\label{prop_intro}
\mbox{}
   \begin{enumerate}[label=\emph{(\arabic*)}]
       \item For $f\in{\mathcal{S}}$, the operator ${\mathbf{T}}_f$ extends to a bounded operator ${\mathcal{H}}\to{\mathcal{H}}$, and the map $f\in{\mathcal{S}}\mapsto{\mathbf{T}}_f$ is a semigroup homomorphism, i.e., for $f_1,f_2\in{\mathcal{S}}$,
        \begin{equation*}
            {\mathbf{T}}_{f_1}\circ{\mathbf{T}}_{f_2}={\mathbf{T}}_{f_1\circ f_2}.
        \end{equation*}
       \item  Let $f\in{\mathcal{S}}$, and let $g_f$ be an admissible metric on the annulus $({\mathbb{A}}_f={\mathbb{D}}\setminus f({\mathbb{D}}^\circ),{\boldsymbol{\zeta}}_f=({\mathrm{id}}_{\mathbb{T}},f|_{\mathbb{T}}))$. Viewing the CILT amplitude ${\mathcal{A}}_{{\mathbb{A}}_f,g_f,{\boldsymbol{\zeta}}_f}$ of $({\mathbb{A}}_f,g_f,{\boldsymbol{\zeta}}_f)$ as an operator $\mathcal H\to\mathcal H$, we have
\[{\mathbf{T}}_f = \frac{e^{-\frac{c_{\mathrm L}}{12} W(f, g_f)}}{\sqrt{2}\pi} {\mathcal{A}}_{{\mathbb{A}}_f,g_f,{\boldsymbol{\zeta}}_f},\]
where $W(f,g_f)$ is defined in \eqref{eq_W_f} and depends on $f$ and $g_f$ only.
\item \emph{(\textbf{Feynman--Kac formula})} Let ${\rm v} = -\sum_{n=0}^\infty v_n z^{n+1} \partial_z$ be a Markovian holomorphic vector field on ${\mathbb{D}}$ such that the coercivity condition \eqref{omega_condition} holds. Then the operator ${\mathbf{H}}_{{\rm v}}$ admits a closed extension that generates a strongly continuous semigroup $t\in{\mathbb{R}}_{\geq0}\mapsto e^{-t{\mathbf{H}}_{\rm v}}$, and we have ${\mathbf{T}}_{f_t} = e^{-t{\mathbf{H}}_{\rm v}}$ for $t>0$, where $t\mapsto f_t$ is the flow generated by ${\rm v}$.

   \end{enumerate}

\label{thm_intro_WARD_CILT}
Let $\Sigma$ be a compact Riemann surface with real-analytic boundary parametrizations ${\boldsymbol{\zeta}}=(\zeta_1,\ldots,\zeta_{\mathfrak{b}})$. Suppose ${\mathfrak{b}}={\mathfrak{b}}^++{\mathfrak{b}}^-$ where $\zeta_j$ is outgoing for $j=1,\ldots,{\mathfrak{b}}^+$ and incoming for $j={\mathfrak{b}}^++1,\ldots,{\mathfrak{b}}$. Let ${\mathbf{z}}=(z_1,\ldots,z_{\mathfrak{s}})$ be distinct marked points on $\Sigma^\circ$, ${\mathbf{v}}=(v_1,\ldots,v_{\mathfrak{s}})$ with $v_j\in T_{z_j}\Sigma\setminus\{0\}$ for each $j$, ${\boldsymbol{\alpha}}=(\alpha_1,\ldots,\alpha_{\mathfrak{s}})\in{\mathbb{R}}^{\mathfrak{s}}$ electric charges such that $\alpha_j>Q$, $\alpha_jR\in{\mathbb{Z}}$ for all $j$, and ${\mathbf{m}}=(m_1,\ldots,m_{\mathfrak{s}})\in{\mathbb{Z}}^{\mathfrak{s}}$ magnetic charges. Let $g$ be an admissible metric on $\Sigma$. We have the amplitude operator ${\mathcal{A}}_{\Sigma,g,{\mathbf{v}},{\boldsymbol{\alpha}},{\mathbf{m}},{\boldsymbol{\zeta}}}:{\mathcal{H}}^{\otimes{\mathfrak{b}}^-}\to{\mathcal{H}}^{\otimes{\mathfrak{b}}^+}$. Finally, let ${\rm w}$ be a holomorphic vector field on $\Sigma$ (analytic up to the boundary). For each $j=1,\ldots,{\mathfrak{b}}$, let ${\rm w}_j:=\zeta_j^*{\rm w}=-\sum_{n\in{\mathbb{Z}}}w_{jn}z^{n+1}\partial_z$, where we extend $\zeta_j$ analytically so that ${\rm w}_j$ is holomorphic on an open neighborhood of ${\mathbb{T}}$. Then the following identity holds:
\begin{align*}
0 &= \sum_{j=1}^{{\mathfrak{b}}^+}{\mathbf{H}}_{{\rm w}_j}^{(j)}{\mathcal{A}}_{\Sigma,g,{\mathbf{v}},{\boldsymbol{\alpha}},{\mathbf{m}},{\boldsymbol{\zeta}}} - \sum_{j=1}^{{\mathfrak{b}}^-}{\mathcal{A}}_{\Sigma,g,{\mathbf{v}},{\boldsymbol{\alpha}},{\mathbf{m}},{\boldsymbol{\zeta}}}{\mathbf{H}}_{{\rm w}_{{\mathfrak{b}}^++j}}^{(j)}
+ \sum_{j=1}^{{\mathfrak{s}}}\left(\Delta_{\alpha_j,m_j}(\operatorname{div}_gW)(z_j)+W_{\mathbf{v}}^{(j)}\right){\mathcal{A}}_{\Sigma,g,{\mathbf{v}},{\boldsymbol{\alpha}},{\mathbf{m}},{\boldsymbol{\zeta}}} \\
&\qquad+ c_{\mathrm{L}}\left(-\sum_{j=1}^{{\mathfrak{b}}^+}\frac{\operatorname{Re} w_{j0}}{12}+\sum_{j={\mathfrak{b}}^++1}^{{\mathfrak{b}}}\frac{\operatorname{Re} w_{j0}}{12}-\frac{1}{96\pi}\int_\Sigma 2K_g\operatorname{div}_gW\,{\mathrm{d}} v_g\right){\mathcal{A}}_{\Sigma,g,{\mathbf{v}},{\boldsymbol{\alpha}},{\mathbf{m}},{\boldsymbol{\zeta}}},
\end{align*}
where ${\mathbf{H}}_{{\rm w}}^{(j)}:={\mathrm{id}}_{\mathcal{H}} \otimes \cdots \otimes \underset{j}{\underbrace{{\mathbf{H}}_{\rm w}}} \otimes \cdots \otimes {\mathrm{id}}_{\mathcal{H}}$ acts on the $j$-th ${\mathcal{H}}$, $W={\rm w}+\bar{{\rm w}}$, and $W_{\mathbf{v}}^{(j)}$ denotes differentiation with respect to $v_j$ in the direction of $W$ at $z_j$. Here ${\mathbf{H}}_{\rm w}$ is defined as in \eqref{intro_H_v}, summing over $n\in{\mathbb{Z}}$.

The dependence of ${\mathcal{A}}_{\Sigma,g,{\mathbf{v}},{\boldsymbol{\alpha}},{\mathbf{m}},{\boldsymbol{\zeta}}}$ on ${\mathbf{v}}$ records the spin $R(\alpha_j-Q)m_j$ at each $z_j$. More precisely, if for ${\boldsymbol{\theta}}=(\theta_1,\ldots,\theta_{\mathfrak{s}})\in{\mathbb{R}}^{\mathfrak{s}}$ we write $e^{{\mathrm{i}}{\boldsymbol{\theta}}}{\mathbf{v}}=(e^{{\mathrm{i}}\theta_1}v_1,\ldots,e^{{\mathrm{i}}\theta_{\mathfrak{s}}}v_{\mathfrak{s}})$, then we have (\cite[Theorem 1.2(3)]{BCILT})
\begin{equation*}
    {\mathcal{A}}_{\Sigma,g,e^{{\mathrm{i}}{\boldsymbol{\theta}}}\boldsymbol{{\rm v}},{\boldsymbol{\alpha}},{\mathbf{m}},{\boldsymbol{\zeta}}}=e^{{\mathrm{i}} R\sum_{j=1}^{\mathfrak{s}}(\alpha_j-Q)m_j\theta_j}{\mathcal{A}}_{\Sigma,g,{\mathbf{v}},{\boldsymbol{\alpha}},{\mathbf{m}},{\boldsymbol{\zeta}}}.
\end{equation*}
In the Ward identity above, the tangent vectors ${\mathbf{v}}$ are also deformed by the flow $f_t$ generated by $\mathrm{w}$. If each $(f_t)_*v_j=e^{\lambda_j(t)}P_{g,j,t}v_j$ where $P_{g,j,t}:T_{z_j}\Sigma\to T_{f_t(z_j)}\Sigma$ is the $g$-parallel transport along $t\mapsto f_t(z_j)$ and $\lambda_j(t)\in{\mathbb{C}}$ depends continuously on $t$, then writing $\theta_j:=\operatorname{Im}\lambda_j$, we have $\partial_t|_{t=0} \theta_j(t)=-\frac12\operatorname{div}_g(JW)(z_j)$, where $JW:={\mathrm{i}} \mathrm{w}-{\mathrm{i}}\bar{\mathrm{w}}$. Thus
\begin{equation*}
    W_{\mathbf{v}}^{(j)}{\mathcal{A}}_{\Sigma,g,{\mathbf{v}},{\boldsymbol{\alpha}},{\mathbf{m}},{\boldsymbol{\zeta}}}=-\frac{\mathrm{i}}2 R(\alpha_j-Q)m_j (\operatorname{div}_g(J W))(z_j){\mathcal{A}}_{\Sigma,g,{\mathbf{v}},{\boldsymbol{\alpha}},{\mathbf{m}},{\boldsymbol{\zeta}}}+W_{\mathbf{z}}^{(j)}{\mathcal{A}}_{\Sigma,g,{\mathbf{v}},{\boldsymbol{\alpha}},{\mathbf{m}},{\boldsymbol{\zeta}}},
\end{equation*}
where $W_{\mathbf{z}}^{(j)}$ denotes differentiation with respect to the marked point $z_j$ while parallel transporting $v_j$.

\label{prop_semigroup_as_amplitude}
Let $f\in{\mathcal{S}}$. Let $g_{\mathbb{A}}:=|dz|^2/|z|^2$ and $g_f$ an admissible metric on the annulus $({\mathbb{A}}_f,{\boldsymbol{\zeta}}_f)$. Viewing the CILT amplitude ${\mathcal{A}}_{{\mathbb{A}}_f,g_f,{\boldsymbol{\zeta}}_f}$ of $({\mathbb{A}}_f,g_f,{\boldsymbol{\zeta}}_f)$ as an operator $L^2({\mathcal{D}}'({\mathbb{T}},{\mathbb{T}}_R))\to L^2({\mathcal{D}}'({\mathbb{T}},{\mathbb{T}}_R))$, we have
\[{\mathbf{T}}_f = \frac{e^{-\frac{c_{\mathrm L}}{12} W(f, g_f)}}{\sqrt{2}\pi} {\mathcal{A}}_{{\mathbb{A}}_f,g_f,{\boldsymbol{\zeta}}_f},\]
where
\begin{equation}\label{eq_W_f}
    W(f,g_f) := -\log|f'(0)| - \left\langle{\mathbf{D}}\log\tfrac{|f'|}{|f|}\big|_{\mathbb{T}},\log\tfrac{|f'|}{|f|}\big|_{\mathbb{T}}\right\rangle - 12S_{\mathrm L}^0({\mathbb{A}}_f,g_f,g_{\mathbb{A}}).
\end{equation}
Here the bracket $\langle\cdot,\cdot\rangle$ on $L^2({\mathbb{T}})$ is defined by $\langle u,v\rangle:=\frac{1}{2\pi}\int_{\mathbb{T}} u\bar{v}\,{\mathrm{d}}\theta$.

\label{HilleYosida_lemma}
Let $({\mathcal{H}},\langle\cdot,\cdot\rangle_{{\mathcal{H}}})$ be a complex Hilbert space and ${\mathcal{Q}}_0:{\mathcal{D}}({\mathcal{Q}}_0)\times {\mathcal{D}}({\mathcal{Q}}_0)\to{\mathbb{C}}$ a closed positive symmetric quadratic form on ${\mathcal{H}}$ with dense domain ${\mathcal{D}}({\mathcal{Q}}_0)\subset{\mathcal{H}}$. Let ${\mathcal{Q}}:{\mathcal{D}}({\mathcal{Q}}_0)\times{\mathcal{D}}({\mathcal{Q}}_0)\to{\mathbb{C}}$ be a (nonsymmetric) quadratic form defined on the domain ${\mathcal{D}}({\mathcal{Q}}_0)$ of ${\mathcal{Q}}_0$. Suppose that there exists $C>0$ such that
\begin{equation}\label{sectorial_property}
\operatorname{Re}{\mathcal{Q}}(u,u)\geq C^{-1}{\mathcal{Q}}_0(u,u),\qquad |{\mathcal{Q}}(u,u)|\leq C{\mathcal{Q}}_0(u,u),\qquad \forall\, u\in{\mathcal{D}}({\mathcal{Q}}_0).
\end{equation}
Then the following hold:
\begin{enumerate}[label=\emph{(\arabic*)}]
    \item There exists a unique closed operator ${\mathbf{H}}:{\mathcal{D}}({\mathbf{H}})\subset{\mathcal{H}}\to{\mathcal{H}}$ with domain $${\mathcal{D}}({\mathbf{H}})=\{u\in{\mathcal{D}}({\mathcal{Q}}_0):\overline{{\mathcal{Q}}(u,\cdot)}\text{ is bounded }{\mathcal{H}}\to{\mathbb{C}}\},$$ such that ${\mathcal{Q}}(u,v)=\langle {\mathbf{H}} u,v\rangle_{{\mathcal{H}}}$ for $u\in{\mathcal{D}}({\mathbf{H}})$, $v\in{\mathcal{D}}({\mathcal{Q}}_0)$. Moreover, ${\mathbf{H}}$ extends to a bounded operator ${\mathcal{D}}({\mathcal{Q}}_0)\to{\mathcal{D}}'({\mathcal{Q}}_0)$, where ${\mathcal{D}}'({\mathcal{Q}}_0)\supset{\mathcal{H}}$ is the dual space of ${\mathcal{D}}({\mathcal{Q}}_0)$ equipped with the norm $\|u\|_{{\mathcal{D}}({\mathcal{Q}}_0)}:=\sqrt{{\mathcal{Q}}_0(u,u)}$.
    \item The operator ${\mathbf{H}}$ generates a strongly continuous contraction semigroup $t\mapsto e^{-t{\mathbf{H}}}$ ($t\geq0$) on ${\mathcal{H}}$. Moreover, for $t>0$, the bounded operator $e^{-t{\mathbf{H}}}$ on ${\mathcal{H}}$ extends to a bounded operator ${\mathcal{D}}'({\mathcal{Q}}_0)\to{\mathcal{D}}({\mathcal{Q}}_0)$.
\end{enumerate}

\label{L_n^0_estimate}
There exists a constant $C>0$ (depending only on $Q$ and $R$) such that for all $n\in{\mathbb{Z}}$ and all $F,G\in{\mathcal{E}}({\mathcal{D}}'({\mathbb{T}},{\mathbb{T}}_R))$, we have
\begin{equation*}
    |\langle\mathbf L^0_nF,G\rangle_{L^2}|\leq C(1+|n|)\sqrt{\widetilde{{\mathcal{Q}}}^0(F,F)\widetilde{{\mathcal{Q}}}^0(G,G)}.
\end{equation*}
In particular, $\mathbf L_n^0$ extends to a bounded operator ${\mathcal{D}}(\widetilde{{\mathcal{Q}}}^0)\to{\mathcal{D}}'(\widetilde{{\mathcal{Q}}}^0)$. The same holds for $\widetilde{\mathbf L}_n^0$.

Since $(\mathbf L_n^{0,\beta})^*=\mathbf L_{-n}^{0,-\beta}$ and $\mathbf H^0=\mathbf L^{0}_0+\widetilde{\mathbf L}^0_0$, it suffices to consider the case $n> 0$.




 Recall \eqref{Qtilde0}, \eqref{eq_L} and that ${\mathbf{A}}_0=\tfrac{{\mathrm{i}}}{2}\partial_c- \frac12Q- \frac12Rk$. By Cauchy-Schwarz inequalities, we have
    \begin{equation*}
    \begin{split}
        |\langle\mathbf L^0_nF,G\rangle_2|={}&\left|(n+1)Q\langle\mathbf{A}_nF,G\rangle_2+2\langle\mathbf A_0\mathbf{A}_nF,G\rangle_2+\sum_{j=1}^{n-1}\langle\mathbf{A}_{n-j}F,\mathbf{A}_{-j}G\rangle_2+2\sum_{l\geq1}\langle\mathbf A_{n+l}F,\mathbf A_{l}G\rangle_2\right|\\
        \leq{}&\left(\ \|\mathbf A_nF\|_2^2+\|\partial_cF\|_2^2+\sum_{j=1}^{n-1}\|\mathbf A_j F\|^2_2+2\sum_{l\geq1}\|\mathbf A_{n+l}F\|_2^2\right)^{\frac12}\\
        &\times\left(\|(nQ-Rk)G\|_2^2+\|\mathbf A_{-n}G\|_2^2+\sum_{j=1}^{n-1}\|\mathbf A_{-j} G\|^2_2+2\sum_{l\geq1}\|\mathbf A_{l}G\|_2^2\right)^{\frac12}.
    \end{split}       
    \end{equation*}
  The second line above is bounded by $C\sqrt{\widetilde{{\mathcal{Q}}}^0(F,F)}$. Using $[\mathbf{A}_j,\mathbf{A}_{-j}]=\frac j2$, we obtain $\|A_{-j} G\|^2_2=\|A_{j} G\|^2_2+\frac j2\|G\|_2^2$. Thus
  \begin{equation*}
      \begin{split}
          &\left(\|(nQ-Rk)G\|_2^2+\|\mathbf A_{-n}G\|_2^2+\sum_{j=1}^{n-1}\|\mathbf A_{-j} G\|^2_2+2\sum_{l\geq1}\|\mathbf A_{l}G\|_2^2\right)^{\frac12}\\
          ={}&\left(\left(|nQ-Rk|^2+\frac{n(n+1)}{4}\right)\|G\|_2^2+\sum_{j=1}^{n}\|\mathbf A_{j} G\|^2_2+2\sum_{l\geq1}\|\mathbf A_{l}G\|_2^2\right)^{\frac12},
      \end{split}
  \end{equation*}
  where the last line is bounded by $Cn\sqrt{\widetilde{{\mathcal{Q}}}^0(G,G)}$.

\label{prop_FK_free}
Let ${\rm v} = -\sum_{n=0}^\infty v_n z^{n+1} \partial_z$ be a Markovian holomorphic vector field on ${\mathbb{D}}$ such that \eqref{omega_condition} holds. Let $t\mapsto f_t$ be the flow generated by ${\rm v}$. For $t>0$, we have ${\mathbf{T}}_{f_t}^0 = e^{-t{\mathbf{H}}_{\rm v}^0}$, i.e.,
\[(e^{-t{\mathbf{H}}_{\rm v}^0}F)(\widetilde{\varphi}^k) = |f_t'(0)|^{\frac{R^2k^2-Q^2}2} \,{\mathbb{E}}\left[F\left((P\widetilde{\varphi}^k+X_{\mathbb{D}})\circ f_t\big|_{\mathbb{T}} + {\mathrm{i}} Q\log\tfrac{|f_t'|}{|f_t|}\big|_{\mathbb{T}}\right)\right].\]

\label{V_v_estimate}
Let $N\geq0$. For $F,G\in{\mathcal{E}}({\mathcal{D}}'({\mathbb{T}},{\mathbb{T}}_R))$, we have
           \begin{equation}\label{eq_V_bound}
           \begin{split}
               \sup_{0<\delta<1}|\langle V^{(\delta)}_{\rm v} F,G\rangle_{L^2}|\leq {}&C\, (N+Q^2/2)^{\frac{\beta^2}{2}-1} \\
               &\sup_{\theta\in[0,2\pi]}|\operatorname{Re}(e^{-{\mathrm{i}}\theta}v(e^{{\mathrm{i}}\theta}))|\sqrt{(N\|F\|_{L^2}^2+\widetilde{\mathcal Q}^0(F,F))(N\|G\|_{L^2}^2+\widetilde{\mathcal Q}^0(G,G))},
           \end{split}
    \end{equation}
where $C>0$ only depends on $\beta$. In particular, $V_{\rm v}$ extends to a bounded operator ${\mathcal{D}}(\widetilde{{\mathcal{Q}}}^0)\to{\mathcal{D}}'(\widetilde{{\mathcal{Q}}}^0)$.

\label{Q_v_bound}
Suppose \eqref{omega_condition} holds. Then there exist $N,C>0$ (depending on ${\rm v}$) such that
\[\operatorname{Re}({\mathcal{Q}}_{\rm v}+N\|\!\cdot\!\|_2^2)\geq C^{-1}\widetilde{{\mathcal{Q}}}^0,\qquad|{\mathcal{Q}}_{\rm v}+N\|\!\cdot\!\|_2^2|\leq C\widetilde{{\mathcal{Q}}}^0.\]

\label{prop_FK_formula}
Let ${\rm v} = -\sum_{n=0}^\infty v_n z^{n+1} \partial_z$ be a Markovian holomorphic vector field on ${\mathbb{D}}$ such that \eqref{omega_condition} holds. Let $t\mapsto f_t$ be the flow generated by ${\rm v}$. For $t>0$, we have ${\mathbf{T}}_{f_t} = e^{-t{\mathbf{H}}_{\rm v}}$, i.e.,
\[(e^{-t{\mathbf{H}}_{\rm v}}F)(\widetilde{\varphi}^k) = |f_t'(0)|^{\frac{R^2k^2-Q^2}2} \,{\mathbb{E}}_{\widetilde{\varphi}^k}\left[F\left((P\widetilde{\varphi}^k+X_{\mathbb{D}})\circ f_t\big|_{\mathbb{T}} + {\mathrm{i}} Q\log\tfrac{|f_t'|}{|f_t|}\big|_{\mathbb{T}}\right)\,e^{-\mu\int_{{\mathbb{A}}_{f_t}}|x|^{\beta Q}M_\beta(P\widetilde{\varphi}^k+X_{\mathbb{D}},{\mathrm{d}} x)}\right].\]

We follow the proof in \cite[Theorem 3.1]{Virasoro_structure} and \cite[Section 5.2]{Guillarmou2024}. Denote by $X:=c + P\varphi + kR\arg+X_{\mathbb{D}}$ the GFF restricted to the disk and $X_\varepsilon:=\frac1{2\pi}\int_0^{2\pi}X(x+\varepsilon e^{{\mathrm{i}}\theta}) {\mathrm{d}}\theta$ its regularisation. Pulling back by the diffeomorphism $[0,t]\times[0,2\pi]\mapsto{\mathbb{A}}_{f_t}, (s,\theta)\mapsto f_s(e^{{\mathrm{i}}\theta})$, we get by change of variables
\begin{equation}\label{eq_FK_1}
    \int_{{\mathbb{A}}_{f_t}}|x|^{\beta Q} \varepsilon^{-\beta^2/2}e^{{\mathrm{i}}\beta X_\varepsilon(x)}\ {\mathrm{d}} x=-\int_{0}^t\int_0^{2\pi} \varepsilon^{-\beta^2/2}|f_s(e^{{\mathrm{i}}\theta})|^{\beta Q}e^{{\mathrm{i}}\beta X_\varepsilon(f_s(e^{{\mathrm{i}}\theta}))}\operatorname{Re}\left(e^{-{\mathrm{i}}\theta}v(f_s(e^{{\mathrm{i}}\theta}))\overline{f_s'(e^{{\mathrm{i}}\theta})}\right)\ {\mathrm{d}}\theta{\mathrm{d}} s
\end{equation}
When $\varepsilon\to0$, as a consequence of the uniqueness of GMC, we have
\begin{equation*}
    \varepsilon^{-\beta^2/2}e^{{\mathrm{i}}\beta X_\varepsilon(f_s(e^{{\mathrm{i}}\theta}))}{\mathrm{d}}\theta{\mathrm{d}} s\approx \varepsilon_{s,\theta}^{-\beta^2/2} e^{{\mathrm{i}}\beta (X\circ f_s)_{\varepsilon_{s,\theta}}(e^{{\mathrm{i}}\theta})}|f'_s(e^{{\mathrm{i}}\theta})|^{-\frac{\beta^2}{2}}{\mathrm{d}}\theta{\mathrm{d}} s,
\end{equation*}
where $\varepsilon_{s,\theta}=\varepsilon/|f'_s(e^{{\mathrm{i}}\theta})|$. Hence, the right hand side of \eqref{eq_FK_1} can be written as
\begin{equation*}
    -\int_{0}^t\int_0^{2\pi} \varepsilon_{s,\theta}^{-\beta^2/2} e^{{\mathrm{i}}\beta ((X\circ f_s)_{\varepsilon_{s,\theta}}(e^{{\mathrm{i}}\theta})+{\mathrm{i}} Q\log\frac{|f'_s(e^{{\mathrm{i}}\theta})|}{|f_s(e^{{\mathrm{i}}\theta})|})}\operatorname{Re}\left(\frac{e^{-{\mathrm{i}}\theta}v(f_s(e^{{\mathrm{i}}\theta}))}{f'_s(e^{{\mathrm{i}}\theta})}\right)\ {\mathrm{d}}\theta{\mathrm{d}} s.
\end{equation*}
By changing the cutoff $\varepsilon_{s,\theta}$ and using \cite[Lemma 2.4]{Virasoro_structure}, we have
\begin{equation}\label{eq_Aft2V}
     \int_{{\mathbb{A}}_{f_t}}|x|^{\beta Q} e^{{\mathrm{i}}\beta X(x)}\ {\mathrm{d}} x=-\lim_{\varepsilon\to0} \int_{0}^t\int_0^{2\pi} \varepsilon^{-\beta^2/2} e^{{\mathrm{i}}\beta ((X\circ f_s)_{\varepsilon}(e^{{\mathrm{i}}\theta})+{\mathrm{i}} Q\log\frac{|f'_s(e^{{\mathrm{i}}\theta})|}{|f_s(e^{{\mathrm{i}}\theta})|})}\operatorname{Re}\left(e^{-{\mathrm{i}}\theta}v(e^{{\mathrm{i}}\theta})\right)\ {\mathrm{d}}\theta{\mathrm{d}} s.
\end{equation}


\begin{lemma}
    For $F,G\in{\mathcal{E}}({\mathcal{D}}'({\mathbb{T}},{\mathbb{T}}_R)) $, $\lim_{t\to0}t^{-1}\langle F-{\mathbf{T}}_{f_t}F,G\rangle_{L^2}=\langle \mathbf H_{\rm v} F,G\rangle_{L^2}$.
\end{lemma}
\begin{proof}
By definition of ${\mathcal{E}}({\mathcal{D}}'({\mathbb{T}},{\mathbb{T}}_R))$, we can assume $F,G$ depend on a finite number of Fourier modes of GFF in terms of polynomials. Similar to the proof in \cite[Lemma 5.4]{Guillarmou2024}, and using the definition of the semigroup ${\mathbf{T}}_{f_t}$ \eqref{eq_def_T_f}, $\langle F-{\mathbf{T}}_{f_t}F,G\rangle_{L^2}$ is just
  \begin{equation}\label{eq_diff_T_f}
   \int_{0}^{2\pi R}{\mathrm{d}} c\ {\mathbb{E}}\left[\left(F(\widetilde{\varphi}^k)-|f_t'(0)|^{\frac{R^2k^2-Q^2}2} F\left((P\widetilde{\varphi}^k+X_{\mathbb{D}})\circ f_t\big|_{\mathbb{T}} + {\mathrm{i}} Q\log\tfrac{|f_t'|}{|f_t|}\big|_{\mathbb{T}}\right)\,e^{-\mu\int_{{\mathbb{A}}_{f_t}}|x|^{\beta Q}M_\beta(P\widetilde{\varphi}^k+X_{\mathbb{D}},{\mathrm{d}} x)}\right)\,\overline{G}(\widetilde{\varphi}^k)\right].
  \end{equation}
In the following proof, denote by $X$ the field on the disk $P\widetilde{\varphi}^k+X_{\mathbb{D}}$. Recall that the GFF part $P{\varphi}+X_{\mathbb{D}}$ has covariance $-\log|x-x'|,\forall x,x'\in\mathbb D$. Since $F,G\in{\mathcal{E}}({\mathcal{D}}'({\mathbb{T}},{\mathbb{T}}_R)) $, we have $\mathbb E[|F(\widetilde{\varphi}^k)G(\widetilde{\varphi}^k)|^n]<\infty$ for arbitrary $n$.

According to \cref{prop_FK_free}, \eqref{eq_diff_T_f} is further written as
  \begin{equation*}
  \begin{split}
   &t{\mathcal{Q}}_{\rm v}^0(F,G)+o(t)+\int_{0}^{2\pi R}{\mathrm{d}} c\ {\mathbb{E}}\left[F(\widetilde{\varphi}^k)\,\overline{G}(\widetilde{\varphi}^k)\,\left(1-e^{-\mu\int_{{\mathbb{A}}_{f_t}}|x|^{\beta Q}M_\beta(X,{\mathrm{d}} x)}\right)\right]+\\
      &\int_{0}^{2\pi R}{\mathrm{d}} c\ {\mathbb{E}}\left[\left(F(\widetilde{\varphi}^k)-|f_t'(0)|^{\frac{R^2k^2-Q^2}2}F\left(X\circ f_t\big|_{\mathbb{T}} + {\mathrm{i}} Q\log\tfrac{|f_t'|}{|f_t|}\big|_{\mathbb{T}}\right)\right)\,\overline{G}(\widetilde{\varphi}^k)\,\left(e^{-\mu\int_{{\mathbb{A}}_{f_t}}|x|^{\beta Q}M_\beta(X,{\mathrm{d}} x)}-1\right)\right]\\
      &=:t{\mathcal{Q}}_{\rm v}^0(F,G)+o(t)+D_t^{(1)}+D_t^{(2)}.
  \end{split}
  \end{equation*}
In the following we will prove $t^{-1}D_t^{(1)}\to \mu\langle V_{\rm v} F,G\rangle$ and $t^{-1}D_t^{(2)}\to 0$.

For $D_t^{(1)}$, we expand the exponential of GMC then we have

  \begin{equation*}
  \begin{split}
      D_t^{(1)}={}&-\int_{0}^{2\pi R}{\mathrm{d}} c\ {\mathbb{E}}\left[F(\widetilde{\varphi}^k)\,\overline{G}(\widetilde{\varphi}^k)\,\sum_{n\geq1}\frac{(-\mu)^n}{n!}\left(\int_{{\mathbb{A}}_{f_t}}|x|^{\beta Q}M_\beta(X,{\mathrm{d}} x)\right)^n\right].
  \end{split}
  \end{equation*}
  Now we apply the imaginary Cameron--Martin theorem to each term in the summation for a single vertex insertion, and we get

  \begin{equation*}
      \begin{split}
      D_t^{(1)}={}&-\int_{0}^{2\pi R}\int_{{\mathbb{A}}_{f_t}}e^{{\mathrm{i}}\beta c+{\mathrm{i}}\beta Rk\arg y}\\ &\ \ \ \ \ \ \ \ \ \ \ \ \ \ {\mathbb{E}}\left[F_{\text{shift}}(y,\widetilde{\varphi}^k)\,(\overline{G})_{\text{shift}}(y,\widetilde{\varphi}^k)\,\sum_{n\geq1}\frac{(-\mu)^n}{n!}\left(\int_{{\mathbb{A}}_{f_t}}|x|^{\beta Q}|x-y|^{\beta^2}M_\beta(X,{\mathrm{d}} x)\right)^{n-1}\right]|y|^{\beta Q}\,{\mathrm{d}} y\,{\mathrm{d}} c\\
      ={}& \mu\int_{0}^{2\pi R}\int_{{\mathbb{A}}_{f_t}}e^{{\mathrm{i}}\beta c+{\mathrm{i}}\beta Rk\arg y}\ {\mathbb{E}}\left[F_{\text{shift}}(y,\widetilde{\varphi}^k)\,(\overline{G})_{\text{shift}}(y,\widetilde{\varphi}^k)\right]|y|^{\beta Q}\,{\mathrm{d}} y\,{\mathrm{d}} c-\int_{0}^{2\pi R}\int_{{\mathbb{A}}_{f_t}}e^{{\mathrm{i}}\beta c+{\mathrm{i}}\beta Rk\arg y}\\ &\ \  \ \ \ \ \ \ \ \ \ {\mathbb{E}}\left[F_{\text{shift}}(y,\widetilde{\varphi}^k)\,(\overline{G})_{\text{shift}}(y,\widetilde{\varphi}^k)\,\sum_{n\geq2}\frac{(-\mu)^n}{n!}\left(\int_{{\mathbb{A}}_{f_t}}|x|^{\beta Q}|x-y|^{\beta^2}M_\beta(X,{\mathrm{d}} x)\right)^{n-1}\right]|y|^{\beta Q}\,{\mathrm{d}} y\,{\mathrm{d}} c,
  \end{split}
  \end{equation*}
where
\begin{equation*}
    F_{\text{shift}}(y,\widetilde{\varphi}^k):=F(\widetilde{\varphi}^k+{\mathrm{i}}\beta K_y),\ \ \ K_{r e^{{\mathrm{i}}\theta'}}(\theta):=\sum_{n\geq1}\frac{|r|^n}{n}\cos(n(\theta-\theta')).
\end{equation*}

For $t$ small enough, ${\mathbb{A}}_{f_t}$ are always the subset of some annulus $\{z:q<|z|<1\},q<1$. Define
\begin{equation*}
    I_t(y):=\left|{\mathbb{E}}\left[F_{\text{shift}}(y,\widetilde{\varphi}^k)\,(\overline{G})_{\text{shift}}(y,\widetilde{\varphi}^k)\,\sum_{n\geq2}\frac{(-\mu)^n}{n!}\left(\int_{{\mathbb{A}}_{f_t}}|x|^{\beta Q}|x-y|^{\beta^2}M_\beta(X,{\mathrm{d}} x)\right)^{n-1}\right]\right|,
\end{equation*}
and we claim that
\begin{equation}\label{eq_FK_claim}
    \lim_{t\to0}\sup_{q<|y|<1}   I_t(y)=0,
\end{equation}
which would imply $t^{-1}D_t^{(1)}-\mu\langle V_{\rm v} F,G\rangle\approx t^{-1}\int_{{\mathbb{A}}_{f_t}}  I_t(y)|y|^{\beta Q}{\mathrm{d}} y\to 0$.
To prove \eqref{eq_FK_claim}, we first apply the Cauchy-Schwarz inequality and obtain
\begin{equation*}
\begin{split}
    &I_t^2(y)\leq{\mathbb{E}}[|\int_{{\mathbb{A}}_{f_t}}|x|^{\beta Q}|x-y|^{\beta^2}M_\beta(X,{\mathrm{d}} x)|^{2}]\times\\
    &{\mathbb{E}}\left[\left|F_{\text{shift}}(y,\widetilde{\varphi}^k)\,(\overline{G})_{\text{shift}}(y,\widetilde{\varphi}^k)\,\sum_{n\geq2}\frac{(-\mu)^n}{n!}\left(\int_{{\mathbb{A}}_{f_t}}|x|^{\beta Q}|x-y|^{\beta^2}M_\beta(X,{\mathrm{d}} x)\right)^{n-2}\right|^2\right].
\end{split}
\end{equation*}
Since $|\sum_{n\geq2}\frac{(-\mu)^n}{n!}z^{n-2}|\leq|\mu|^2\sum_{n\geq0}\frac{|\mu z|^n}{(n+2)!}\leq |\mu|^2e^{|\mu z|}$, the second term above is further bounded, using Cauchy-Schwarz inequality, up to a constant depending on $\mu$ by
\begin{equation*}
    {\mathbb{E}}[|F_{\text{shift}}(\overline{G})_{\text{shift}}|^4]^{\frac12}{\mathbb{E}}[\exp(4|\mu||\int_{{\mathbb{A}}_{f_t}}|x|^{\beta Q}|x-y|^{\beta^2}M_\beta(X,{\mathrm{d}} x)|)]^{\frac12}.
\end{equation*}
For some constant $C$ independent of $t$ small enough, we have $\sup_{q<|y|<1}\mathbb E[|F_{\text{shift}}(\overline{G})_{\text{shift}}|^4]<C$ (since the Fourier modes of $K_y(\theta)$ are under control). According to \cite[Proposition 5.3]{CILT}, for some constant $C$ only depending on $\beta$, the exponential moment is bounded by
\begin{equation*}
    e^{C|\mu|}(1+2|\mu| u e^{C|\mu|^2 u^2}),
\end{equation*}
where
\begin{equation}\label{eq_metric_integral}
    u^2:=\iint_{({\mathbb{A}}_{f_t})^2}|x|^{\beta Q}|x-y|^{\beta^2}|x'|^{\beta Q}|x'-y|^{\beta^2}|x-x'|^{-\beta^2}\ {\mathrm{d}} x\, {\mathrm{d}} x'.
\end{equation}
Hence ${\mathbb{E}}[\exp(C|\int_{{\mathbb{A}}_{f_t}}|x|^{\beta Q}|x-y|^{\beta^2}M_\beta(X,{\mathrm{d}} x)|)]$ is finite and uniformly bounded in $q<|y|<1$ and $t$ small enough. Then the study of $I_t^2$ boils down to the second moment
\begin{equation*}
    {\mathbb{E}}[|\int_{{\mathbb{A}}_{f_t}}|x|^{\beta Q}|x-y|^{\beta^2}M_\beta(X,{\mathrm{d}} x)|^{2}]\leq\iint_{({\mathbb{A}}_{f_t})^2}|x|^{\beta Q}|x-y|^{\beta^2}|x'|^{\beta Q}|x'-y|^{\beta^2}|x-x'|^{-\beta^2}\ {\mathrm{d}} x\, {\mathrm{d}} x',
\end{equation*}
which goes to $0$ uniformly in $y$ as $t\to0$. 

Therefore \eqref{eq_FK_claim} is proved and we just have
 \begin{equation*}
      \begin{split}
      \lim_{t\to0}t^{-1}D_t^{(1)} &=   \lim_{t\to0}t^{-1}\mu\int_{0}^{2\pi R}\int_{{\mathbb{A}}_{f_t}}e^{{\mathrm{i}}\beta c+{\mathrm{i}}\beta Rk\arg y}\ {\mathbb{E}}\left[F_{\text{shift}}(y,\widetilde{\varphi}^k)\,(\overline{G})_{\text{shift}}(y,\widetilde{\varphi}^k)\right]|y|^{\beta Q}\,{\mathrm{d}} y\,{\mathrm{d}} c\\
      &=-\lim_{t\to0}t^{-1}\mu\int_{0}^{2\pi R}\int_0^t\int_0^{2\pi}e^{{\mathrm{i}}\beta c+{\mathrm{i}}\beta Rk\arg f_s(e^{{\mathrm{i}}\theta})}\ {\mathbb{E}}\left[F_{\text{shift}}(f_s(e^{{\mathrm{i}}\theta}),\widetilde{\varphi}^k)\,(\overline{G})_{\text{shift}}(f_s(e^{{\mathrm{i}}\theta}),\widetilde{\varphi}^k)\right]\\
      &\ \ \ \ \ \ \ \ \ \  \ \ \ \ \ \ \ \ \ \ \  \ \ \ \ \ \ \ \ \ |f_s(e^{{\mathrm{i}}\theta})|^{\beta Q}|f_s'(e^{{\mathrm{i}}\theta})|^2\operatorname{Re}\left(e^{-{\mathrm{i}}\theta}v(e^{{\mathrm{i}}\theta})\right)\, {\mathrm{d}}\theta{\mathrm{d}} s\ {\mathrm{d}} c\\
      &=-\mu\int_{0}^{2\pi R}\int_0^{2\pi}e^{{\mathrm{i}}\beta c+{\mathrm{i}}\beta Rk\theta}\ {\mathbb{E}}\left[F_{\text{shift}}(e^{{\mathrm{i}}\theta},\widetilde{\varphi}^k)\,(\overline{G})_{\text{shift}}(e^{{\mathrm{i}}\theta},\widetilde{\varphi}^k)\operatorname{Re}\left(e^{-{\mathrm{i}}\theta}v(e^{{\mathrm{i}}\theta})\right)\right]\ {\mathrm{d}}\theta\, {\mathrm{d}} c,
  \end{split}
  \end{equation*}
  where we used \eqref{eq_Aft2V} for the second line.

  Finally, we can focus on how $t^{-1}D_t^{(2)}$ goes to $0$. We can replace $F_{\text{shift}}$ in \eqref{eq_FK_claim} with
  \begin{equation*}
      F_{\text{shift}}(y,\widetilde{\varphi}^k)-|f_t'(0)|^{\frac{R^2k^2-Q^2}2}F\left(X\circ f_t\big|_{\mathbb{T}} +{\mathrm{i}}\beta K_{t,y}+ {\mathrm{i}} Q\log\tfrac{|f_t'|}{|f_t|}\big|_{\mathbb{T}}\right),\ \ K_{t,y}(\theta):=-\log|f_t(e^{{\mathrm{i}}\theta})-y|
  \end{equation*}as long as the second moment is still uniformly bounded in $y$ and $t$. Indeed, we have the free field semigroup $\|F\left(X\circ f_t\big|_{\mathbb{T}} +{\mathrm{i}}\beta K_{t,y}+ {\mathrm{i}} Q\log\tfrac{|f_t'|}{|f_t|}\big|_{\mathbb{T}}\right)\|_{L^2}\leq Ce^{Ct}\|F_{\text{shift}}\left(y,\widetilde{\varphi}^k\right)\|_{L^2}$ for some constant independent of $y$ and $t$. Since $f_t\to{\mathrm{id}}$, we have $\sup_{y\in{\mathbb{A}}_{f_t}}|\langle K_{t,y}-K_y,h\rangle|\to0$ for every $h\in C^\infty({\mathbb{T}})$. Thus
  \begin{equation*}
      \begin{split}
      \lim_{t\to0}t^{-1}D_t^{(2)} = -&  \lim_{t\to0}t^{-1}\mu\int_{0}^{2\pi R}\int_{{\mathbb{A}}_{f_t}}e^{{\mathrm{i}}\beta c+{\mathrm{i}}\beta Rk\arg y}\ \\
      &{\mathbb{E}}\left[\left(F_{\text{shift}}(y,\widetilde{\varphi}^k)-|f_t'(0)|^{\frac{R^2k^2-Q^2}2}F\left(X\circ f_t\big|_{\mathbb{T}} +{\mathrm{i}}\beta K_{t,y}+ {\mathrm{i}} Q\log\tfrac{|f_t'|}{|f_t|}\big|_{\mathbb{T}}\right)\right)\,(\overline{G})_{\text{shift}}(y,\widetilde{\varphi}^k)\right]|y|^{\beta Q}\, {\mathrm{d}} y\,{\mathrm{d}} c,
  \end{split}
  \end{equation*}
  where we can use Cauchy Schwarz inequality and \cite[Lemma 2.6, equation (2.27)]{Virasoro_structure} to conclude that $\lim_{t\to0}t^{-1}D_t^{(2)}=0$ and the proof is complete. 

\end{proof}
The above lemma says the quadratic form from the semigroup $\mathbf T_{f_t}$ is equal to ${\mathcal{Q}}_{\rm v}$ for $F,G\in{\mathcal{E}}({\mathcal{D}}'({\mathbb{T}},{\mathbb{T}}_R))$. Then we just need to prove the resolvents of $\mathbf T_{f_t}$ and ${\mathcal{Q}}_{\rm v}$ are the same.

Define \begin{equation*}
    {\mathcal{Q}}_{\rm v}^{(\delta)}(F,G):={\mathcal{Q}}_{\rm v}^0(F,G)+\mu\langle V_{\rm v}^{(\delta)}F,G\rangle_{L^2}.
\end{equation*}
Since $V_{\rm v}^{(\delta)}$ is bounded when $\delta$ is fixed, we can define the operator $\mathbf H^{(\delta)}_{{\rm v}}:=\mathbf H^0_{{\rm v}}+\mu V_{\rm v}^{(\delta)}$ associated with $ {\mathcal{Q}}_{\rm v}^{(\delta)}(F,G)$. Then using the Trotter product formula \cite[Exercise 5.11 in Chapter III]{EN} and the fact that $V_{\rm v}^{(\delta)}$ is bounded, one can obtain the following formula by following the proof of \cite[Proposition 5.3]{Guillarmou2024}
\begin{equation}\label{eq_FK_cutoff}
    e^{-t\mathbf H^{(\delta)}_{{\rm v}}}F=|f_t'(0)|^{\frac{R^2k^2-Q^2}2} \,{\mathbb{E}}_{\widetilde{\varphi}^k}\left[F\left((P\widetilde{\varphi}^k+X_{\mathbb{D}})\circ f_t\big|_{\mathbb{T}} + {\mathrm{i}} Q\log\tfrac{|f_t'|}{|f_t|}\big|_{\mathbb{T}}\right)\,e^{-\mu\int_0^t V^{(\delta)}_{\rm v}((P\widetilde{\varphi}^k+X_{\mathbb{D}})\circ f_s + {\mathrm{i}} Q\log\tfrac{|f_s'|}{|f_s|}){\mathrm{d}} s}\right].
\end{equation}

















We follow the strategy in \cite[Proposition 5.5]{Guillarmou2024}. First we have the representation of the resolvent
\begin{equation*}
    \mathbf R_{{\rm v},\lambda}F:=\int_0^{\infty} e^{-\lambda t}\mathbf T_{f_t}F\ {\mathrm{d}} t,\ \ \ \ \mathbf R_{{\rm v},\lambda}^{(\delta)}F:=\int_0^{\infty} e^{-\lambda t}e^{-t\mathbf H^{(\delta)}_{{\rm v}}}F\ {\mathrm{d}} t.
\end{equation*}
Note that $\|\mathbf T_{f_t}F\|\leq e^{Ct}\|F\|$ (see \cref{lemma_gmc_delta_exp_bound} below) so $\mathbf R_{{\rm v},\lambda}F$ is well-defined if we consider $\lambda$ large enough. Now we want to show that $\mathbf R_{{\rm v},\lambda}^{(\delta)}F$ converges to $\mathbf R_{{\rm v},\lambda}F$ in $L^2({\mathcal{D}}'({\mathbb{T}},{\mathbb{T}}_R))$. Using Cauchy-Schwarz inequality, we have
\begin{equation*}
    \int_{0}^{2\pi R}\mathbb E|\mathbf R_{{\rm v},\lambda}F-\mathbf R_{{\rm v},\lambda}^{(\delta)}F|^2\ {\mathrm{d}} c\leq C\int_{0}^{2\pi R}\int_0^{\infty} e^{-\lambda t}\ \mathbb E|(e^{-t\mathbf H_{\rm v} }-e^{-t\mathbf H^{(\delta)}_{{\rm v}}})F|^2\ {\mathrm{d}} t{\mathrm{d}} c.
\end{equation*}
Then by Jensen's inequality, one can obtain
\begin{equation}\label{eq_diff_GMC_delta}
\begin{split}
    &\mathbb E|(\mathbf T_{f_t}-e^{-t\mathbf H^{(\delta)}_{{\rm v}}})F|^2\\
    \leq{}& \left| |f_t'(0)|^{\frac{R^2k^2-Q^2}2}\right|^2\mathbb E\Bigg[ |F|^2\left(X\circ f_t\big|_{\mathbb{T}} + {\mathrm{i}} Q\log\tfrac{|f_t'|}{|f_t|}\big|_{\mathbb{T}}\right)\\
    &\ \ \ \ \ \ \ \ \ \ \ \ \ \ \ \ \ \ \ \ \left|e^{-\mu\int_0^t V_{\rm v}^{}(X\circ f_s\big|_{\mathbb{T}} + {\mathrm{i}} Q\log\tfrac{|f_s'|}{|f_s|}\big|_{\mathbb{T}}){\mathrm{d}} s}-e^{-\mu\int_0^t V_{\rm v}^{(\delta)}(X\circ f_s\big|_{\mathbb{T}} + {\mathrm{i}} Q\log\tfrac{|f_s'|}{|f_s|}\big|_{\mathbb{T}}){\mathrm{d}} s}\right|^2\Bigg].
\end{split}
\end{equation}
We can apply the Cauchy-Schwarz inequality again to separate $F$ and GMC exponential moment with the $F$ part controlled by $e^{Ct}\|F^2\|_{L^2}^2$. Thus we only need to show that the GMC exponential moment part converges and is bounded by a function of $t$ (in fact $e^{Ct},C>0$) independent of $\delta$. Since for all $t>0$, we have the $L^2$ convergence of GMC \cite{Lacoin2015}, the convergence of the resolvent is a consequence of the following lemma. 

Before the lemma, recall in \cite[Lemma 2.3]{Virasoro_structure}, as $s\to\infty$, $e^{\omega s}f_s(e^{{\mathrm{i}}\theta})$ and $e^{\omega s}f_s'(e^{{\mathrm{i}}\theta})$ converge uniformly in $\theta\in[0,2\pi]$ to some function $f_*(e^{{\mathrm{i}}\theta})$ and $f'_*(e^{{\mathrm{i}}\theta})$, with $f_*$ biholomorphic in $(1+\varepsilon')\mathbb D$ for some $\varepsilon'>0$.
\begin{lemma}\label{lemma_gmc_delta_exp_bound}
    For the GFF on the disk $X$, and a measurable function $h(\theta,s)$, there exists a constant $C$ depending on $\beta$ and $(v(z))_{z\in\mathbb D}$ only, such that when $\delta<1$,
    \begin{equation*}
        \mathbb E\left[\left|e^{-\mu \int_0^T \int_0^{2\pi}h(\theta,s)e^{{\mathrm{i}}\beta(X\circ f_s)^{\text{arc}}_\delta(e^{{\mathrm{i}}\theta})+\frac{\beta^2}{2}\mathbb E[(\varphi^{\text{arc}}_\delta)^2(\theta)]}\,{\mathrm{d}}\varrho_{\rm v}(\theta){\mathrm{d}} s}\right|\right]< e^{C|\mu|}(1+2|\mu| u_\delta(T) e^{C|\mu|^2 u^2_{\delta}(T)}),
    \end{equation*}
    where
    \begin{equation}\label{eq_u_and_k}
    \begin{split}
        u^2_\delta(T):={}&\delta^{-2}\iint_{([0,T]\times[0,2\pi])^2}\int_{-\delta}^{\delta}\int_{-\delta}^{\delta}|h(\theta_1+\theta_1',s_1)||h(\theta_2+\theta_2',s_2)|\,{\mathrm{d}} \theta_1'{\mathrm{d}}\theta_2'\\
        &\ \ \ \ \ \ \ \ \  \ \ \ \ \ \ \ \ \ e^{-\frac{\beta^2\operatorname{Re}\omega}{2}(s_1+s_2) }|f_{s_1}(e^{{\mathrm{i}}\theta_1})-f_{s_2}(e^{{\mathrm{i}}\theta_2})|^{-\beta^2}\,{\mathrm{d}} s_1{\mathrm{d}}\varrho_{\rm v}(\theta_1){\mathrm{d}} s_2{\mathrm{d}}\varrho_{\rm v}(\theta_2).
    \end{split}
    \end{equation}
\end{lemma}
\begin{proof}
    Without loss of generality, we can consider the decomposition of GFF on a disk of radius $\mathcal R>1$ into a Dirichlet GFF and a harmonic extension, hence we only need to focus on the Dirichlet GFF on $\mathcal R\mathbb D$ restricted to $\mathbb D$ and still denote it by $X$. 

Let $p_{t/2}(x,y)$ be the Dirichlet heat kernel on $\mathcal R\mathbb D$ and $W({\mathrm{d}} y,{\mathrm{d}} t)$ be a white noise on $\mathcal R\mathbb D\times[0,\infty)$.   Using the white noise decomposition, we have
    \begin{equation*}
        (X\circ f_s)_{\delta,\varepsilon}^{arc}(e^{{\mathrm{i}}\theta}):=\frac{\sqrt{2\pi}}{2\delta}\int_{-\delta}^{\delta}\int_{\varepsilon^2}^\infty\int_{|y|<\mathcal R}p_{t/2}(f_s(e^{{\mathrm{i}}(\theta+\theta')}),y)W({\mathrm{d}} y,{\mathrm{d}} t){\mathrm{d}} \theta',
    \end{equation*}
    and $(e^{{\mathrm{i}} \beta (X\circ f_s)_{\delta,\varepsilon}^{arc}(e^{{\mathrm{i}}\theta})+\frac{\beta^2}2\mathbb E[(X\circ f_s)_{\delta,\varepsilon}^{arc}(e^{{\mathrm{i}}\theta})^2]})_{\varepsilon>0}$ becomes a martingale. Define
    \begin{equation*}
        k_\delta(\theta,s):=h(\theta,s)\exp\left(\frac{\beta^2}{2}\left(\mathbb E[(\varphi^{\text{arc}}_\delta)^2(\theta)]-\mathbb E[(X\circ f_s)_{\delta}^{arc}(e^{{\mathrm{i}}\theta})^2]\right)\right).
    \end{equation*}
    Following the proof of \cite[Proposition 5.3]{CILT}, we compute the quadratic variation of  the martingale
    \begin{equation*}
        \mathcal M_{\varepsilon}^{(\delta)}:=\int_0^{T}\int_0^{2\pi} k_\delta(\theta,s)\,e^{{\mathrm{i}} \beta (X\circ f_s)_{\delta,\varepsilon}^{arc}(e^{{\mathrm{i}}\theta})+\frac{\beta^2}2\mathbb E[(X\circ f_s)_{\delta,\varepsilon}^{arc}(e^{{\mathrm{i}}\theta})^2]}\ {\mathrm{d}}\varrho_{\rm v}(\theta){\mathrm{d}} s,
    \end{equation*}
    which is
    \begin{equation*}
    \begin{split}
          &\langle \mathcal M^{(\delta)}\rangle_t-\langle \mathcal M^{(\delta)}\rangle_0\\
          ={}&\beta^2\int_0^t\iint_{([0,T]\times[0,2\pi])^2}k_\delta(\theta_1,s_1)k_\delta(\theta_2,s_2)\sin(\beta (X\circ f_{s_1})_{\delta,e^{-u}}^{arc}(e^{{\mathrm{i}}\theta_1}))\sin(\beta(X\circ f_{s_2})_{\delta,e^{-u}}^{arc}(e^{{\mathrm{i}}\theta_2}))\\
          &\ \ \  \ \  e^{\frac{\beta^2}2(\mathbb E[(X\circ f_{s_1})_{\delta,\varepsilon}^{arc}(e^{{\mathrm{i}}\theta_1})^2]+\mathbb E[(X\circ f_{s_2})_{\delta,\varepsilon}^{arc}(e^{{\mathrm{i}}\theta_2})^2])}\ {\mathrm{d}} s_1{\mathrm{d}}\varrho_{\rm v}(\theta_1){\mathrm{d}} s_2{\mathrm{d}}\varrho_{\rm v}(\theta_2)\  {\mathrm{d}}\langle (X\circ f_{s_1})_{\delta,e^{-u}}^{arc}(e^{{\mathrm{i}}\theta_1}),(X\circ f_{s_2})_{\delta,e^{-u}}^{arc}(e^{{\mathrm{i}}\theta_2})\rangle_u,
    \end{split}
    \end{equation*}
    where for convenience we have assumed $\operatorname{Im}(h)=0$ and $\mu\in\mathbb R$. Next, the quadratic variation of the smooth field is
    \begin{equation*}
        {\mathrm{d}}\langle (X\circ f_{s_1})_{\delta,e^{-u}}^{arc}(e^{{\mathrm{i}}\theta_1}),(X\circ f_{s_2})_{\delta,e^{-u}}^{arc}(e^{{\mathrm{i}}\theta_2})\rangle_u=\frac{\pi e^{-2u}}{\delta^2}\int_{-\delta}^{\delta}\int_{-\delta}^{\delta}p_{e^{-2u}}(f_{s_1}(e^{{\mathrm{i}}(\theta_1+\theta_1')}),f_{s_2}(e^{{\mathrm{i}}(\theta_2+\theta_2')}))\ {\mathrm{d}} \theta_1'{\mathrm{d}} \theta_2'{\mathrm{d}} u.
    \end{equation*}
    Using the bound for the heat kernel \cite{Cheng1981},
    \begin{equation*}
        e^{-2u}p_{e^{-2u}}(f_{s_1}(e^{{\mathrm{i}}(\theta_1+\theta_1')}),f_{s_2}(e^{{\mathrm{i}}(\theta_2+\theta_2')}))\leq C e^{-{|f_{s_1}(e^{{\mathrm{i}}(\theta_1+\theta_1')})-f_{s_2}(e^{{\mathrm{i}}(\theta_2+\theta_2')})|^2e^{2u}}/{C}}
    \end{equation*}
    for some constant $C$, we can again bound the quadratic variation using the integral
 \begin{equation}\label{eq_M_bound}
    \begin{split}
          &\sup_{t\geq0}\langle \mathcal M^{(\delta)}\rangle_t-\langle \mathcal M^{(\delta)}\rangle_0\\
          \leq{}&\frac{C\beta^2}{\delta^2}\int_0^\infty\iint_{([0,T]\times[0,2\pi])^2}|k_\delta(s_1,\theta_1)||k_\delta(s_2,\theta_2)|e^{\frac{\beta^2}2(\mathbb E[(X\circ f_{s_1})_{\delta,e^{-u}}^{arc}(e^{{\mathrm{i}}\theta_1})^2]+\mathbb E[(X\circ f_{s_2})_{\delta,e^{-u}}^{arc}(e^{{\mathrm{i}}\theta_2})^2])}\\
          &\ \ \ \ \ \ \ \ \ \ \ \ \ \ \ \int_{-\delta}^{\delta}\int_{-\delta}^{\delta}e^{-|f_{s_1}(e^{{\mathrm{i}}(\theta_1+\theta_1')})-f_{s_2}(e^{{\mathrm{i}}(\theta_2+\theta_2')})|^2e^{2u}/{C}}\ {\mathrm{d}} \theta_1'{\mathrm{d}}\theta_2'\,{\mathrm{d}} s_1{\mathrm{d}}\varrho_{\rm v}(\theta_1){\mathrm{d}} s_2{\mathrm{d}}\varrho_{\rm v}(\theta_2)\, {\mathrm{d}} u.
    \end{split}
    \end{equation}
When $t$ is small, we have the free heat kernel diagonal bound $ p_t(x,y)\leq\frac{1}{4\pi t}$, while for $t$ large $p_t$ decays exponentially fast in $t$. Thus we have when $u$ large
\begin{equation*}
    \mathbb E[ (X\circ f_{s_1})_{\delta,e^{-u}}^{arc}(e^{{\mathrm{i}}\theta_1})^2]=\frac{\pi}{2\delta^2}\int_{-\delta}^{\delta}\int_{-\delta}^{\delta}\int_{e^{-2u}}^\infty p_t(f_{s_1}(e^{{\mathrm{i}}(\theta_1+\theta')}),f_{s_1}(e^{{\mathrm{i}}(\theta_1+\theta'')}))\ {\mathrm{d}} t\ {\mathrm{d}} \theta'{\mathrm{d}} \theta''\leq C+u,
\end{equation*}
where $C$ is independent of $\delta,s_1,\theta_1$ hence we can replace the variance in \eqref{eq_M_bound} with $u$ uniformly. Finally, integrating out the white noise cut-off ${\mathrm{d}} u$, we are left with
\begin{equation*}
    \frac{C\beta^2}{\delta^2}\iint_{([0,T]\times[0,2\pi])^2}|k_\delta(s_1,\theta_1)||k_\delta(s_2,\theta_2)|\int_{-\delta}^{\delta}\int_{-\delta}^{\delta}|f_{s_1}(e^{{\mathrm{i}}(\theta_1+\theta_1')})-f_{s_2}(e^{{\mathrm{i}}(\theta_2+\theta_2')})|^{-\beta^2}{\mathrm{d}} \theta_1'{\mathrm{d}}\theta_2'\,{\mathrm{d}} s_1{\mathrm{d}}\varrho_{\rm v}(\theta_1){\mathrm{d}} s_2{\mathrm{d}}\varrho_{\rm v}(\theta_2),
\end{equation*}
which is bounded by
\begin{equation}\label{eq_temp_in_GMC_bound}
    \frac{C\beta^2}{\delta^2}\iint_{([0,T]\times[0,2\pi])^2}\int_{-\delta}^{\delta}\int_{-\delta}^{\delta}|k_\delta(s_1,\theta_1+\theta_1')||k_\delta(s_2,\theta_2+\theta_2')|\,{\mathrm{d}} \theta_1'{\mathrm{d}}\theta_2'\,|f_{s_1}(e^{{\mathrm{i}}\theta_1})-f_{s_2}(e^{{\mathrm{i}}\theta_2})|^{-\beta^2}\,{\mathrm{d}} s_1{\mathrm{d}}\varrho_{\rm v}(\theta_1){\mathrm{d}} s_2{\mathrm{d}}\varrho_{\rm v}(\theta_2).
\end{equation}
Besides, by Jensen's inequality,
\begin{equation*}
\begin{split}
    \exp\left(\frac{\beta^2}{2}(\mathbb E[(\varphi^{\text{arc}}_\delta)^2(\theta)]-\mathbb E[(X\circ f_s)_{\delta}^{arc}(e^{{\mathrm{i}}\theta})^2])\right)={}&\exp\left(\frac{\beta^2}{8\delta^2}\int_{-\delta}^\delta\int_{-\delta}^\delta \log\left|\frac {f_s(e^{{\mathrm{i}}(\theta+\theta_1)})-f_s(e^{{\mathrm{i}}(\theta+\theta_2)})}{e^{{\mathrm{i}}(\theta+\theta_1)}-e^{{\mathrm{i}}(\theta+\theta_2)}}\right|{\mathrm{d}}\theta_1{\mathrm{d}}\theta_2\right)\\
    \leq{}&\frac{1}{4\delta^2}\int_{-\delta}^\delta\int_{-\delta}^\delta \exp\left(\frac{\beta^2}{2}\log\left|\frac {f_s(e^{{\mathrm{i}}(\theta+\theta_1)})-f_s(e^{{\mathrm{i}}(\theta+\theta_2)})}{e^{{\mathrm{i}}(\theta+\theta_1)}-e^{{\mathrm{i}}(\theta+\theta_2)}}\right|\right){\mathrm{d}}\theta_1{\mathrm{d}}\theta_2,
\end{split}
\end{equation*}
Since $f_s(z)$ is holomorphic on $\mathbb T$, we have 
\begin{equation*}
      |k_{\delta}(s,\theta)|\leq  |h(s,\theta)|\sup_{\theta'\in[0,2\pi]}|f'_s(e^{{\mathrm{i}}\theta'})|^{\frac{\beta^2}{2}}\leq C |h(s,\theta)|e^{-\frac{\beta^2\operatorname{Re}\omega}{2}s }.
\end{equation*}
We finish the proof by putting the above bound in \eqref{eq_temp_in_GMC_bound}.
\end{proof}
We stress that when $s$ becomes large, $|f_s(e^{{\mathrm{i}}\theta})|\approx|f_s'(e^{{\mathrm{i}}\theta})|\approx C e^{-s{\operatorname{Re}\omega} }$. Take in \cref{lemma_gmc_delta_exp_bound}
\begin{equation*}
    h(s,\theta)=\exp\left(-\frac{\beta Q}{2\delta}\int_{-\delta}^{\delta}\log\tfrac{|f_s'(e^{{\mathrm{i}}(\theta+\theta')})|}{|f_s(e^{{\mathrm{i}}(\theta+\theta')})|}{\mathrm{d}}\theta'\right),
\end{equation*}
and
\begin{equation*}
    h(s,\theta)\leq \frac{1}{2\delta}\int_{-\delta}^{\delta}\exp\left(-\beta Q\log\frac{|f_s'(e^{{\mathrm{i}}(\theta+\theta')})|}{|f_s(e^{{\mathrm{i}}(\theta+\theta')})|}\right){\mathrm{d}}\theta'\leq \sup_{\theta'\in[-\delta_0,\delta_0]}\left|\frac{f_s'(e^{{\mathrm{i}}(\theta+\theta')})}{f_s(e^{{\mathrm{i}}(\theta+\theta')})}\right|^{-\frac{\beta^2}{2}+2},
\end{equation*}
where the above is bounded in $s>0$ and $\theta\in[0,2\pi]$. Now applying change of variable to \eqref{eq_u_and_k}, we have when $T$ large
\begin{equation*}
\begin{split}
     u^2_\delta(T)\leq{}&C\iint_{([0,T]\times[0,2\pi])^2}|f_{s_1}(e^{{\mathrm{i}}\theta_1})f_{s_2}(e^{{\mathrm{i}}\theta_2})|^{\frac{\beta^2}{2}}|f_{s_1}(e^{{\mathrm{i}}\theta_1})-f_{s_2}(e^{{\mathrm{i}}\theta_2})|^{-\beta^2}\,{\mathrm{d}} s_1{\mathrm{d}}\varrho_{\rm v}(\theta_1){\mathrm{d}} s_2{\mathrm{d}}\varrho_{\rm v}(\theta_2)\\
     \leq{}&C\iint_{(\mathbb A_{f_T})^2}|z_1z_2|^{\beta Q}|z_1-z_2|^{-\beta^2}\,{\mathrm{d}} z_1{\mathrm{d}} z_2\leq C\iint_{Ce^{-T\operatorname{Re}\omega}\leq|z_1|,|z_2|\leq 1}|z_1z_2|^{\beta Q}|z_1-z_2|^{-\beta^2}\,{\mathrm{d}} z_1{\mathrm{d}} z_2.
\end{split}
\end{equation*}
Evaluating the last integral on $C^le^{-l\,T\operatorname{Re}\omega  }\leq|z_1|,|z_2|\leq C^{l-1}e^{-(l-1)\, T\operatorname{Re}\omega  },l\geq1$ shows that $ u^2_\delta(T)\leq  C(1+T\operatorname{Re}\omega) $. Therefore the bound in \cref{lemma_gmc_delta_exp_bound} is at most exponential in $T$ and independent of $\delta<\delta_0$. Then we can take the $\delta\to0$ limit in \eqref{eq_diff_GMC_delta} and obtain the $L^2$ convergence of the resolvent if we choose $\lambda$ large enough.

















We first state a general lemma about convergence.
\begin{lem}\label{lemma_resolvent_technical}
    Let $A\geq c_0I,c_0>0$ be a positive self-adjoint operator on Hilbert space $\mathcal H$. Write $\mathcal W^s:=\mathcal D(A^{\frac s2})$, i.e. the domain under $\|u\|_s:=\|A^{\frac s2}u\|_{\mathcal H}$, with $\|\cdot\|_{\mathcal H}$ the Hilbert norm. Also there is a sequence of bounded operator $(B_n)_{n\geq1}$ satisfying
    \begin{equation*}
        \|e^{-t A}B_ne^{-s A}\|_{\mathcal H\to\mathcal H}\leq C_0(ts)^{-\alpha}e^{-c_1(t+s)},\ \ \ s,t>0,
    \end{equation*}
    where $C_0,c_1>0$ and $0\leq\alpha<\frac12$. Also consider a dense subspace $\mathcal C$ of $\mathcal W^1$ on which $\langle B_n u,v\rangle_{\mathcal H}$ converges for $u,v\in\mathcal C$ and we denote the limit by $\langle B u,v\rangle_{\mathcal H}$. If $u_n\to u$ strongly in $\mathcal H$ and $\sup_{n}\|u_n\|_{1}<\infty$, then $u\in \mathcal W^1$ and $\langle B_n u_n,v\rangle_{\mathcal H}$ converge to $\langle B u,v\rangle_{\mathcal H}$ for all $v\in\mathcal W^r,2\alpha<r<1$.







\end{lem}
\begin{proof}
   Fix $2\alpha<r<1$. Since $A^{-\frac r2}=\frac{1}{\Gamma(\frac r2)}\int_0^\infty t^{\frac r2-1}e^{-tA}\,\mathrm{d}t$, it is plain to check that 
   \begin{equation}\label{eq_temp_ABA}
       \|A^{-\frac{r}{2}}B_nA^{-\frac{r}{2}}\|_{\mathcal H\to\mathcal H}\leq\frac{C_0}{\Gamma(\frac r2)^2}\left(\int_0^{\infty}t^{\frac{r}{2}-\alpha-1}e^{-c_1t}\,\mathrm{d}t\right)^2=:C(r)<\infty,
   \end{equation}
   using the bound from $\|e^{-t A}B_ne^{-s A}\|_{\mathcal H\to\mathcal H}$. Hence 
   \begin{equation}\label{eq_temp_bound}
       |\langle B_n u,v\rangle_{\mathcal H}|\leq C(r)\|u\|_r\|v\|_r.
   \end{equation}
   Now let us check the first item. 
   \begin{equation*}
   \begin{split}
        |\langle B_n u_n,v\rangle_{\mathcal H}-\langle Bu,v\rangle_{\mathcal H}|\leq{}&|\langle B_n (u_n-u),v\rangle_{\mathcal H}|+|\langle B_nu,v\rangle_{\mathcal H}-\langle Bu,v\rangle_{\mathcal H}|\\
        \leq{}&C(r)\|u_n-u\|_r\|v\|_r+|\langle B_nu,v\rangle_{\mathcal H}-\langle Bu,v\rangle_{\mathcal H}|.
   \end{split}
   \end{equation*}
   According to \cite[Lemma 2.12]{Ma_1992}, the convergence of $u_n$ in $\mathcal H$ and boundedness in $\mathcal W^1$ imply that $u\in\mathcal W^1$. By H\"older's inequality, we have
   \begin{equation*}
       \|u_n-u\|_r\leq\|u_n-u\|_{\mathcal H}^{1-r}\|u_n-u\|_1^{r}\to0.
   \end{equation*}
   The convergence of $|\langle B_nu,v\rangle_{\mathcal H}-\langle Bu,v\rangle_{\mathcal H}|$ is again from \eqref{eq_temp_bound} with $\mathcal C$ approximation. 
\end{proof}



By the definition of ${\mathcal{Q}}_{\rm v}^{(\delta)}$, for $G\in{\mathcal{E}}({\mathcal{D}}'({\mathbb{T}},{\mathbb{T}}_R))$ we have
\begin{equation*}
    \lambda \langle \mathbf R_{{\rm v},\lambda}^{(\delta)}F,G\rangle_{L^2}+{\mathcal{Q}}_{\rm v}^{(\delta)}(\mathbf R_{{\rm v},\lambda}^{(\delta)}F,G)=\langle F,G\rangle_{L^2}.
\end{equation*}
Especially one can take $G=\mathbf R_{{\rm v},\lambda}^{(\delta)}F$ (by approximation) and get $\sup_{0<\delta<1} |{\mathcal{Q}}_{\rm v}^{(\delta)}(\mathbf R_{{\rm v},\lambda}^{(\delta)}F,\mathbf R_{{\rm v},\lambda}^{(\delta)}F)|<\infty$. In \cref{Q_v_bound}, specifically in \cref{V_v_estimate}, the comparison between ${\mathcal{Q}}_{\rm v}^{(\delta)}$ and $\widetilde{{\mathcal{Q}}}_0$ is uniform in $\delta$. We thus have $\sup_{0<\delta<1} |\widetilde{{\mathcal{Q}}}^0(\mathbf R_{{\rm v},\lambda}^{(\delta)}F,\mathbf R_{{\rm v},\lambda}^{(\delta)}F)|<\infty$ (for each $\delta$, ${\mathcal{Q}}^0_{\rm v}(\mathbf R_{{\rm v},\lambda}^{(\delta)}F,\mathbf R_{{\rm v},\lambda}^{(\delta)}F)$ is finite since $V_{\rm v}^{(\delta)}$ is bounded). Then according to \cite[Lemma 2.12]{Ma_1992}, there is a subsequence of $ (\mathbf R_{{\rm v},\lambda}^{(\delta)}F)_{\delta}$ that converges weakly in $\widetilde{\mathcal Q}^0$ and $\mathbf R_{{\rm v},\lambda}F\in\mathcal D(\widetilde{\mathcal Q}^0)$. Recall \eqref{eq_estimate_PVP}, and we can easily use \cref{lemma_resolvent_technical} with $\mathbf H^0+Q^2$ to get the convergence of ${\mathcal{Q}}_{\rm v}^{(\delta)}(\mathbf R_{{\rm v},\lambda}^{(\delta)}F,G)$ to ${\mathcal{Q}}_{\rm v}(\mathbf R_{{\rm v},\lambda}F,G)$.




















In the end, we have shown that for $\lambda$ large enough,
 \begin{equation*}
    \lambda \langle \mathbf R_{{\rm v},\lambda}F,G\rangle_{L^2}+{\mathcal{Q}}_{\rm v}(\mathbf R_{{\rm v},\lambda}F,G)=\langle F,G\rangle_{L^2},
\end{equation*}
which means the resolvents from two approaches agree and therefore the proof is complete by the uniqueness of the resolvent.

By definition of ${\mathcal{E}}({\mathcal{D}}'({\mathbb{T}},{\mathbb{T}}_R))$, we can assume $F,G$ depend on a finite number of Fourier modes of GFF in terms of polynomials. Similar to the proof in \cite[Lemma 5.4]{Guillarmou2024}, and using the definition of the semigroup ${\mathbf{T}}_{f_t}$ \eqref{eq_def_T_f}, $\langle F-{\mathbf{T}}_{f_t}F,G\rangle_{L^2}$ is just
  \begin{equation}\label{eq_diff_T_f}
   \int_{0}^{2\pi R}{\mathrm{d}} c\ {\mathbb{E}}\left[\left(F(\widetilde{\varphi}^k)-|f_t'(0)|^{\frac{R^2k^2-Q^2}2} F\left((P\widetilde{\varphi}^k+X_{\mathbb{D}})\circ f_t\big|_{\mathbb{T}} + {\mathrm{i}} Q\log\tfrac{|f_t'|}{|f_t|}\big|_{\mathbb{T}}\right)\,e^{-\mu\int_{{\mathbb{A}}_{f_t}}|x|^{\beta Q}M_\beta(P\widetilde{\varphi}^k+X_{\mathbb{D}},{\mathrm{d}} x)}\right)\,\overline{G}(\widetilde{\varphi}^k)\right].
  \end{equation}
In the following proof, denote by $X$ the field on the disk $P\widetilde{\varphi}^k+X_{\mathbb{D}}$. Recall that the GFF part $P{\varphi}+X_{\mathbb{D}}$ has covariance $-\log|x-x'|,\forall x,x'\in\mathbb D$. Since $F,G\in{\mathcal{E}}({\mathcal{D}}'({\mathbb{T}},{\mathbb{T}}_R)) $, we have $\mathbb E[|F(\widetilde{\varphi}^k)G(\widetilde{\varphi}^k)|^n]<\infty$ for arbitrary $n$.

According to \cref{prop_FK_free}, \eqref{eq_diff_T_f} is further written as
  \begin{equation*}
  \begin{split}
   &t{\mathcal{Q}}_{\rm v}^0(F,G)+o(t)+\int_{0}^{2\pi R}{\mathrm{d}} c\ {\mathbb{E}}\left[F(\widetilde{\varphi}^k)\,\overline{G}(\widetilde{\varphi}^k)\,\left(1-e^{-\mu\int_{{\mathbb{A}}_{f_t}}|x|^{\beta Q}M_\beta(X,{\mathrm{d}} x)}\right)\right]+\\
      &\int_{0}^{2\pi R}{\mathrm{d}} c\ {\mathbb{E}}\left[\left(F(\widetilde{\varphi}^k)-|f_t'(0)|^{\frac{R^2k^2-Q^2}2}F\left(X\circ f_t\big|_{\mathbb{T}} + {\mathrm{i}} Q\log\tfrac{|f_t'|}{|f_t|}\big|_{\mathbb{T}}\right)\right)\,\overline{G}(\widetilde{\varphi}^k)\,\left(e^{-\mu\int_{{\mathbb{A}}_{f_t}}|x|^{\beta Q}M_\beta(X,{\mathrm{d}} x)}-1\right)\right]\\
      &=:t{\mathcal{Q}}_{\rm v}^0(F,G)+o(t)+D_t^{(1)}+D_t^{(2)}.
  \end{split}
  \end{equation*}
In the following we will prove $t^{-1}D_t^{(1)}\to \mu\langle V_{\rm v} F,G\rangle$ and $t^{-1}D_t^{(2)}\to 0$.

For $D_t^{(1)}$, we expand the exponential of GMC then we have

  \begin{equation*}
  \begin{split}
      D_t^{(1)}={}&-\int_{0}^{2\pi R}{\mathrm{d}} c\ {\mathbb{E}}\left[F(\widetilde{\varphi}^k)\,\overline{G}(\widetilde{\varphi}^k)\,\sum_{n\geq1}\frac{(-\mu)^n}{n!}\left(\int_{{\mathbb{A}}_{f_t}}|x|^{\beta Q}M_\beta(X,{\mathrm{d}} x)\right)^n\right].
  \end{split}
  \end{equation*}
  Now we apply the imaginary Cameron--Martin theorem to each term in the summation for a single vertex insertion, and we get

  \begin{equation*}
      \begin{split}
      D_t^{(1)}={}&-\int_{0}^{2\pi R}\int_{{\mathbb{A}}_{f_t}}e^{{\mathrm{i}}\beta c+{\mathrm{i}}\beta Rk\arg y}\\ &\ \ \ \ \ \ \ \ \ \ \ \ \ \ {\mathbb{E}}\left[F_{\text{shift}}(y,\widetilde{\varphi}^k)\,(\overline{G})_{\text{shift}}(y,\widetilde{\varphi}^k)\,\sum_{n\geq1}\frac{(-\mu)^n}{n!}\left(\int_{{\mathbb{A}}_{f_t}}|x|^{\beta Q}|x-y|^{\beta^2}M_\beta(X,{\mathrm{d}} x)\right)^{n-1}\right]|y|^{\beta Q}\,{\mathrm{d}} y\,{\mathrm{d}} c\\
      ={}& \mu\int_{0}^{2\pi R}\int_{{\mathbb{A}}_{f_t}}e^{{\mathrm{i}}\beta c+{\mathrm{i}}\beta Rk\arg y}\ {\mathbb{E}}\left[F_{\text{shift}}(y,\widetilde{\varphi}^k)\,(\overline{G})_{\text{shift}}(y,\widetilde{\varphi}^k)\right]|y|^{\beta Q}\,{\mathrm{d}} y\,{\mathrm{d}} c-\int_{0}^{2\pi R}\int_{{\mathbb{A}}_{f_t}}e^{{\mathrm{i}}\beta c+{\mathrm{i}}\beta Rk\arg y}\\ &\ \  \ \ \ \ \ \ \ \ \ {\mathbb{E}}\left[F_{\text{shift}}(y,\widetilde{\varphi}^k)\,(\overline{G})_{\text{shift}}(y,\widetilde{\varphi}^k)\,\sum_{n\geq2}\frac{(-\mu)^n}{n!}\left(\int_{{\mathbb{A}}_{f_t}}|x|^{\beta Q}|x-y|^{\beta^2}M_\beta(X,{\mathrm{d}} x)\right)^{n-1}\right]|y|^{\beta Q}\,{\mathrm{d}} y\,{\mathrm{d}} c,
  \end{split}
  \end{equation*}
where
\begin{equation*}
    F_{\text{shift}}(y,\widetilde{\varphi}^k):=F(\widetilde{\varphi}^k+{\mathrm{i}}\beta K_y),\ \ \ K_{r e^{{\mathrm{i}}\theta'}}(\theta):=\sum_{n\geq1}\frac{|r|^n}{n}\cos(n(\theta-\theta')).
\end{equation*}

For $t$ small enough, ${\mathbb{A}}_{f_t}$ are always the subset of some annulus $\{z:q<|z|<1\},q<1$. Define
\begin{equation*}
    I_t(y):=\left|{\mathbb{E}}\left[F_{\text{shift}}(y,\widetilde{\varphi}^k)\,(\overline{G})_{\text{shift}}(y,\widetilde{\varphi}^k)\,\sum_{n\geq2}\frac{(-\mu)^n}{n!}\left(\int_{{\mathbb{A}}_{f_t}}|x|^{\beta Q}|x-y|^{\beta^2}M_\beta(X,{\mathrm{d}} x)\right)^{n-1}\right]\right|,
\end{equation*}
and we claim that
\begin{equation}\label{eq_FK_claim}
    \lim_{t\to0}\sup_{q<|y|<1}   I_t(y)=0,
\end{equation}
which would imply $t^{-1}D_t^{(1)}-\mu\langle V_{\rm v} F,G\rangle\approx t^{-1}\int_{{\mathbb{A}}_{f_t}}  I_t(y)|y|^{\beta Q}{\mathrm{d}} y\to 0$.
To prove \eqref{eq_FK_claim}, we first apply the Cauchy-Schwarz inequality and obtain
\begin{equation*}
\begin{split}
    &I_t^2(y)\leq{\mathbb{E}}[|\int_{{\mathbb{A}}_{f_t}}|x|^{\beta Q}|x-y|^{\beta^2}M_\beta(X,{\mathrm{d}} x)|^{2}]\times\\
    &{\mathbb{E}}\left[\left|F_{\text{shift}}(y,\widetilde{\varphi}^k)\,(\overline{G})_{\text{shift}}(y,\widetilde{\varphi}^k)\,\sum_{n\geq2}\frac{(-\mu)^n}{n!}\left(\int_{{\mathbb{A}}_{f_t}}|x|^{\beta Q}|x-y|^{\beta^2}M_\beta(X,{\mathrm{d}} x)\right)^{n-2}\right|^2\right].
\end{split}
\end{equation*}
Since $|\sum_{n\geq2}\frac{(-\mu)^n}{n!}z^{n-2}|\leq|\mu|^2\sum_{n\geq0}\frac{|\mu z|^n}{(n+2)!}\leq |\mu|^2e^{|\mu z|}$, the second term above is further bounded, using Cauchy-Schwarz inequality, up to a constant depending on $\mu$ by
\begin{equation*}
    {\mathbb{E}}[|F_{\text{shift}}(\overline{G})_{\text{shift}}|^4]^{\frac12}{\mathbb{E}}[\exp(4|\mu||\int_{{\mathbb{A}}_{f_t}}|x|^{\beta Q}|x-y|^{\beta^2}M_\beta(X,{\mathrm{d}} x)|)]^{\frac12}.
\end{equation*}
For some constant $C$ independent of $t$ small enough, we have $\sup_{q<|y|<1}\mathbb E[|F_{\text{shift}}(\overline{G})_{\text{shift}}|^4]<C$ (since the Fourier modes of $K_y(\theta)$ are under control). According to \cite[Proposition 5.3]{CILT}, for some constant $C$ only depending on $\beta$, the exponential moment is bounded by
\begin{equation*}
    e^{C|\mu|}(1+2|\mu| u e^{C|\mu|^2 u^2}),
\end{equation*}
where
\begin{equation}\label{eq_metric_integral}
    u^2:=\iint_{({\mathbb{A}}_{f_t})^2}|x|^{\beta Q}|x-y|^{\beta^2}|x'|^{\beta Q}|x'-y|^{\beta^2}|x-x'|^{-\beta^2}\ {\mathrm{d}} x\, {\mathrm{d}} x'.
\end{equation}
Hence ${\mathbb{E}}[\exp(C|\int_{{\mathbb{A}}_{f_t}}|x|^{\beta Q}|x-y|^{\beta^2}M_\beta(X,{\mathrm{d}} x)|)]$ is finite and uniformly bounded in $q<|y|<1$ and $t$ small enough. Then the study of $I_t^2$ boils down to the second moment
\begin{equation*}
    {\mathbb{E}}[|\int_{{\mathbb{A}}_{f_t}}|x|^{\beta Q}|x-y|^{\beta^2}M_\beta(X,{\mathrm{d}} x)|^{2}]\leq\iint_{({\mathbb{A}}_{f_t})^2}|x|^{\beta Q}|x-y|^{\beta^2}|x'|^{\beta Q}|x'-y|^{\beta^2}|x-x'|^{-\beta^2}\ {\mathrm{d}} x\, {\mathrm{d}} x',
\end{equation*}
which goes to $0$ uniformly in $y$ as $t\to0$. 

Therefore \eqref{eq_FK_claim} is proved and we just have
 \begin{equation*}
      \begin{split}
      \lim_{t\to0}t^{-1}D_t^{(1)} &=   \lim_{t\to0}t^{-1}\mu\int_{0}^{2\pi R}\int_{{\mathbb{A}}_{f_t}}e^{{\mathrm{i}}\beta c+{\mathrm{i}}\beta Rk\arg y}\ {\mathbb{E}}\left[F_{\text{shift}}(y,\widetilde{\varphi}^k)\,(\overline{G})_{\text{shift}}(y,\widetilde{\varphi}^k)\right]|y|^{\beta Q}\,{\mathrm{d}} y\,{\mathrm{d}} c\\
      &=-\lim_{t\to0}t^{-1}\mu\int_{0}^{2\pi R}\int_0^t\int_0^{2\pi}e^{{\mathrm{i}}\beta c+{\mathrm{i}}\beta Rk\arg f_s(e^{{\mathrm{i}}\theta})}\ {\mathbb{E}}\left[F_{\text{shift}}(f_s(e^{{\mathrm{i}}\theta}),\widetilde{\varphi}^k)\,(\overline{G})_{\text{shift}}(f_s(e^{{\mathrm{i}}\theta}),\widetilde{\varphi}^k)\right]\\
      &\ \ \ \ \ \ \ \ \ \  \ \ \ \ \ \ \ \ \ \ \  \ \ \ \ \ \ \ \ \ |f_s(e^{{\mathrm{i}}\theta})|^{\beta Q}|f_s'(e^{{\mathrm{i}}\theta})|^2\operatorname{Re}\left(e^{-{\mathrm{i}}\theta}v(e^{{\mathrm{i}}\theta})\right)\, {\mathrm{d}}\theta{\mathrm{d}} s\ {\mathrm{d}} c\\
      &=-\mu\int_{0}^{2\pi R}\int_0^{2\pi}e^{{\mathrm{i}}\beta c+{\mathrm{i}}\beta Rk\theta}\ {\mathbb{E}}\left[F_{\text{shift}}(e^{{\mathrm{i}}\theta},\widetilde{\varphi}^k)\,(\overline{G})_{\text{shift}}(e^{{\mathrm{i}}\theta},\widetilde{\varphi}^k)\operatorname{Re}\left(e^{-{\mathrm{i}}\theta}v(e^{{\mathrm{i}}\theta})\right)\right]\ {\mathrm{d}}\theta\, {\mathrm{d}} c,
  \end{split}
  \end{equation*}
  where we used \eqref{eq_Aft2V} for the second line.

  Finally, we can focus on how $t^{-1}D_t^{(2)}$ goes to $0$. We can replace $F_{\text{shift}}$ in \eqref{eq_FK_claim} with
  \begin{equation*}
      F_{\text{shift}}(y,\widetilde{\varphi}^k)-|f_t'(0)|^{\frac{R^2k^2-Q^2}2}F\left(X\circ f_t\big|_{\mathbb{T}} +{\mathrm{i}}\beta K_{t,y}+ {\mathrm{i}} Q\log\tfrac{|f_t'|}{|f_t|}\big|_{\mathbb{T}}\right),\ \ K_{t,y}(\theta):=-\log|f_t(e^{{\mathrm{i}}\theta})-y|
  \end{equation*}as long as the second moment is still uniformly bounded in $y$ and $t$. Indeed, we have the free field semigroup $\|F\left(X\circ f_t\big|_{\mathbb{T}} +{\mathrm{i}}\beta K_{t,y}+ {\mathrm{i}} Q\log\tfrac{|f_t'|}{|f_t|}\big|_{\mathbb{T}}\right)\|_{L^2}\leq Ce^{Ct}\|F_{\text{shift}}\left(y,\widetilde{\varphi}^k\right)\|_{L^2}$ for some constant independent of $y$ and $t$. Since $f_t\to{\mathrm{id}}$, we have $\sup_{y\in{\mathbb{A}}_{f_t}}|\langle K_{t,y}-K_y,h\rangle|\to0$ for every $h\in C^\infty({\mathbb{T}})$. Thus
  \begin{equation*}
      \begin{split}
      \lim_{t\to0}t^{-1}D_t^{(2)} = -&  \lim_{t\to0}t^{-1}\mu\int_{0}^{2\pi R}\int_{{\mathbb{A}}_{f_t}}e^{{\mathrm{i}}\beta c+{\mathrm{i}}\beta Rk\arg y}\ \\
      &{\mathbb{E}}\left[\left(F_{\text{shift}}(y,\widetilde{\varphi}^k)-|f_t'(0)|^{\frac{R^2k^2-Q^2}2}F\left(X\circ f_t\big|_{\mathbb{T}} +{\mathrm{i}}\beta K_{t,y}+ {\mathrm{i}} Q\log\tfrac{|f_t'|}{|f_t|}\big|_{\mathbb{T}}\right)\right)\,(\overline{G})_{\text{shift}}(y,\widetilde{\varphi}^k)\right]|y|^{\beta Q}\, {\mathrm{d}} y\,{\mathrm{d}} c,
  \end{split}
  \end{equation*}
  where we can use Cauchy Schwarz inequality and \cite[Lemma 2.6, equation (2.27)]{Virasoro_structure} to conclude that $\lim_{t\to0}t^{-1}D_t^{(2)}=0$ and the proof is complete.

\label{lemma_gmc_delta_exp_bound}
    For the GFF on the disk $X$, and a measurable function $h(\theta,s)$, there exists a constant $C$ depending on $\beta$ and $(v(z))_{z\in\mathbb D}$ only, such that when $\delta<1$,
    \begin{equation*}
        \mathbb E\left[\left|e^{-\mu \int_0^T \int_0^{2\pi}h(\theta,s)e^{{\mathrm{i}}\beta(X\circ f_s)^{\text{arc}}_\delta(e^{{\mathrm{i}}\theta})+\frac{\beta^2}{2}\mathbb E[(\varphi^{\text{arc}}_\delta)^2(\theta)]}\,{\mathrm{d}}\varrho_{\rm v}(\theta){\mathrm{d}} s}\right|\right]< e^{C|\mu|}(1+2|\mu| u_\delta(T) e^{C|\mu|^2 u^2_{\delta}(T)}),
    \end{equation*}
    where
    \begin{equation}\label{eq_u_and_k}
    \begin{split}
        u^2_\delta(T):={}&\delta^{-2}\iint_{([0,T]\times[0,2\pi])^2}\int_{-\delta}^{\delta}\int_{-\delta}^{\delta}|h(\theta_1+\theta_1',s_1)||h(\theta_2+\theta_2',s_2)|\,{\mathrm{d}} \theta_1'{\mathrm{d}}\theta_2'\\
        &\ \ \ \ \ \ \ \ \  \ \ \ \ \ \ \ \ \ e^{-\frac{\beta^2\operatorname{Re}\omega}{2}(s_1+s_2) }|f_{s_1}(e^{{\mathrm{i}}\theta_1})-f_{s_2}(e^{{\mathrm{i}}\theta_2})|^{-\beta^2}\,{\mathrm{d}} s_1{\mathrm{d}}\varrho_{\rm v}(\theta_1){\mathrm{d}} s_2{\mathrm{d}}\varrho_{\rm v}(\theta_2).
    \end{split}
    \end{equation}

Without loss of generality, we can consider the decomposition of GFF on a disk of radius $\mathcal R>1$ into a Dirichlet GFF and a harmonic extension, hence we only need to focus on the Dirichlet GFF on $\mathcal R\mathbb D$ restricted to $\mathbb D$ and still denote it by $X$. 

Let $p_{t/2}(x,y)$ be the Dirichlet heat kernel on $\mathcal R\mathbb D$ and $W({\mathrm{d}} y,{\mathrm{d}} t)$ be a white noise on $\mathcal R\mathbb D\times[0,\infty)$.   Using the white noise decomposition, we have
    \begin{equation*}
        (X\circ f_s)_{\delta,\varepsilon}^{arc}(e^{{\mathrm{i}}\theta}):=\frac{\sqrt{2\pi}}{2\delta}\int_{-\delta}^{\delta}\int_{\varepsilon^2}^\infty\int_{|y|<\mathcal R}p_{t/2}(f_s(e^{{\mathrm{i}}(\theta+\theta')}),y)W({\mathrm{d}} y,{\mathrm{d}} t){\mathrm{d}} \theta',
    \end{equation*}
    and $(e^{{\mathrm{i}} \beta (X\circ f_s)_{\delta,\varepsilon}^{arc}(e^{{\mathrm{i}}\theta})+\frac{\beta^2}2\mathbb E[(X\circ f_s)_{\delta,\varepsilon}^{arc}(e^{{\mathrm{i}}\theta})^2]})_{\varepsilon>0}$ becomes a martingale. Define
    \begin{equation*}
        k_\delta(\theta,s):=h(\theta,s)\exp\left(\frac{\beta^2}{2}\left(\mathbb E[(\varphi^{\text{arc}}_\delta)^2(\theta)]-\mathbb E[(X\circ f_s)_{\delta}^{arc}(e^{{\mathrm{i}}\theta})^2]\right)\right).
    \end{equation*}
    Following the proof of \cite[Proposition 5.3]{CILT}, we compute the quadratic variation of  the martingale
    \begin{equation*}
        \mathcal M_{\varepsilon}^{(\delta)}:=\int_0^{T}\int_0^{2\pi} k_\delta(\theta,s)\,e^{{\mathrm{i}} \beta (X\circ f_s)_{\delta,\varepsilon}^{arc}(e^{{\mathrm{i}}\theta})+\frac{\beta^2}2\mathbb E[(X\circ f_s)_{\delta,\varepsilon}^{arc}(e^{{\mathrm{i}}\theta})^2]}\ {\mathrm{d}}\varrho_{\rm v}(\theta){\mathrm{d}} s,
    \end{equation*}
    which is
    \begin{equation*}
    \begin{split}
          &\langle \mathcal M^{(\delta)}\rangle_t-\langle \mathcal M^{(\delta)}\rangle_0\\
          ={}&\beta^2\int_0^t\iint_{([0,T]\times[0,2\pi])^2}k_\delta(\theta_1,s_1)k_\delta(\theta_2,s_2)\sin(\beta (X\circ f_{s_1})_{\delta,e^{-u}}^{arc}(e^{{\mathrm{i}}\theta_1}))\sin(\beta(X\circ f_{s_2})_{\delta,e^{-u}}^{arc}(e^{{\mathrm{i}}\theta_2}))\\
          &\ \ \  \ \  e^{\frac{\beta^2}2(\mathbb E[(X\circ f_{s_1})_{\delta,\varepsilon}^{arc}(e^{{\mathrm{i}}\theta_1})^2]+\mathbb E[(X\circ f_{s_2})_{\delta,\varepsilon}^{arc}(e^{{\mathrm{i}}\theta_2})^2])}\ {\mathrm{d}} s_1{\mathrm{d}}\varrho_{\rm v}(\theta_1){\mathrm{d}} s_2{\mathrm{d}}\varrho_{\rm v}(\theta_2)\  {\mathrm{d}}\langle (X\circ f_{s_1})_{\delta,e^{-u}}^{arc}(e^{{\mathrm{i}}\theta_1}),(X\circ f_{s_2})_{\delta,e^{-u}}^{arc}(e^{{\mathrm{i}}\theta_2})\rangle_u,
    \end{split}
    \end{equation*}
    where for convenience we have assumed $\operatorname{Im}(h)=0$ and $\mu\in\mathbb R$. Next, the quadratic variation of the smooth field is
    \begin{equation*}
        {\mathrm{d}}\langle (X\circ f_{s_1})_{\delta,e^{-u}}^{arc}(e^{{\mathrm{i}}\theta_1}),(X\circ f_{s_2})_{\delta,e^{-u}}^{arc}(e^{{\mathrm{i}}\theta_2})\rangle_u=\frac{\pi e^{-2u}}{\delta^2}\int_{-\delta}^{\delta}\int_{-\delta}^{\delta}p_{e^{-2u}}(f_{s_1}(e^{{\mathrm{i}}(\theta_1+\theta_1')}),f_{s_2}(e^{{\mathrm{i}}(\theta_2+\theta_2')}))\ {\mathrm{d}} \theta_1'{\mathrm{d}} \theta_2'{\mathrm{d}} u.
    \end{equation*}
    Using the bound for the heat kernel \cite{Cheng1981},
    \begin{equation*}
        e^{-2u}p_{e^{-2u}}(f_{s_1}(e^{{\mathrm{i}}(\theta_1+\theta_1')}),f_{s_2}(e^{{\mathrm{i}}(\theta_2+\theta_2')}))\leq C e^{-{|f_{s_1}(e^{{\mathrm{i}}(\theta_1+\theta_1')})-f_{s_2}(e^{{\mathrm{i}}(\theta_2+\theta_2')})|^2e^{2u}}/{C}}
    \end{equation*}
    for some constant $C$, we can again bound the quadratic variation using the integral
 \begin{equation}\label{eq_M_bound}
    \begin{split}
          &\sup_{t\geq0}\langle \mathcal M^{(\delta)}\rangle_t-\langle \mathcal M^{(\delta)}\rangle_0\\
          \leq{}&\frac{C\beta^2}{\delta^2}\int_0^\infty\iint_{([0,T]\times[0,2\pi])^2}|k_\delta(s_1,\theta_1)||k_\delta(s_2,\theta_2)|e^{\frac{\beta^2}2(\mathbb E[(X\circ f_{s_1})_{\delta,e^{-u}}^{arc}(e^{{\mathrm{i}}\theta_1})^2]+\mathbb E[(X\circ f_{s_2})_{\delta,e^{-u}}^{arc}(e^{{\mathrm{i}}\theta_2})^2])}\\
          &\ \ \ \ \ \ \ \ \ \ \ \ \ \ \ \int_{-\delta}^{\delta}\int_{-\delta}^{\delta}e^{-|f_{s_1}(e^{{\mathrm{i}}(\theta_1+\theta_1')})-f_{s_2}(e^{{\mathrm{i}}(\theta_2+\theta_2')})|^2e^{2u}/{C}}\ {\mathrm{d}} \theta_1'{\mathrm{d}}\theta_2'\,{\mathrm{d}} s_1{\mathrm{d}}\varrho_{\rm v}(\theta_1){\mathrm{d}} s_2{\mathrm{d}}\varrho_{\rm v}(\theta_2)\, {\mathrm{d}} u.
    \end{split}
    \end{equation}
When $t$ is small, we have the free heat kernel diagonal bound $ p_t(x,y)\leq\frac{1}{4\pi t}$, while for $t$ large $p_t$ decays exponentially fast in $t$. Thus we have when $u$ large
\begin{equation*}
    \mathbb E[ (X\circ f_{s_1})_{\delta,e^{-u}}^{arc}(e^{{\mathrm{i}}\theta_1})^2]=\frac{\pi}{2\delta^2}\int_{-\delta}^{\delta}\int_{-\delta}^{\delta}\int_{e^{-2u}}^\infty p_t(f_{s_1}(e^{{\mathrm{i}}(\theta_1+\theta')}),f_{s_1}(e^{{\mathrm{i}}(\theta_1+\theta'')}))\ {\mathrm{d}} t\ {\mathrm{d}} \theta'{\mathrm{d}} \theta''\leq C+u,
\end{equation*}
where $C$ is independent of $\delta,s_1,\theta_1$ hence we can replace the variance in \eqref{eq_M_bound} with $u$ uniformly. Finally, integrating out the white noise cut-off ${\mathrm{d}} u$, we are left with
\begin{equation*}
    \frac{C\beta^2}{\delta^2}\iint_{([0,T]\times[0,2\pi])^2}|k_\delta(s_1,\theta_1)||k_\delta(s_2,\theta_2)|\int_{-\delta}^{\delta}\int_{-\delta}^{\delta}|f_{s_1}(e^{{\mathrm{i}}(\theta_1+\theta_1')})-f_{s_2}(e^{{\mathrm{i}}(\theta_2+\theta_2')})|^{-\beta^2}{\mathrm{d}} \theta_1'{\mathrm{d}}\theta_2'\,{\mathrm{d}} s_1{\mathrm{d}}\varrho_{\rm v}(\theta_1){\mathrm{d}} s_2{\mathrm{d}}\varrho_{\rm v}(\theta_2),
\end{equation*}
which is bounded by
\begin{equation}\label{eq_temp_in_GMC_bound}
    \frac{C\beta^2}{\delta^2}\iint_{([0,T]\times[0,2\pi])^2}\int_{-\delta}^{\delta}\int_{-\delta}^{\delta}|k_\delta(s_1,\theta_1+\theta_1')||k_\delta(s_2,\theta_2+\theta_2')|\,{\mathrm{d}} \theta_1'{\mathrm{d}}\theta_2'\,|f_{s_1}(e^{{\mathrm{i}}\theta_1})-f_{s_2}(e^{{\mathrm{i}}\theta_2})|^{-\beta^2}\,{\mathrm{d}} s_1{\mathrm{d}}\varrho_{\rm v}(\theta_1){\mathrm{d}} s_2{\mathrm{d}}\varrho_{\rm v}(\theta_2).
\end{equation}
Besides, by Jensen's inequality,
\begin{equation*}
\begin{split}
    \exp\left(\frac{\beta^2}{2}(\mathbb E[(\varphi^{\text{arc}}_\delta)^2(\theta)]-\mathbb E[(X\circ f_s)_{\delta}^{arc}(e^{{\mathrm{i}}\theta})^2])\right)={}&\exp\left(\frac{\beta^2}{8\delta^2}\int_{-\delta}^\delta\int_{-\delta}^\delta \log\left|\frac {f_s(e^{{\mathrm{i}}(\theta+\theta_1)})-f_s(e^{{\mathrm{i}}(\theta+\theta_2)})}{e^{{\mathrm{i}}(\theta+\theta_1)}-e^{{\mathrm{i}}(\theta+\theta_2)}}\right|{\mathrm{d}}\theta_1{\mathrm{d}}\theta_2\right)\\
    \leq{}&\frac{1}{4\delta^2}\int_{-\delta}^\delta\int_{-\delta}^\delta \exp\left(\frac{\beta^2}{2}\log\left|\frac {f_s(e^{{\mathrm{i}}(\theta+\theta_1)})-f_s(e^{{\mathrm{i}}(\theta+\theta_2)})}{e^{{\mathrm{i}}(\theta+\theta_1)}-e^{{\mathrm{i}}(\theta+\theta_2)}}\right|\right){\mathrm{d}}\theta_1{\mathrm{d}}\theta_2,
\end{split}
\end{equation*}
Since $f_s(z)$ is holomorphic on $\mathbb T$, we have 
\begin{equation*}
      |k_{\delta}(s,\theta)|\leq  |h(s,\theta)|\sup_{\theta'\in[0,2\pi]}|f'_s(e^{{\mathrm{i}}\theta'})|^{\frac{\beta^2}{2}}\leq C |h(s,\theta)|e^{-\frac{\beta^2\operatorname{Re}\omega}{2}s }.
\end{equation*}
We finish the proof by putting the above bound in \eqref{eq_temp_in_GMC_bound}.

\label{lemma_resolvent_technical}
    Let $A\geq c_0I,c_0>0$ be a positive self-adjoint operator on Hilbert space $\mathcal H$. Write $\mathcal W^s:=\mathcal D(A^{\frac s2})$, i.e. the domain under $\|u\|_s:=\|A^{\frac s2}u\|_{\mathcal H}$, with $\|\cdot\|_{\mathcal H}$ the Hilbert norm. Also there is a sequence of bounded operator $(B_n)_{n\geq1}$ satisfying
    \begin{equation*}
        \|e^{-t A}B_ne^{-s A}\|_{\mathcal H\to\mathcal H}\leq C_0(ts)^{-\alpha}e^{-c_1(t+s)},\ \ \ s,t>0,
    \end{equation*}
    where $C_0,c_1>0$ and $0\leq\alpha<\frac12$. Also consider a dense subspace $\mathcal C$ of $\mathcal W^1$ on which $\langle B_n u,v\rangle_{\mathcal H}$ converges for $u,v\in\mathcal C$ and we denote the limit by $\langle B u,v\rangle_{\mathcal H}$. If $u_n\to u$ strongly in $\mathcal H$ and $\sup_{n}\|u_n\|_{1}<\infty$, then $u\in \mathcal W^1$ and $\langle B_n u_n,v\rangle_{\mathcal H}$ converge to $\langle B u,v\rangle_{\mathcal H}$ for all $v\in\mathcal W^r,2\alpha<r<1$.

Fix $2\alpha<r<1$. Since $A^{-\frac r2}=\frac{1}{\Gamma(\frac r2)}\int_0^\infty t^{\frac r2-1}e^{-tA}\,\mathrm{d}t$, it is plain to check that 
   \begin{equation}\label{eq_temp_ABA}
       \|A^{-\frac{r}{2}}B_nA^{-\frac{r}{2}}\|_{\mathcal H\to\mathcal H}\leq\frac{C_0}{\Gamma(\frac r2)^2}\left(\int_0^{\infty}t^{\frac{r}{2}-\alpha-1}e^{-c_1t}\,\mathrm{d}t\right)^2=:C(r)<\infty,
   \end{equation}
   using the bound from $\|e^{-t A}B_ne^{-s A}\|_{\mathcal H\to\mathcal H}$. Hence 
   \begin{equation}\label{eq_temp_bound}
       |\langle B_n u,v\rangle_{\mathcal H}|\leq C(r)\|u\|_r\|v\|_r.
   \end{equation}
   Now let us check the first item. 
   \begin{equation*}
   \begin{split}
        |\langle B_n u_n,v\rangle_{\mathcal H}-\langle Bu,v\rangle_{\mathcal H}|\leq{}&|\langle B_n (u_n-u),v\rangle_{\mathcal H}|+|\langle B_nu,v\rangle_{\mathcal H}-\langle Bu,v\rangle_{\mathcal H}|\\
        \leq{}&C(r)\|u_n-u\|_r\|v\|_r+|\langle B_nu,v\rangle_{\mathcal H}-\langle Bu,v\rangle_{\mathcal H}|.
   \end{split}
   \end{equation*}
   According to \cite[Lemma 2.12]{Ma_1992}, the convergence of $u_n$ in $\mathcal H$ and boundedness in $\mathcal W^1$ imply that $u\in\mathcal W^1$. By H\"older's inequality, we have
   \begin{equation*}
       \|u_n-u\|_r\leq\|u_n-u\|_{\mathcal H}^{1-r}\|u_n-u\|_1^{r}\to0.
   \end{equation*}
   The convergence of $|\langle B_nu,v\rangle_{\mathcal H}-\langle Bu,v\rangle_{\mathcal H}|$ is again from \eqref{eq_temp_bound} with $\mathcal C$ approximation.

Let $g_f$ be an admissible metric on ${\mathbb{A}}_f$ that depends in a $C^1$ fashion on $f$. Since the prefactor $W(f,g_f) $ in \cref{prop_semigroup_as_amplitude} is clearly continuous in $f$, we only need to show the continuity of the annulus amplitude ${\mathcal{A}}_{{\mathbb{A}}_f,g_f,{\boldsymbol{\zeta}}_f}$. Let $\widetilde{\boldsymbol{\varphi}}^k=(\widetilde{{\varphi}}^k_1,\widetilde{{\varphi}}^k_2)\in{\mathcal{D}}'({\mathbb{T}},{\mathbb{T}}_R)^2$ with $k\in{\mathbb{Z}}$. Recall the decompositions $\widetilde{\varphi}_1^k=c_1+\varphi_1+kR\arg$, $\widetilde{\varphi}_2^k=c_2+\varphi_2+kR\arg$ with $c_1,c_2\in{\mathbb{T}}_R$, $\varphi_1,\varphi_2\in{\mathcal{D}}_0'({\mathbb{T}},{\mathbb{R}})$. For $j\in{\mathbb{Z}}$, recall ${\mathbf{c}}_j:=(c_1+2\pi Rj,c_2)$ and the $1$-form $\nu_{f,k}$ on ${\mathbb{A}}_f$
\begin{equation*}
    \nu_{f,k}:= kR\, d\arg+\,d P(0,k R(\arg f^{-1}-\arg)|_{f(\mathbb T)}),
\end{equation*}
where $P=P_{{\mathbb{A}}_f}$ is the Poisson operator on ${\mathbb{A}}_f$, i.e., $P(h_1,h_2)$ is the unique harmonic function on ${\mathbb{A}}_f$ that equals $h_1$ on $\mathbb T$ and $h_2$ on $f(\mathbb T)$. Then by definition,
    \begin{equation*}
    \begin{split}
        {\mathcal{A}}_{{\mathbb{A}}_f,g_f,{\boldsymbol{\zeta}}_f}(\widetilde{\boldsymbol{\varphi}}^k)={}&\det(\Delta_{\mathbb A_f,g_f,\mathrm{D}})^{-1/2}e^{-\frac1{4\pi} \int_{{\mathbb{A}}_f}|\nu_{f,k}|^2_{g_f}{\mathrm{d}} v_{g_f}}\sum_{j\in\mathbb Z}e^{-\frac{1}{2\pi}\int_{\partial\mathbb A_f}P({\mathbf{c}}_j+\boldsymbol{\varphi})\,\nu_{f,k}({\mathbf{n}})\,{\mathrm{d}}\ell_{g_f}-\frac1{2}\langle{\mathbf{c}}_j+\boldsymbol{\varphi},(\mathbf{D}_{{\mathbb{A}}_f}-\mathbf D)({\mathbf{c}}_j+\boldsymbol{\varphi})\rangle} \\
        \times&\mathbb E_{\widetilde{\boldsymbol{\varphi}}^k}[e^{-\frac{{\mathrm{i}} Q}{4\pi}\int_{{\mathbb{A}}_f}^{\mathrm{reg}}K_{g_f}X_{g_f}^{k,j}\,{\mathrm{d}} v_{g_f}-\mu\int_{{\mathbb{A}}_f}M_\beta(X_{g_f}^{k,j},{\mathrm{d}} v_{g_f})}].
    \end{split}
\end{equation*}

And
\[X_{g_f}^{k,j}:=I(\nu_{f,k})+P ({\mathbf{c}}_j+{\boldsymbol{\varphi}})+X_{g_f},\]
where $I(\nu_{f,k})(z):=\int_1^z \nu_{f,k}$ (see \cref{Sec_background} for the choice of arc $d_f$) and $X_{g_f}$ is the Dirichlet GFF on the annulus ${\mathbb{A}}_f$. Here the curvature term $\int_{{\mathbb{A}}_f}^{\mathrm{reg}}K_{g_f}X_{g_f}^{k,j}\,{\mathrm{d}} v_{g_f}$ is regularized as in \cite[Section 5]{BCILT} as
\begin{equation*}
    \int_{{\mathbb{A}}_f}^{\mathrm{reg}}K_{g_f}I(\nu_{f,k})\,{\mathrm{d}} v_{g_f}:= \int_{{\mathbb{A}}_f}K_{g_f}I(\nu_{f,k})\,{\mathrm{d}} v_{g_f}-4\pi Rk\int_{d_f}k_{g_f}{\mathrm{d}} \ell_{g_f},
\end{equation*}
where $k_{g_f}$ is the geodesic curvature and ${\mathrm{d}}\ell_{g_f}$ is the length measure under metric $g_f$.


    Consider a sequence $(f_n)_n$ that converges to $f$. Then there exists $\varepsilon>0$ such that $f_n,f\in{\mathcal{S}}_\varepsilon$ for all $n$ large enough and $f_n\to f$ under $\|\!\cdot\!\|_{\varepsilon,\ell}$ for all $\ell$. Then we can similarly introduce $X_{g_{f_n},k,j}$. In the following, we denote $X_{g_{f_n},k,j}$ by $X_{n}^{k,j}$ ($X^{k,j}:=X_{g_f}^{k,j}$ as well) and $X_n$ ($X$ resp.) for the Dirichlet GFF on ${\mathbb{A}}_{f_n}$ (${\mathbb{A}}_f$ resp.). Similarly, we have $P_n({\mathbf{c}}_j+\boldsymbol{\varphi})$ and $P({\mathbf{c}}_j+\boldsymbol{\varphi})$ for the harmonic extension on $\mathbb A_{f_n}$ and $\mathbb A_{f}$ then $\nu_{f_n,k}^{n},d_{f_n},{\mathbf{n}}_n$ for the 1-form, the separating arc and outward normal vector on $\mathbb A_{f_n}$. We also replace the surface $(\mathbb A_{f_n},g_{f_n}),(\mathbb A_{f},g_f)$, the volume form ${\mathrm{d}} v_{g_{f_n}},{\mathrm{d}} v_{g_f}$, and the curvature $K_{g_{f_n}},K_{g_f}$,  with $(\Sigma_n,g_n),(\Sigma,g)$, ${\mathrm{d}} v_n,{\mathrm{d}} v$ and $K_n,K$. Take $0<\xi<\varepsilon$ and consider the subset 
    \begin{equation*}
        \Sigma^{\xi}:=(\Sigma\backslash f((1+\xi)\mathbb D))\cap(1-\xi)\mathbb D.
    \end{equation*}

Let
\begin{equation*}
 \begin{split}
    \mathcal A_{j,n}^0(\widetilde{{\boldsymbol{\varphi}}}^k):={}&\det(\Delta_{\Sigma_n,g_n,\mathrm{D}})^{-1/2}\exp\Bigg(-\frac1{4\pi}\int_{\Sigma_n}|\nu_{f_n,k}|^2_{g_{n}}{\mathrm{d}} v_{n}\\
    -&\frac1{2\pi}\int_{\partial\Sigma_n}P_n({\mathbf{c}}_j+\boldsymbol{\varphi})\,\nu_{f_n,k}({\mathbf{n}}_n)\,{\mathrm{d}}\ell_{n}-\frac1{2}\langle{\mathbf{c}}_j+\boldsymbol{\varphi},(\mathbf{D}_{\Sigma_n}-\mathbf D)({\mathbf{c}}_j+\boldsymbol{\varphi})\rangle\Bigg),
\end{split}
\end{equation*}
and $\mathcal A^0_j(\widetilde{{\boldsymbol{\varphi}}}^k)$ accordingly for $\Sigma$ and $f$. In the following proof, we will focus on a fixed $k\in\mathbb Z$. Indeed, first notice that $|{\mathcal{A}}_{{\mathbb{A}}_{f_n},g_{f_n},{\boldsymbol{\zeta}}_{f_n}}|\leq C\sum_{j\in\mathbb Z}\mathcal A^0_{j,n}$ and $|{\mathcal{A}}_{{\mathbb{A}}_{f},g_{f},{\boldsymbol{\zeta}}_{f}}|\leq C\sum_{j\in\mathbb Z}\mathcal A^0_j$ for some constant $C>0$ that does not depend on $\widetilde{{\boldsymbol{\varphi}}}$, $k$ and $n$, because of \cite[Proposition 5.3]{CILT}. According to the first item in  \cref{lem_continuity_tech}, the norm estimate of $\sum_{|k|\geq K}{\mathcal{A}}_{{\mathbb{A}}_{f_n},g_{f_n},{\boldsymbol{\zeta}}_{f_n}}(\widetilde{\boldsymbol{\varphi}}^k)$ for some large $K>0$ is dominated by the norm of $\sum_{|k|\geq K}\sum_{j\in\mathbb Z}\mathcal A^0_j$.


For $n$ large enough, we have $\Sigma^{\xi}\subset\Sigma_n$ and $ {\mathcal{A}}_{{\mathbb{A}}_{f_n},g_{f_n},{\boldsymbol{\zeta}}_{f_n}}(\widetilde{\boldsymbol{\varphi}}^k)=A_{n,\xi}^{(1)}+A_{n,\xi}^{(2)}$, where
\begin{equation*}
    A_{n,\xi}^{(1)}:=\sum_{j\in\mathbb Z}\mathcal  A_{j,n}^0(\widetilde{{\boldsymbol{\varphi}}}^k) \mathbb E_{\widetilde{\boldsymbol{\varphi}}^k}[e^{-\frac{{\mathrm{i}} Q}{4\pi}\int_{\Sigma_n}^{\mathrm{reg}}K_{n}X_{n}^{k,j}\,{\mathrm{d}} v_n-\mu\int_{\Sigma^{\xi}}M_\beta(X_{n}^{k,j},{\mathrm{d}} v_n)}],
\end{equation*}
and
\begin{equation*}
\begin{split}
     A_{n,\xi}^{(2)}:={}&\sum_{j\in\mathbb Z}\mathcal  A_{j,n}^0(\widetilde{{\boldsymbol{\varphi}}}^k) \mathbb E_{\widetilde{\boldsymbol{\varphi}}^k}[e^{-\frac{{\mathrm{i}} Q}{4\pi}\int_{\Sigma_n}^{\mathrm{reg}}K_{n}X_{n}^{k,j}\,{\mathrm{d}} v_n}(e^{-\mu\int_{\Sigma_n}M_\beta(X_{n}^{k,j},{\mathrm{d}} v_n)}-e^{-\mu\int_{\Sigma^{\xi}}M_\beta(X_{n}^{k,j},{\mathrm{d}} v_n)})].
\end{split}
\end{equation*}
By applying Cauchy-Schwarz inequality to the expectation in $ A_{n,\xi}^{(2)}$, we have
\begin{equation*}
    |A_{n,\xi}^{(2)}|\leq \sum_{j\in\mathbb Z}\mathcal  A_{j,n}^0(\widetilde{{\boldsymbol{\varphi}}}^k)  \mathcal K_{n,\xi}^{k,j}(\widetilde{\boldsymbol{\varphi}}^k)\mathbb E_{\widetilde{\boldsymbol{\varphi}}^k}[|e^{-\mu\int_{\Sigma^{\xi}}M_\beta(X_{n}^{k,j},{\mathrm{d}} v_n)}|^2]^{\frac12},
\end{equation*}
where
\begin{equation*}
    \mathcal K_{n,\xi}^{k,j}(\widetilde{\boldsymbol{\varphi}}^k):=\mathbb E_{\widetilde{\boldsymbol{\varphi}}^k}[|e^{-\mu\int_{\Sigma_n\backslash\Sigma^{\xi}}M_\beta(X_{n}^{k,j},{\mathrm{d}} v_n)}-1|^2]^{\frac12}.
\end{equation*}
Using the fact that $|e^z-1|^2\leq (e^{|z|}-1)^2\leq e^{2|z|}-1$ for all $z\in\mathbb C$, we can bound $ \mathcal K_{n,\xi}^{k,j}(\widetilde{\boldsymbol{\varphi}}^k)$ with
\begin{equation}\label{eq_K_bound}
