\end{equation}
According to \cite[Proposition 5.3]{CILT}, for some constant $C$ only depending on $\beta$, the above is bounded by
\begin{equation*}
   \sqrt{ e^{C|\mu| w}(1+2|\mu| u e^{C|\mu|^2 u^2})-1},
\end{equation*}
where
\begin{equation}\label{eq_metric_integral_continuity}
    u^2:=\iint_{(\Sigma_n\backslash\Sigma^{\xi})^2}d_{g_n}(x,y)^{-\beta^2}\ dv_n(x){\mathrm{d}} v_n(y), \ \ \ w:=\int_{\Sigma_n\backslash\Sigma^{\xi}}d_{g_n}(x,\partial\Sigma_n)^{-\frac{\beta^2}2}\ {\mathrm{d}} v_n(x).
\end{equation}


Then by \cite[Lemma 4.5]{Guillarmou2021}, the first and second item in \cref{lem_continuity_tech}, $A_{n,\xi}^{(2)}$ yields an operator on $\mathcal H$ with norm $(\iint |A_{n,\xi}^{(2)}|^2 ({\mathrm{d}}\widetilde{\varphi}^k)^{\otimes2})^{1/2}$ of order $\xi^{\frac12-\frac{\beta^2}{4}}$. 

Similarly, we write $ {\mathcal{A}}_{{\mathbb{A}}_{f},g_{f},{\boldsymbol{\zeta}}_{f}}(\widetilde{\boldsymbol{\varphi}}^k)=A_{\xi}^{(1)}+A_{\xi}^{(2)}$, where
\begin{equation*}
    A_{\xi}^{(1)}:=\sum_{j\in\mathbb Z}\mathcal A_{j}^0(\widetilde{{\boldsymbol{\varphi}}}^k) \mathbb E_{\widetilde{\boldsymbol{\varphi}}^k}[e^{-\frac{{\mathrm{i}} Q}{4\pi}\int_{\Sigma}^{\mathrm{reg}}KX^{k,j}\,{\mathrm{d}} v-\mu\int_{\Sigma^{\xi}}M_\beta(X^{k,j},{\mathrm{d}} v)}],
