\end{equation*}
and
\begin{equation*}
    \begin{split}
   B_{n,\xi}^{(2)}:={}&\sum_{j\in\mathbb Z}(\mathcal  A_{j,n}^0(\widetilde{{\boldsymbol{\varphi}}}^k)-\mathcal  A_{j}^0(\widetilde{{\boldsymbol{\varphi}}}^k))
   \mathbb E_{\widetilde{\boldsymbol{\varphi}}^k}[e^{-\frac{{\mathrm{i}} Q}{4\pi}\int_{\Sigma_n}^{\mathrm{reg}}K_{n}X_{n}^{k,j}\,{\mathrm{d}} v_n-\mu\int_{\Sigma^{\xi}}M_\beta(X_{n}^{k,j},{\mathrm{d}} v_n)}].
\end{split}
\end{equation*}
The estimate of $B_{n,\xi}^{(2)}$ is a consequence of the third item in \cref{lem_continuity_tech} together with \cite[Theorem 6.11]{CILT}. We will now focus on $B_{n,\xi}^{(1)}$. First using the imaginary Cameron--Martin theorem (the proof of \cite[Theorem 6.11]{CILT}), $B_{n,\xi}^{(1)}$ can be written as
\begin{equation}\label{eq_B1}
\begin{split}
     B_{n,\xi}^{(1)}={}&\sum_{j\in\mathbb Z}\mathcal  A_{j}^0(\widetilde{{\boldsymbol{\varphi}}}^k)(e^{-\frac{{\mathrm{i}} Q}{4\pi}\int_{\Sigma_n}^{\mathrm{reg}}K_{n}(X_n^{k,j}-X_n)\,{\mathrm{d}} v_n-\frac{Q^2}{32\pi^2}\int K_n\ \mathcal G_n\ {\mathrm{d}} v_n}\ \mathbb E_{\widetilde{\boldsymbol{\varphi}}^k}[e^{-\mu\int_{\Sigma^{\xi}}M_\beta(X_n^{k,j}-\frac{{\mathrm{i}} Q}{4\pi}\mathcal G_n,{\mathrm{d}} v_n)}]\\
    -&e^{-\frac{{\mathrm{i}} Q}{4\pi}\int_{\Sigma}^{\mathrm{reg}}K (X^{k,j}-X)\,{\mathrm{d}} v-\frac{Q^2}{32\pi^2}\int K\ \mathcal G\ {\mathrm{d}} v}\ \mathbb E_{\widetilde{\boldsymbol{\varphi}}^k}[e^{-\mu\int_{\Sigma^{\xi}}M_\beta(X^{k,j}-\frac{{\mathrm{i}} Q}{4\pi}\mathcal G,{\mathrm{d}} v)}]),
