\end{equation}
where $\mathcal G_n(x):=\int_{\Sigma_n}K_n(x')G_n(x,x')\ {\mathrm{d}} v_n(x')$ and $(2\pi)^{-1}G_n$ is the Green's function on $\Sigma_n$ with Dirichlet boundary conditions ($\mathcal G(x)$ is similarly defined). Suppose $g_n=e^{\rho_n}g$ on $\Sigma^\xi$ and it is not hard to see that $\sup_{\Sigma^\xi}|\rho_n|\to0$. Recall that
\begin{equation*}
    e^{(\frac{\beta^2}{4}-1)\rho_n} M_\beta(X_n^{k,j}-\frac{{\mathrm{i}} Q}{4\pi}\mathcal G_n,{\mathrm{d}} v_n)= M_\beta(X_n^{k,j}-\frac{{\mathrm{i}} Q}{4\pi}\mathcal G_n,{\mathrm{d}} v),
\end{equation*}
where $e^{\frac{\beta^2}{4}\rho_n}$ is the effect of changing the metric regularisation for GFF. Then we can replace the term containing $\mathbb E_{\widetilde{\boldsymbol{\varphi}}^k}[e^{-\mu\int_{\Sigma^{\xi}}M_\beta(X_n^{k,j}-\frac{{\mathrm{i}} Q}{4\pi}\mathcal G_n,{\mathrm{d}} v_n)}]$ in \eqref{eq_B1} with $\mathbb E_{\widetilde{\boldsymbol{\varphi}}^k}[e^{-\mu\int_{\Sigma^{\xi}}M_\beta(X_n^{k,j}-\frac{{\mathrm{i}} Q}{4\pi}\mathcal G,{\mathrm{d}} v)}]$ if we can control
\begin{equation}\label{eq_B3}
\begin{split}
