    -&e^{-\frac{{\mathrm{i}} Q}{4\pi}\int_{\Sigma_n}^{\mathrm{reg}}K_{n}(X_n^{k,j}-X_n)\,{\mathrm{d}} v_n-\frac{Q^2}{32\pi^2}\int K_n\ \mathcal G_n\ {\mathrm{d}} v_n}\ \mathbb E_{\widetilde{\boldsymbol{\varphi}}^k}[e^{-\mu\int_{\Sigma^{\xi}}M_\beta(X_n^{k,j}-\frac{{\mathrm{i}} Q}{4\pi}\mathcal G_n,{\mathrm{d}} v_n)}]).
\end{split}
\end{equation}
For each $j\in\mathbb Z$, the convergence of the term $e^{-\frac{{\mathrm{i}} Q}{4\pi}\int_{\Sigma_n}^{\mathrm{reg}}K_{n}\ (X_n^{k,j}-X_n)\,{\mathrm{d}} v_n-\frac{Q^2}{32\pi^2}\int K_n\ \mathcal G_n\ {\mathrm{d}} v_n}$ above is already addressed in \cite[Proposition 3.11]{Segal_semigroup} (and the convergence of $\int_{d_{f_n}}k_{g_{f_n}}{\mathrm{d}} \ell_{g_{f_n}}$ is straightforward), then we apply the dominated convergence theorem. And according to \cite[Lemma 3.12]{Segal_semigroup} and \cite[Proposition 5.3]{CILT}, we can bound the GMC difference in \cref{eq_B3} since $\sup_{\Sigma^\xi}|\rho_n|\to0$ and $\sup_{\Sigma^\xi}|\mathcal G_n-\mathcal G|\to0$ \cite[Lemma 3.12 (3)]{Segal_semigroup}.

For the rest of the proof, we just need to show that
\begin{equation}\label{eq_goal_conv_B1}
    \iint \left|\sum_{j\in\mathbb Z}\mathcal  A_{j}^0(\widetilde{{\boldsymbol{\varphi}}}^k)|\mathbb E_{\widetilde{\boldsymbol{\varphi}}^k}[e^{-\mu\int_{\Sigma^{\xi}}M_\beta(X_n^{k,j}-\frac{{\mathrm{i}} Q}{4\pi}\mathcal G,{\mathrm{d}} v)}]-\mathbb E_{\widetilde{\boldsymbol{\varphi}}^k}[e^{-\mu\int_{\Sigma^{\xi}}M_\beta(X^{k,j}-\frac{{\mathrm{i}} Q}{4\pi}\mathcal G,{\mathrm{d}} v)}]|\right|^2({\mathrm{d}}\widetilde{\varphi}^k)^{\otimes2}<\xi
 \end{equation}
for suitably large $n$. Note that we now compare two different GFFs so we cannot use \cite[Proposition 5.3]{CILT} directly. Instead, using the Taylor expansion of the exponential, we obtain
\begin{equation}\label{eq_int_expand}
\begin{split}
     &\mathbb E_{\widetilde{\boldsymbol{\varphi}}^k}[e^{-\mu\int_{\Sigma^{\xi}}M_\beta(X_n^{k,j}-\frac{{\mathrm{i}} Q}{4\pi}\mathcal G,{\mathrm{d}} v)}]=\sum_{s\geq0}\frac{(-\mu)^s}{s!}\mathbb E_{\widetilde{\boldsymbol{\varphi}}^k}[(\int_{\Sigma^{\xi}}e^{\frac{\beta Q}{4\pi}\mathcal G} M_\beta(X_n^{k,j},{\mathrm{d}} v))^s]\\
     ={}&\sum_{s\geq0}\frac{(-\mu)^s}{s!}\int_{(\Sigma^\xi)^s}e^{-\beta^2\sum_{r<l} G_n(x_r,x_l)}e^{\beta(\sum_{r=1}^s\frac{ Q}{4\pi}\mathcal G(x_r)+{\mathrm{i}}(X_n^{k,j}(x_r)-X_n(x_r))  )}e^{-\frac{\beta^2}{2}\sum_{r=1}^sW_{n}(x_r)}\ \prod_r{\mathrm{d}} v(x_r),
\end{split}
\end{equation}
where $W_{n}$ is the Robin mass of $X_n$ under the regularisation of the metric $g$, namely
\begin{equation*}
    W_{n}(x):=\lim_{\delta\to0}\mathbb E[X^2_{n,\delta}(x)]+\log\delta.
\end{equation*}
Let us consider the Dirichlet GFF $X^{\xi}$ on $\Sigma^\xi$. Since $\Sigma^\xi\subset \cap_{n\geq N}\Sigma_n$, we have the monotonicity of the $X^{\xi}$ Green's function $G^{\xi}\leq G_n$ on $(\Sigma^{\xi})^2$ and Robin mass $W^\xi\leq W_{n}$ on $\Sigma^{\xi}$. Thus the second line in \eqref{eq_int_expand} is further bounded by
\begin{equation}\label{eq_expansion_bound}
\begin{split}
    \sum_{s\geq0}\frac{|\mu|^s}{s!}\int_{(\Sigma^\xi)^s}e^{-\beta^2\sum_{r<l} G^\xi(x_r,x_l)}e^{\beta\sum_{r=1}^s\frac{ Q}{4\pi}\mathcal G(x_r)}e^{-\frac{\beta^2}{2}\sum_{r=1}^sW^\xi(x_r)}\ {\mathrm{d}} v(x)
    =\mathbb E[e^{|\mu|\int_{\Sigma^{\xi}}M_\beta(X^\xi-\frac{{\mathrm{i}} Q}{4\pi}\mathcal G,{\mathrm{d}} v)}].
\end{split}
\end{equation}
Therefore, for each moment in the expansion of \eqref{eq_int_expand}, we provide a uniform bound independent of $n,k,j$ and $\widetilde{\boldsymbol{\varphi}}^k$. For each $\xi>0$, we can pick a large $S$, such that 
\begin{equation*}
    \sum_{s\geq S}\frac{(-\mu)^s}{s!}\mathbb E_{\widetilde{\boldsymbol{\varphi}}^k}[(\int_{\Sigma^{\xi}}e^{\frac{\beta Q}{4\pi}\mathcal G} M_\beta(X_n^{k,j},{\mathrm{d}} v))^s]
\end{equation*}
 is arbitrarily small, uniformly over $n,k,j$ and $\widetilde{\boldsymbol{\varphi}}^k$. For $s<S$, we clearly have that the integral
 \begin{equation*}
     \int_{(\Sigma^\xi)^s}e^{-\beta^2\sum_{r<l} G_n(x_r,x_l)}e^{\beta\sum_{r=1}^s(\frac{ Q}{4\pi}\mathcal G(x_r)+{\mathrm{i}}(X_n^{k,j}-X_n))}e^{-\frac{\beta^2}{2}\sum_{r=1}^sW_{n}(x_r)}\ {\mathrm{d}} v(x)
 \end{equation*}
 converges to the one corresponding to $X$ since $\sup_{(\Sigma^\xi)^2}|G_n-G|$ and $\sup_{\Sigma^\xi}|P_n\widetilde{\boldsymbol{\varphi}}^k-P\widetilde{\boldsymbol{\varphi}}^k|$ goes to zero when $n$ gets large as stated in \cite[Lemma 3.12 (2),(4)]{Segal_semigroup} (semigroup lemma). We thus have \eqref{eq_goal_conv_B1} using dominated convergence theorem by \eqref{eq_expansion_bound}.

\label{lem_continuity_tech}
Follow the notation in \cref{prop_Tf_continuity}. Fix $\varepsilon>0$. Let $f_n\to f$ in $\mathcal S_\varepsilon$ under Fréchet topology, and $(\Sigma_n,g_n):=(\mathbb A_{f_n},g_{f_n})$, $(\Sigma,g):=(\mathbb A_f,g_f)$. Similarly, we have $v_n,v,\ell_n,\ell$. Let $\Sigma^{\xi}:=(\Sigma\backslash f((1+\xi)\mathbb D))\cap(1-\xi)\mathbb D,0<\xi<\varepsilon.$ 

Then:

    \begin{enumerate}[label=\emph{(\arabic*)}]




        \item Let 
\begin{equation*}
 \begin{split}
    \mathcal A_{j,n}^0(\widetilde{{\boldsymbol{\varphi}}}^k):={}&\det(\Delta_{\Sigma_n,g_n,\mathrm{D}})^{-1/2}\exp\Bigg(-\frac1{4\pi}\int_{\Sigma_n}|\nu_{f_n,k}|^2_{g_{n}}{\mathrm{d}} v_{n}\\
    -&\frac1{2\pi}\int_{\partial\Sigma_n}P_n({\mathbf{c}}_j+\boldsymbol{\varphi})\,\nu_{f_n,k}({\mathbf{n}}_n)\,{\mathrm{d}}\ell_{n}-\frac1{2}\langle{\mathbf{c}}_j+\boldsymbol{\varphi},(\mathbf{D}_{\Sigma_n}-\mathbf D)({\mathbf{c}}_j+\boldsymbol{\varphi})\rangle\Bigg),
\end{split}
\end{equation*}
and $\mathcal A^0_j(\widetilde{{\boldsymbol{\varphi}}}^k)$ accordingly for $\Sigma$ and $f$. Then
\begin{equation*}
   \lim_{n\to\infty}\left\|\sum_{j\in\mathbb Z} \mathcal A_{j,n}^0(\widetilde{{\boldsymbol{\varphi}}}^k)-\sum_{j\in\mathbb Z}\mathcal A_{j}^0(\widetilde{{\boldsymbol{\varphi}}}^k)\right\|_{\mathcal H^{\otimes2}}=0.
\end{equation*}










        \item For $\xi$ small and $n$ large enough (depending on $\xi$), there exists some $C>0$ depending on $f,\beta$,
\begin{equation*}
            \iint_{(\Sigma_n\backslash\Sigma^{\xi})^2}d_{g_n}(x,y)^{-\beta^2}\ dv_n(x){\mathrm{d}} v_n(y)\leq C\xi^{2-\beta^2},\ \ \ \int_{\Sigma_n\backslash\Sigma^{\xi}}d_{g_n}(x,\partial\Sigma_n)^{-\frac{\beta^2}2}\ {\mathrm{d}} v_n(x)\leq C \xi^{1-\frac{\beta^2}{2}}.
        \end{equation*}
        \item Fix $k\in\mathbb Z$ and let $\mathcal H_k$ be the subspace of $\mathcal H$ with winding $k$. Then there exists $C>0,\delta_n\to0^+$ independent of $j$ s.t. when $n$ large enough,
\begin{equation*}
    \|A_{j,n}^0(\widetilde{{\boldsymbol{\varphi}}}^k)-A_{j}^0(\widetilde{{\boldsymbol{\varphi}}}^k)\|_{\mathcal H_k^{\otimes2}}\leq \delta_ne^{-Cj^2}.
\end{equation*}
    \end{enumerate}

\begin{enumerate}[label=(\arabic*)]










\item Notice that $\mathcal A^0_n$ is just a free field annulus amplitude and $\| \mathcal A_{n}^0(\widetilde{{\boldsymbol{\varphi}}}^k)-\mathcal A_{}^0(\widetilde{{\boldsymbol{\varphi}}}^k)\|_{\mathcal H^{\otimes2}}$ consists of partition functions of gluing $\Sigma_n$ (or $\Sigma$) with $\Sigma$ (or $\Sigma_n$). Take the gluing of $\Sigma_n$ and reflected $\Sigma_n$ as an example. The convergence of $(\Sigma_n,g_n)$ makes sure that the determinant and the harmonic representatives of the monodromy also converge, so the partition function converges to that of $\Sigma$ gluing reflected $\Sigma$ as well. Thus we obtain the convergence.





















\item  Recall that $h_n(f_n(z))=\log\frac{|zf_n'(z)|}{|f_n(z)|}$ on a neighborhood of $f(\mathbb D)$ and $g_n=e^{-2 h_n\chi}\frac{|{\mathrm{d}} z|^2}{|z|^2}$, where $\chi\in C^{\infty}(\cup_{n\geq N}\Sigma_n)$ for some large $N$ is equal to $1$ near $f(\mathbb T)$ and $0$ near $\mathbb T$. It is not hard to see that $h_n$ converges to $h$ uniformly on $\cap_{n\geq N}\Sigma_n$. 

    When $n>N$, we have $C^{-1} e^{-2h}\leq e^{-2 h_n\chi}\leq Ce^{-2 h}$ in the region $\cup_{n\geq N}\Sigma_n\backslash\Sigma^{\xi_0}\cap(1-\xi_0)\mathbb D$ for a fixed $\xi_0>0$, where the constant $C$ does not depend on $\xi$ and $n$. First notice that $\Sigma_n\backslash\Sigma^{\xi}$ contains two collars: the inner one $\Sigma_n\backslash\Sigma^{\xi}\cap(1-\xi)\mathbb D$ and the outer one near $\mathbb T$. The two collars do not intersect when $\xi$ is sufficiently small, and we will only estimate the integral for the inner one, since the other ones are simple. Besides, when $n$ is large enough, $f_n^{-1}((\Sigma_n\backslash\Sigma^{\xi})\cap(1-\xi)\mathbb D)\subset (1+C'\xi)\mathbb D$ and the two integrals in \eqref{eq_metric_integral_continuity} restricted to $(\Sigma_n\backslash\Sigma^{\xi})\cap(1-\xi)\mathbb D)$ are further bounded by
\begin{equation*}
   \iint_{(\mathbb A_{1,1+C'\xi})^2}|x-y|^{-\beta^2}\ {\mathrm{d}} x{\mathrm{d}} y, \ \ \ \int_{1}^{1+C'\xi}|r-1|^{-\frac{\beta^2}2}r\ {\mathrm{d}} r,
\end{equation*}
where $\mathbb A_{1,1+C'\xi}:=\{z:1\leq|z|\leq 1+C'\xi\}$ ($C'\xi<\varepsilon$). Therefore we complete the proof.
\item It is plain to see that $\nu_{f_n,1}({\mathbf{n}}_n)$ is smooth on $\partial\Sigma_n$ and converges in $C^\infty$ to $\nu_{f,1}({\mathbf{n}})$, therefore the proof follows from \cite[Lemma 3.12 (6)]{Segal_semigroup}. Especially,
\begin{equation*}
    |\log A_{j,n}^0(\widetilde{{\boldsymbol{\varphi}}}^k)-\log A_{j}^0(\widetilde{{\boldsymbol{\varphi}}}^k)|\leq \delta'_n(1+j^2+k^2+\|{\boldsymbol{\varphi}}\|_{H^{-s}}^2),
\end{equation*}
where $\delta'_n\to0^+$ and $\|{\boldsymbol{\varphi}}\|_{H^{-s}}$ is the norm on Sobolev space $H^{-s}(\mathbb T)^{2},s>0$.\qedhere
 \end{enumerate}

\label{assmp_diff}
   \mbox{}
    \begin{enumerate}[label=(\arabic*), ref=\arabic*]
        \item\label{itm_diff_1} There exists a measure space $(M,\mu_0)$ such that, if $\mathcal H=L^2(M,\mu_0)$ is the Hilbert space of square integrable functions, we are given a general quadratic form $\mathcal Q$ and a symmetric positive one $\widetilde{\mathcal Q}^0$ with $\mathcal D(\mathcal Q)=\mathcal D(\widetilde{\mathcal Q}^0)\subset \mathcal H$. The form $\mathcal Q$ generates a continuous semigroup $(e^{-t\mathbf H})_{t\geq0}$ on $\mathcal H$, with a non self-adjoint generator $\mathbf H$. The semigroup also maps $\mathcal D'(\widetilde{\mathcal Q}^0)\to\mathcal D(\widetilde{\mathcal Q}^0)$ continuously. The form $\widetilde{\mathcal Q}^0$ corresponds to a positive self-adjoint operator $\widetilde{\mathbf H}^0$. The Sobolev-like norm $\langle F,G\rangle_{\widetilde{\mathbf H}^0,s}:=\langle ({\widetilde{\mathbf H}^0})^sF,G\rangle_{L^2}$ induces space $W^s$ as the closure of $F\in{\mathcal{E}}({\mathcal{D}}'({\mathbb{T}},{\mathbb{T}}_R))$ with $\|F\|_{\widetilde{\mathbf H}^0,s}$. 
        \item We are given a closed subset $\mathcal {AS}$ of $\mathcal S$, stable by composition, and then we consider the space $\mathcal{AS}_\varepsilon:=\mathcal {AS}\cap \mathcal{S}_\varepsilon$ equipped with the induced topology. Let $\mathcal A\mathrm{Hol}^{\bullet}(\mathbb D)\subset \mathrm{Hol}^{\bullet}(\mathbb D)$ be the tangent space of $\mathcal{AS}$ and $\mathcal A\mathrm{Hol}^{\bullet}_\varepsilon(\mathbb D):=\mathcal A\mathrm{Hol}^{\bullet}(\mathbb D)\cap \mathrm{Hol}^{\bullet}_\varepsilon(\mathbb D)$.
        \item The subspace $\mathcal {AS}$ is preserved by the flow. More precisely, let $v\in\mathcal{A}\mathrm{Hol}^{\bullet}_\varepsilon(\mathbb D)$ Markovian and $f_0\in\mathcal{AS}_{\varepsilon}$ (resp. $f_0(z)=z$). Then there exists $\varepsilon'<\varepsilon$ (locally uniform in $v$ and depending on $f_0$) s.t. the solution $f_t$ to the flow $\partial_t f_t=v(f_t)$ belongs to $\mathcal{AS}_{\varepsilon'}$ for all $t\geq0$ (resp. for all $t>0$).
        \item If $f\in\mathcal{AS}_\varepsilon$ then for $t_0>0$ small enough, $e^{t_0}f(e^{t_0}\cdot)\in\mathcal{AS}_{\varepsilon'}$, where $(1+\varepsilon')e^{t_0}=1+\varepsilon$.
        \item\label{itm_5} For $f\in\mathcal {AS}$, the operator $\mathbf T_f$ extends to a bounded operator on $\mathcal H$, i.e. $\mathbf T_f\in\mathcal L(\mathcal H)$ and obeys the composition rule $\mathbf T_{f_1}\circ\mathbf T_{f_2}=\mathbf T_{f_1\circ f_2}$.
        \item\label{itm_6} The mapping $f\in\mathcal {AS}\mapsto \mathbf T_f$ is continuous in $\mathcal L(\mathcal H)$.
        \item\label{itm_diff_7} There exists a  linear map $v\in\cup_{\varepsilon>0}\mathcal A {\mathrm{Hol}^\bullet_\varepsilon(\mathbb D) }\to \mathcal Q_{\rm v}$ where ${\rm v}=v(z)\partial_z$ and $\mathcal Q_{\rm v}$ is a continuous sesquilinear form on $\mathcal D(\widetilde{\mathcal Q}^0)^2$, equipped with $\widetilde{\mathcal Q}^0$-norm. For all $\varepsilon>0$, the restriction of this map $v\in\mathcal A {\mathrm{Hol}^\bullet_\varepsilon(\mathbb D) }\to \mathcal Q_{\rm v}$ is $\|\cdot\|_{\varepsilon,s}$-continuous (for some $s\geq0$).
        \item\label{itm_coercivity} Let ${\rm v}=v(z)\partial_z$ with $v(z)=-\sum_{n\geq0}v_n z^{n+1}\in\mathcal A {\mathrm{Hol}^\bullet_\varepsilon(\mathbb D)}$. If $\operatorname{Re}\omega>0$ is large enough in the sense that there exists $C'>0$ and $s>0$ such that $v$ satisfies

\begin{equation*}
    D(v):=\operatorname{Re}\omega-C'(|\operatorname{Im}\omega|^2+\sum_{n\geq-1,n\not=0}(1+|n|)^{2s}|v_n|^2)^{1/2}>0,
\end{equation*}
then the bilinear form $\mathcal Q_{\rm v}$ generates a semigroup $(e^{-t\mathbf H_{\rm v}})_{t\geq0}$ on $\mathcal H$, for some bounded operator $\mathbf H_{\rm v}:\mathcal D(\widetilde{\mathcal Q}^0)\to\mathcal D'(\widetilde{\mathcal Q}^0)$. Furthermore, we can find $s'>0,\xi>0$, and positive constants $C_1,C_2$ (that depend on $\beta$ only) such that for all $ F\in\mathcal D(\widetilde{\mathcal Q}^0)$ and $N>0$,
\begin{equation}\label{eq_assump_N_lower}
    \operatorname{Re}(\mathcal Q_{\rm v}(F,F))+N\|F\|_{L^2}^2\geq (D(v)-C_1N^{-\xi}\|v\|_{\varepsilon=0,s'}) \ \widetilde{\mathcal Q}^0(F,F)+(N-C_1N^{1-\xi}\|v\|_{\varepsilon=0,s'}-C_2\operatorname{Re}\omega)\|F\|^2_{L^2}.
\end{equation}
In particular, for $v(z)=-z$, we have $\mathcal Q_{\rm v}=\mathcal Q$.
        \item\label{itm_9} If $v\in\mathcal A {\mathrm{Hol}^\bullet_\varepsilon(\mathbb D) }$ satisfies the coercivity condition of item \eqref{itm_coercivity}, and $f_t$ denotes its flow with $f_0(z)=z$, then $e^{-t\mathbf H_{\rm v}}=\mathbf T_{f_t}$.
        \item \label{itm_10}If $f\in\mathcal {AS}_\varepsilon$ and $v\in\mathcal A {\mathrm{Hol}^\bullet_\varepsilon(\mathbb D) }$ such that $v/f'$ satisfies the coercivity condition of item \eqref{itm_coercivity}, we set $f_t(z)=f^{-1}(f(z)+tv(z))$. We assume that for $\delta>0$ small enough and for some fixed $\varepsilon'\in(0,\varepsilon)$, the map
        \begin{equation*}
            h:s,t\in[0,\delta]\mapsto \frac{v\circ f^{-1}_t(e^sz)}{f'(e^sz)}\in\mathcal A {\mathrm{Hol}^\bullet_{\varepsilon'}(\mathbb D)}
        \end{equation*}
        is continuous.
        \item If $f\in\mathcal{AS}_\varepsilon$ and $v\in\mathcal A {\mathrm{Hol}^\bullet_\varepsilon(\mathbb D) }$, then $-\omega zf'(z)+v(z)\in\mathcal A{\mathrm{Hol}^\bullet_\varepsilon(\mathbb D) }$ for all $\omega>0$ large enough.
\end{enumerate}

We still need to handle the non-autonomous flows as in \cite[Section 4.1.2]{Segal_semigroup}. Consider a non-autonomous flow
\begin{equation*}
    \partial_t f_t=w_t(f_t), \ \ \ \text{with }f_0(z)=z,\ \ \ \text{where }w_t(z)=\frac{v(f_t^{-1}(z))}{f'(z)}. 
\end{equation*}
Consider $v\in\mathcal A\mathrm{Hol}^\bullet_\varepsilon(\mathbb D)$ such that $v/f'\in\mathcal A\mathrm{Hol}^\bullet_\varepsilon(\mathbb D)$ and satisfies the coercivity condition of item \eqref{itm_coercivity}. According to \cite[Lemma 4.6]{Segal_semigroup}, with item \eqref{itm_10}, for some $\varepsilon'<\varepsilon$, we can then find $\delta>0$ and $\eta>0$ such that
\begin{equation}\label{eq_con4-7}
\begin{split}
    &\forall t\leq\delta,\forall s\in[0,\eta]\ \ \ z\mapsto w_t(e^s z)\in\mathcal A\mathrm{Hol}^\bullet_{\varepsilon'}(\mathbb D),\text{there are some uniform }D,N>0,\\
    &\text{ such that} \operatorname{Re}(\mathcal Q_{w_t(e^s z)\partial_z}(F,F))+N\|F\|_{L^2}^2\geq D\widetilde{\mathcal Q}^0(F,F),
\end{split}    
\end{equation}
and
\begin{equation}\label{eq_con4-8}
   \text{for some }\varepsilon''\in(\varepsilon',\varepsilon),\text{ the mapping }t\in[0,\delta]\mapsto f_t^{-1}\in\mathcal S_{\varepsilon''}\text{ is continuous.}
\end{equation}
Fix $n>0$ and set $t_l:=l\delta/n$ for $0\leq l\leq n$. We construct recursively the flow $f_t^n$ for $t\in[0,\delta]$ as follows: we set $f_t^n=f_t^{n,l}$ for $t\in[t_l,t_{l+1}]$ where $f^{n,l}$ is constructed inductively on $l$ as the solution of the autonomous flow
\begin{equation*}
    \forall t\in[t_l,t_{l+1}],\ \ \partial_t f_t^{n,l}=w_{t_l}(f_t^{n,l}), \ \ \text{with initial condition }f_{t_l}^{n,l}(z)=f_{t_l}^{n,l-1}(z).
\end{equation*}

In the following, we pick the $N>0$ in \eqref{eq_con4-7} (as we have \eqref{eq_assump_N_lower}) such that the estimate for $e^{-Nt}\mathbf T_{f_t^n}$ can be adapted from \cite[Lemma 4.9]{Segal_semigroup}.
\begin{lemma}
    For each $F\in\mathcal D(\widetilde{\mathcal{Q}}^0)$, the mapping $t\in[0,\delta]\mapsto e^{-Nt}\mathbf T_{f_t^n}F$ converges in $C([0,\delta],L^2)\cap L^2([0,\delta],\mathcal D(\widetilde{\mathcal Q}^0))$, as $n\to\infty$, to the mapping $t\in[0,\delta]\mapsto e^{-Nt}\mathbf T_{f_t}F$ satisfying, for ${\mathrm w}_t=w_t(z)\partial_z$,
    \begin{equation}\label{eq_increment_id}
        \forall G\in\mathcal D(\widetilde{\mathcal{Q}}^0),\ \ \ \langle e^{-Nt}\mathbf T_{f_t}F,G\rangle_{L^2}-\langle F,G\rangle_{L^2}=-\int_0^t\mathcal Q_{{\mathrm w}_r}(e^{-Nr}\mathbf T_{f_r}F,G)+N\langle e^{-Nr}\mathbf T_{f_r}F,G\rangle\ {\mathrm{d}} r.
    \end{equation}
\end{lemma}
\begin{proof}
    Similar to the discussion at the beginning of \cite[Lemma 4.9]{Segal_semigroup}, $T_{f_t^n}F$ converges to $T_{f_t}F$ in $L^2$ because of item \eqref{itm_6} and \eqref{eq_con4-8}. 

    On each interval $[t_l,t_{l+1}]$, we still have for the autonomous flow using item \eqref{itm_diff_7}, \eqref{itm_coercivity}
    \begin{equation*}
        \forall G\in\mathcal{D}(\widetilde{\mathcal Q}^0),\ \ \ \langle e^{-Nt}\mathbf T_{f_t^n}F,G\rangle_{L^2}-\langle e^{-Nt_l}\mathbf T_{f_{t_l}^n}F,G\rangle_{L^2}=-\int_{t_l}^t\mathcal Q_{{\mathrm w}_{t_l}}(e^{-Nr}\mathbf T_{f_r^n}F,G)+N\langle e^{-Nr}\mathbf T_{f_r^n}F,G\rangle_{L^2}\ {\mathrm{d}} r.
    \end{equation*}
    Furthermore, we have
    \begin{equation}\label{eq_TfnTfm}
    \begin{split}
        \langle e^{-Nt}\mathbf T_{f_t^n}F,e^{-Nt}\mathbf T_{f_t^m}F\rangle_{L^2}-\|F\|^2_{L^2}&=-\int_{0}^t\mathcal Q_{{\mathrm w}_{r}^n}(e^{-Nr}\mathbf T_{f_r^n}F,e^{-Nr}\mathbf T_{f_r^m}F)+N\langle e^{-Nr}\mathbf T_{f_r^n}F,e^{-Nr}\mathbf T_{f_r^m}F\rangle_{L^2}\ {\mathrm{d}} r\\
        &-\int_{0}^t\overline{\mathcal Q}_{{\mathrm w}_{r}^m}(e^{-Nr}\mathbf T_{f_r^n}F,e^{-Nr}\mathbf T_{f_r^m}F)+N\langle e^{-Nr}\mathbf T_{f_r^n}F,e^{-Nr}\mathbf T_{f_r^m}F\rangle_{L^2}\ {\mathrm{d}} r,
    \end{split}
    \end{equation}
    where $w_t^n(z):=w_{t_l}(z)$ for $t\in[t_l,t_{l+1}]$. Especially, we have the a priori estimate
    \begin{equation*}
        \|e^{-Nt}\mathbf T_{f_t^n}F\|_{L^2}^2+2\int_{0}^t\operatorname{Re} \mathcal Q_{{\mathrm w}_{r}^n}(e^{-Nr}\mathbf T_{f_r^n}F,e^{-Nr}\mathbf T_{f_r^n}F)+N\| e^{-Nr}\mathbf T_{f_r^n}F\|_{L^2}^2\ {\mathrm{d}} r=\|F\|^2_{L^2},
    \end{equation*}
 and applying \eqref{eq_con4-7} to the left-hand side leads to
    \begin{equation}\label{eq_apriori_estimate}
    \sup_{t\in[0,\delta]}\|e^{-Nt}\mathbf T_{f_t^n}F\|_{L^2}^2+C\int_0^\delta \widetilde{\mathcal Q}^0(e^{-Nr}\mathbf T_{f_r^n}F,e^{-Nr}\mathbf T_{f_r^n}F)\ {\mathrm{d}} r\leq 2\|F\|^2_{L^2}.
    \end{equation}
Denote by $\Delta^{n,m}_t:=e^{-Nt}\mathbf T_{f_t^n}F-e^{-Nt}\mathbf T_{f_t^m}F$. Using \eqref{eq_TfnTfm} and item \eqref{itm_diff_7}, we obtain
\begin{equation*}
    \begin{split}
        \|\Delta_{t}^{n,m}\|^2_{L^2}&+2\int_{0}^t\operatorname{Re} \mathcal Q_{{\mathrm w}_{r}^n}(\Delta_{r}^{n,m},\Delta_{r}^{n,m})+N\| \Delta_{r}^{n,m}\|_{L^2}^2\ {\mathrm{d}} r=-2\int_0^t\operatorname{Re}(\mathcal Q_{{\mathrm w}_{r}^n}-\mathcal Q_{{\mathrm w}_{r}^m})(e^{-Nr}\mathbf T_{f_r^m}F,\Delta_{r}^{n,m})\ {\mathrm{d}} r\\
        &\leq 2C' \sup_{t\in[0,\delta]}\|w_t^n-w_t^m\|_{\varepsilon',s}\int_0^t\sqrt{\widetilde{\mathcal Q}^0(e^{-Nr}\mathbf T_{f_r^m}F,e^{-Nr}\mathbf T_{f_r^m}F)\widetilde{\mathcal Q}^0(\Delta_{r}^{n,m},\Delta_{r}^{n,m})}\ {\mathrm{d}} r\\
        &\leq \frac1\lambda(C')^2 \sup_{t\in[0,\delta]}\|w_t^n-w_t^m\|^2_{\varepsilon',s}\int_0^t{\widetilde{\mathcal Q}^0(e^{-Nr}\mathbf T_{f_r^m}F,e^{-Nr}\mathbf T_{f_r^m}F)\, {\mathrm{d}} r+\lambda\int_0^t\widetilde{\mathcal Q}^0(\Delta_{r}^{n,m},\Delta_{r}^{n,m})}\, {\mathrm{d}} r,
    \end{split}
\end{equation*}
where $\lambda$ is arbitrarily small. For the left-hand side of the first line above, we use \eqref{eq_assump_N_lower}; for the last line we use equation \eqref{eq_apriori_estimate}, then we arrive at
\begin{equation*}
    \sup_{t\in[0,\delta]}\|\Delta_{t}^{n,m}\|_{L^2}^2+\int_0^\delta\widetilde{\mathcal Q}^0(\Delta_{r}^{n,m},\Delta_{r}^{n,m})\ {\mathrm{d}} r\leq C'' \sup_{t\in[0,\delta]}\|w_t^n-w_t^m\|^2_{\varepsilon',s}\|F\|^2_{L^2}.
\end{equation*}
Now the rest of the proof is the same as \cite[Lemma 4.9]{Segal_semigroup}.
\end{proof}
Recall the norm $\|\cdot\|_{\widetilde{\mathbf H}^0,s}$ defined in item \eqref{itm_diff_1} of Assumption \ref{assmp_diff}. It is not hard to see that $W^{-1}=\mathcal D'(\widetilde{\mathcal Q}^0),W^0=\mathcal H,W^1=\mathcal D(\widetilde{\mathcal Q}^0)$. Moreover, we have
\begin{equation*}
    \forall F,G\in\mathcal D(\widetilde{\mathcal Q}^0), \ \ \ |\widetilde{\mathcal Q}^0(F,G)|\leq\|F\|_{\widetilde{\mathbf H}^0,1}\|G\|_{\widetilde{\mathbf H}^0,1},
\end{equation*}
and
\begin{equation*}
    \forall F\in\mathcal D(\widetilde{\mathcal Q}^0),\forall G\in\mathcal D'(\widetilde{\mathcal Q}^0) \ \ \ |\langle F,G\rangle_{L^2}|\leq\|F\|_{\widetilde{\mathbf H}^0,1}\|G\|_{\widetilde{\mathbf H}^0,-1}.
\end{equation*}
We also have the Sobolev inequality
\begin{equation*}
    \forall F\in\mathcal D(\widetilde{\mathcal Q}^0),\ \ \ \|F\|_{\widetilde{\mathbf H}^0,-1}\leq C\|F\|_{\widetilde{\mathbf H}^0,0}\leq C\|F\|_{\widetilde{\mathbf H}^0,1},
\end{equation*}
where $C$ is some constant independent of $F$. Recall $\eta>0$ appeared in \eqref{eq_con4-7}. Below we provide a weaker version of \cite[Lemma 4.10]{Segal_semigroup} since we only have $e^{-t\mathbf H}:W^{-1}\to W^1$.
\begin{lemma}\label{lemma_Tf_prop}
    For $f\in\mathcal A \mathcal S_\varepsilon$, there is some operator $\mathbf T^{\eta}_f$ such that $\mathbf T_f=\mathbf T_f^{\eta} e^{-\eta\mathbf H}$ with operator norm
    \begin{equation*}
        \|\mathbf T_f\|_{W^{-1}\to W^{1}}<+\infty\ \ \ \ \text{and}\ \ \ \ \|\mathbf T_f^\eta\|_{W^{-1}\to W^{1}}<+\infty.
    \end{equation*}
    The same property and operator norm estimates hold for the adjoints $\mathbf T^*_f$ and $(\mathbf T^\eta_f)^*$.
\end{lemma}
The proof for the above lemma is exactly the same as in \cite[Lemma 4.10]{Segal_semigroup}. Recall the $\delta$ in \eqref{eq_con4-7}. Now we claim
\begin{lemma}\label{lemma_TF-Id_is_sqt}
    There exists a constant $C>0$ such that for $t\in(0,\delta)$,
    \begin{equation*}
        \|e^{-Nt}\mathbf T_{f_t}-{\mathrm{Id}}\|_{\mathcal D(\widetilde{\mathcal{Q}}^0)\to \mathcal H}\leq C \sqrt{t}.
    \end{equation*}
\end{lemma}
\begin{proof}
    Let us follow the proof of \cite[Lemma 4.11]{Segal_semigroup}. From \eqref{eq_increment_id}, we have
    \begin{equation*}
        \|e^{-Nt}\mathbf T_{f_t} F-F\|_{L^2}^2=-2\int_{0}^t\operatorname{Re} \left(\mathcal Q_{{\mathrm w}_r}(e^{-Nr}\mathbf T_{f_r} F,e^{-Nr}\mathbf T_{f_r} F-F)+N\langle e^{-Nr}\mathbf T_{f_r} F,e^{-Nr}\mathbf T_{f_r} F-F\rangle_{L^2}\right)\ {\mathrm{d}} r.
    \end{equation*}
    Using \eqref{eq_con4-7}, we get
    \begin{equation*}
    \begin{split}
        &\|e^{-Nt}\mathbf T_{f_t} F-F\|_{L^2}^2+C\int_{0}^t\widetilde{\mathcal Q}^0(e^{-Nr}\mathbf T_{f_r} F-F,e^{-Nr}\mathbf T_{f_r} F-F)\ {\mathrm{d}} r\\
        \leq{}&-2\int_{0}^t\operatorname{Re} \left(\mathcal Q_{{\mathrm w}_r}(F,e^{-Nr}\mathbf T_{f_r} F-F)+N\langle F,e^{-Nr}\mathbf T_{f_r} F-F\rangle_{L^2}\right)\ {\mathrm{d}} r.
    \end{split}
    \end{equation*}
   Based on item \eqref{itm_diff_7} and item \eqref{itm_10}, the right-hand side above can be further bounded by
    \begin{equation*}
        \frac t\lambda C\|F\|_{\widetilde{\mathbf H}^0,1}^2+\lambda(C+N)\int_0^t\|e^{-Nr}\mathbf T_{f_r} F-F\|_{\widetilde{\mathbf H}^0,1}^2\ {\mathrm{d}} r+\frac t\lambda N\|F\|_{\widetilde{\mathbf H}^0,-1}^2.
    \end{equation*}
    Make $\lambda$ sufficiently small and using Sobolev inequality, we complete the proof.
\end{proof}
We follow the rest of the proof in \cite[Section 4.1.3]{Segal_semigroup}. Since $t^{-1}\langle e^{-Nt}F-F,G\rangle$ clearly exists, it is enough to study $\langle\mathbf e^{-Nt}T_{f_t}F,G\rangle_{L^2}-\langle F,G\rangle_{L^2}$.  First using \eqref{eq_increment_id}, we have
\begin{equation*}
\begin{split}
    \langle\mathbf e^{-Nt}T_{f_t}F,G\rangle_{L^2}-\langle F,G\rangle_{L^2}&=-\int_0^t\mathcal Q_{{\mathrm w}_r}(e^{-Nr}\mathbf T_{f_r}F,G)+N\langle e^{-Nr}\mathbf T_{f_r}F,G\rangle\ {\mathrm{d}} r\\
    ={}&-t\mathcal Q_{{\mathrm w}_0}(F,G)-Nt\langle F,G\rangle_{L^2}-\int_0^t(\mathcal Q_{{\mathrm w}_r}(F,G)-\mathcal Q_{{\mathrm w}_0}(F,G))\ {\mathrm{d}} r\\
    &-\int_0^t\mathcal Q_{{\mathrm w}_r}(e^{-Nr}\mathbf T_{f_r}F-F,G)+N\langle e^{-Nr}\mathbf T_{f_r}F-F,G\rangle_{L^2}\ {\mathrm{d}} r\\
    =&:-t\mathcal Q_{{\mathrm w}_0}(F,G)-Nt\langle F,G\rangle_{L^2}-R^1_t(G)-R^2_t(G).
\end{split}
\end{equation*}
Especially, we put $\mathbf T_f^* G$ with $ G\in\mathcal D'(\widetilde{\mathcal Q}_0)$ in the above equation, and 
\begin{equation*}
     \langle e^{-Nt}\mathbf T_{f}\mathbf T_{f_t}F,G\rangle_{L^2}-\langle \mathbf T_{f}F,G\rangle_{L^2}=-t\mathcal Q_{{\mathrm w}_0}(F,\mathbf T_f^*G)-Nt\langle F,\mathbf T_f^*G\rangle_{L^2}-R^1_t(\mathbf T_f^*G)-R^2_t(\mathbf T_f^*G).
\end{equation*}
Using item \eqref{itm_diff_7} for $\mathcal Q_{{\mathrm w}_0}$ and \cref{lemma_Tf_prop}, we have
\begin{equation*}
    |\mathcal Q_{{\mathrm w}_0}(F,\mathbf T_f^*G)|\leq C\|F\|_{\widetilde{\mathbf H}^0,1}\|\mathbf T_f^*G\|_{\widetilde{\mathbf H}^0,1}\leq C\|F\|_{\widetilde{\mathbf H}^0,1}\|G\|_{\widetilde{\mathbf H}^0,-1}.
\end{equation*}
By the Riesz representation theorem, we can find an element $D_{{\rm v}}\mathbf T_f F\in\mathcal D(\widetilde{\mathcal{Q}}^0)$ such that $\langle D_{{\rm v}}\mathbf T_f F,G\rangle_{L^2}=-\mathcal Q_{{\mathrm w}_0}(F,\mathbf T_f^*G)$ for all $G\in\mathcal D'(\widetilde{\mathcal Q}^0)$. Now we just prove $R^1_t,R^2_t$ are $o(t)$ in operator norm $\mathcal D(\widetilde{\mathcal{Q}}^0)\to \mathcal D(\widetilde{\mathcal{Q}}^0)$.

For $R_t^2$, using \cite[Lemma 4.12]{Segal_semigroup} (the proof is the same except that $\mathcal Q_{\rm v}(F,e^{-t\mathbf H^*}G)=\mathcal Q_{{\rm v}_t}(e^{-t\mathbf H}F,G)$ where $v_t(z):=e^{-t}v(e^tz)$) and \cref{lemma_Tf_prop}, we have
\begin{equation*}
    |R_t^2(\mathbf T_f^*G)|=\left|\int_0^t\mathcal Q_{{\mathrm w}_r}(e^{-Nr}\mathbf T_{f_r}F-F,e^{-\eta\mathbf H^*}(\mathbf T_f^\eta)^*G)+N\langle e^{-Nr}\mathbf T_{f_r}F-F,\mathbf T_f^*G\rangle_{L^2} {\mathrm{d}} r\right|,
\end{equation*}
which leads to the same estimate in \cite{Segal_semigroup} using \cite[Lemma 4.12]{Segal_semigroup} ($\mathcal Q_{\rm v}(F,e^{-t\mathbf H^*}G)=\mathcal Q_{{\rm v}_t}(e^{-t\mathbf H}F,G)$), item \eqref{itm_diff_7}, and \cref{lemma_TF-Id_is_sqt}
\begin{equation*}
    |R_t^2(\mathbf T_f^*G)|\leq C\int_0^t\|e^{-Nr}\mathbf T_{f_r}F-F\|_{L^2}\|G\|_{\widetilde{\mathbf H}^0,-1}\ {\mathrm{d}} r\leq C t^{3/2}\|F\|_{\widetilde{\mathbf H}^0,1}\|G\|_{\widetilde{\mathbf H}^0,-1}.
\end{equation*}
The proof of $R_t^1$ is the same except that in \cite[Lemma 4.14]{Segal_semigroup}, we bound the difference of quadratic form using $\widetilde{\mathcal Q}^0$.

 The rest of the proof is the same as those in \cite[Section 4.1]{Segal_semigroup}.

For each $F\in\mathcal D(\widetilde{\mathcal{Q}}^0)$, the mapping $t\in[0,\delta]\mapsto e^{-Nt}\mathbf T_{f_t^n}F$ converges in $C([0,\delta],L^2)\cap L^2([0,\delta],\mathcal D(\widetilde{\mathcal Q}^0))$, as $n\to\infty$, to the mapping $t\in[0,\delta]\mapsto e^{-Nt}\mathbf T_{f_t}F$ satisfying, for ${\mathrm w}_t=w_t(z)\partial_z$,
    \begin{equation}\label{eq_increment_id}
        \forall G\in\mathcal D(\widetilde{\mathcal{Q}}^0),\ \ \ \langle e^{-Nt}\mathbf T_{f_t}F,G\rangle_{L^2}-\langle F,G\rangle_{L^2}=-\int_0^t\mathcal Q_{{\mathrm w}_r}(e^{-Nr}\mathbf T_{f_r}F,G)+N\langle e^{-Nr}\mathbf T_{f_r}F,G\rangle\ {\mathrm{d}} r.
    \end{equation}

Similar to the discussion at the beginning of \cite[Lemma 4.9]{Segal_semigroup}, $T_{f_t^n}F$ converges to $T_{f_t}F$ in $L^2$ because of item \eqref{itm_6} and \eqref{eq_con4-8}. 

    On each interval $[t_l,t_{l+1}]$, we still have for the autonomous flow using item \eqref{itm_diff_7}, \eqref{itm_coercivity}
    \begin{equation*}
        \forall G\in\mathcal{D}(\widetilde{\mathcal Q}^0),\ \ \ \langle e^{-Nt}\mathbf T_{f_t^n}F,G\rangle_{L^2}-\langle e^{-Nt_l}\mathbf T_{f_{t_l}^n}F,G\rangle_{L^2}=-\int_{t_l}^t\mathcal Q_{{\mathrm w}_{t_l}}(e^{-Nr}\mathbf T_{f_r^n}F,G)+N\langle e^{-Nr}\mathbf T_{f_r^n}F,G\rangle_{L^2}\ {\mathrm{d}} r.
    \end{equation*}
    Furthermore, we have
    \begin{equation}\label{eq_TfnTfm}
    \begin{split}
        \langle e^{-Nt}\mathbf T_{f_t^n}F,e^{-Nt}\mathbf T_{f_t^m}F\rangle_{L^2}-\|F\|^2_{L^2}&=-\int_{0}^t\mathcal Q_{{\mathrm w}_{r}^n}(e^{-Nr}\mathbf T_{f_r^n}F,e^{-Nr}\mathbf T_{f_r^m}F)+N\langle e^{-Nr}\mathbf T_{f_r^n}F,e^{-Nr}\mathbf T_{f_r^m}F\rangle_{L^2}\ {\mathrm{d}} r\\
        &-\int_{0}^t\overline{\mathcal Q}_{{\mathrm w}_{r}^m}(e^{-Nr}\mathbf T_{f_r^n}F,e^{-Nr}\mathbf T_{f_r^m}F)+N\langle e^{-Nr}\mathbf T_{f_r^n}F,e^{-Nr}\mathbf T_{f_r^m}F\rangle_{L^2}\ {\mathrm{d}} r,
    \end{split}
    \end{equation}
    where $w_t^n(z):=w_{t_l}(z)$ for $t\in[t_l,t_{l+1}]$. Especially, we have the a priori estimate
    \begin{equation*}
        \|e^{-Nt}\mathbf T_{f_t^n}F\|_{L^2}^2+2\int_{0}^t\operatorname{Re} \mathcal Q_{{\mathrm w}_{r}^n}(e^{-Nr}\mathbf T_{f_r^n}F,e^{-Nr}\mathbf T_{f_r^n}F)+N\| e^{-Nr}\mathbf T_{f_r^n}F\|_{L^2}^2\ {\mathrm{d}} r=\|F\|^2_{L^2},
    \end{equation*}
 and applying \eqref{eq_con4-7} to the left-hand side leads to
    \begin{equation}\label{eq_apriori_estimate}
    \sup_{t\in[0,\delta]}\|e^{-Nt}\mathbf T_{f_t^n}F\|_{L^2}^2+C\int_0^\delta \widetilde{\mathcal Q}^0(e^{-Nr}\mathbf T_{f_r^n}F,e^{-Nr}\mathbf T_{f_r^n}F)\ {\mathrm{d}} r\leq 2\|F\|^2_{L^2}.
    \end{equation}
Denote by $\Delta^{n,m}_t:=e^{-Nt}\mathbf T_{f_t^n}F-e^{-Nt}\mathbf T_{f_t^m}F$. Using \eqref{eq_TfnTfm} and item \eqref{itm_diff_7}, we obtain
\begin{equation*}
    \begin{split}
        \|\Delta_{t}^{n,m}\|^2_{L^2}&+2\int_{0}^t\operatorname{Re} \mathcal Q_{{\mathrm w}_{r}^n}(\Delta_{r}^{n,m},\Delta_{r}^{n,m})+N\| \Delta_{r}^{n,m}\|_{L^2}^2\ {\mathrm{d}} r=-2\int_0^t\operatorname{Re}(\mathcal Q_{{\mathrm w}_{r}^n}-\mathcal Q_{{\mathrm w}_{r}^m})(e^{-Nr}\mathbf T_{f_r^m}F,\Delta_{r}^{n,m})\ {\mathrm{d}} r\\
        &\leq 2C' \sup_{t\in[0,\delta]}\|w_t^n-w_t^m\|_{\varepsilon',s}\int_0^t\sqrt{\widetilde{\mathcal Q}^0(e^{-Nr}\mathbf T_{f_r^m}F,e^{-Nr}\mathbf T_{f_r^m}F)\widetilde{\mathcal Q}^0(\Delta_{r}^{n,m},\Delta_{r}^{n,m})}\ {\mathrm{d}} r\\
        &\leq \frac1\lambda(C')^2 \sup_{t\in[0,\delta]}\|w_t^n-w_t^m\|^2_{\varepsilon',s}\int_0^t{\widetilde{\mathcal Q}^0(e^{-Nr}\mathbf T_{f_r^m}F,e^{-Nr}\mathbf T_{f_r^m}F)\, {\mathrm{d}} r+\lambda\int_0^t\widetilde{\mathcal Q}^0(\Delta_{r}^{n,m},\Delta_{r}^{n,m})}\, {\mathrm{d}} r,
    \end{split}
\end{equation*}
where $\lambda$ is arbitrarily small. For the left-hand side of the first line above, we use \eqref{eq_assump_N_lower}; for the last line we use equation \eqref{eq_apriori_estimate}, then we arrive at
\begin{equation*}
    \sup_{t\in[0,\delta]}\|\Delta_{t}^{n,m}\|_{L^2}^2+\int_0^\delta\widetilde{\mathcal Q}^0(\Delta_{r}^{n,m},\Delta_{r}^{n,m})\ {\mathrm{d}} r\leq C'' \sup_{t\in[0,\delta]}\|w_t^n-w_t^m\|^2_{\varepsilon',s}\|F\|^2_{L^2}.
\end{equation*}
Now the rest of the proof is the same as \cite[Lemma 4.9]{Segal_semigroup}.

\label{lemma_Tf_prop}
    For $f\in\mathcal A \mathcal S_\varepsilon$, there is some operator $\mathbf T^{\eta}_f$ such that $\mathbf T_f=\mathbf T_f^{\eta} e^{-\eta\mathbf H}$ with operator norm
    \begin{equation*}
        \|\mathbf T_f\|_{W^{-1}\to W^{1}}<+\infty\ \ \ \ \text{and}\ \ \ \ \|\mathbf T_f^\eta\|_{W^{-1}\to W^{1}}<+\infty.
    \end{equation*}
    The same property and operator norm estimates hold for the adjoints $\mathbf T^*_f$ and $(\mathbf T^\eta_f)^*$.

\label{lemma_TF-Id_is_sqt}
    There exists a constant $C>0$ such that for $t\in(0,\delta)$,
    \begin{equation*}
        \|e^{-Nt}\mathbf T_{f_t}-{\mathrm{Id}}\|_{\mathcal D(\widetilde{\mathcal{Q}}^0)\to \mathcal H}\leq C \sqrt{t}.
    \end{equation*}

Let us follow the proof of \cite[Lemma 4.11]{Segal_semigroup}. From \eqref{eq_increment_id}, we have
    \begin{equation*}
        \|e^{-Nt}\mathbf T_{f_t} F-F\|_{L^2}^2=-2\int_{0}^t\operatorname{Re} \left(\mathcal Q_{{\mathrm w}_r}(e^{-Nr}\mathbf T_{f_r} F,e^{-Nr}\mathbf T_{f_r} F-F)+N\langle e^{-Nr}\mathbf T_{f_r} F,e^{-Nr}\mathbf T_{f_r} F-F\rangle_{L^2}\right)\ {\mathrm{d}} r.
    \end{equation*}
    Using \eqref{eq_con4-7}, we get
    \begin{equation*}
    \begin{split}
        &\|e^{-Nt}\mathbf T_{f_t} F-F\|_{L^2}^2+C\int_{0}^t\widetilde{\mathcal Q}^0(e^{-Nr}\mathbf T_{f_r} F-F,e^{-Nr}\mathbf T_{f_r} F-F)\ {\mathrm{d}} r\\
        \leq{}&-2\int_{0}^t\operatorname{Re} \left(\mathcal Q_{{\mathrm w}_r}(F,e^{-Nr}\mathbf T_{f_r} F-F)+N\langle F,e^{-Nr}\mathbf T_{f_r} F-F\rangle_{L^2}\right)\ {\mathrm{d}} r.
    \end{split}
    \end{equation*}
   Based on item \eqref{itm_diff_7} and item \eqref{itm_10}, the right-hand side above can be further bounded by
    \begin{equation*}
        \frac t\lambda C\|F\|_{\widetilde{\mathbf H}^0,1}^2+\lambda(C+N)\int_0^t\|e^{-Nr}\mathbf T_{f_r} F-F\|_{\widetilde{\mathbf H}^0,1}^2\ {\mathrm{d}} r+\frac t\lambda N\|F\|_{\widetilde{\mathbf H}^0,-1}^2.
    \end{equation*}
    Make $\lambda$ sufficiently small and using Sobolev inequality, we complete the proof.

\label{annulus_differential}
Let $t\mapsto f_t\in{\mathcal{S}}({\mathbb{A}})$ be a differentiable family with $f_0:z\mapsto rz$ ($0<r<1$) and $\partial_t|_{t=0}f_t={\rm v}=-\sum_{n\in{\mathbb{Z}}}v_nz^{n+1}\partial_z$ a holomorphic vector field on ${\mathbb{T}}$. Let $g_{f_t}$ be an admissible metric on ${\mathbb{A}}_{f_t}$ depending in a $C^1$ fashion on $t$ with $g_{f_0}=g_{\mathbb{A}}=|dz|^2/|z|^2$. Then the map $t\mapsto{\mathcal{A}}_{{\mathbb{A}}_{f_t},g_{f_t},{\boldsymbol{\zeta}}_{f_t}}\in{\mathcal{L}}(L^2({\mathcal{D}}'({\mathbb{T}},{\mathbb{T}}_R)))$ is differentiable at $t=0$ with differential (in the same sense as in \cref{T_f_differentiable})
\[\partial_t\big|_{t=0}{\mathcal{A}}_{{\mathbb{A}}_{f_t},g_{f_t},{\boldsymbol{\zeta}}_{f_t}} = -c_{\mathrm{L}}\left(-\frac{\operatorname{Re} v_0}{12r} + \partial_t\big|_{t=0} S_{\mathrm{L}}^0({\mathbb{A}}_{f_t},g_{f_t},g_{\mathbb{A}})\right){\mathcal{A}}_{{\mathbb{A}}_{f_0},g_{\mathbb{A}},{\boldsymbol{\zeta}}_{f_0}}-{\mathcal{A}}_{{\mathbb{A}}_{f_0},g_{\mathbb{A}},{\boldsymbol{\zeta}}_{f_0}}\circ{\mathbf{H}}_{{\rm v}/r}.\]

\label{ward_cilt}
Let $\Sigma$ be a compact Riemann surface with real-analytic boundary parametrizations ${\boldsymbol{\zeta}}=(\zeta_1,\ldots,\zeta_{\mathfrak{b}})$. Suppose ${\mathfrak{b}}={\mathfrak{b}}^++{\mathfrak{b}}^-$ where $\zeta_j$ is outgoing for $j=1,\ldots,{\mathfrak{b}}^+$ and incoming for $j={\mathfrak{b}}^++1,\ldots,{\mathfrak{b}}$. Let ${\mathbf{z}}=(z_1,\ldots,z_{\mathfrak{s}})$ be distinct marked points on $\Sigma^\circ$, ${\mathbf{v}}=(v_1,\ldots,v_{\mathfrak{s}})$ with $v_j\in T_{z_j}\Sigma\setminus\{0\}$ for each $j$, ${\boldsymbol{\alpha}}=(\alpha_1,\ldots,\alpha_{\mathfrak{s}})\in{\mathbb{R}}^{\mathfrak{s}}$ electric charges such that $\alpha_j>Q$, $\alpha_jR\in{\mathbb{Z}}$ for all $j$, and ${\mathbf{m}}=(m_1,\ldots,m_{\mathfrak{s}})\in{\mathbb{Z}}^{\mathfrak{s}}$ magnetic charges. Let $g$ be an admissible metric on $\Sigma$. We have the amplitude operator ${\mathcal{A}}_{\Sigma,g,{\mathbf{v}},{\boldsymbol{\alpha}},{\mathbf{m}},{\boldsymbol{\zeta}}}:{\mathcal{H}}^{\otimes{\mathfrak{b}}^-}\to{\mathcal{H}}^{\otimes{\mathfrak{b}}^+}$ with ${\mathcal{H}}=L^2({\mathcal{D}}'({\mathbb{T}},{\mathbb{T}}_R))$. Finally, let ${\rm w}$ be a holomorphic vector field on $\Sigma$ (analytic up to the boundary). For each $j=1,\ldots,{\mathfrak{b}}$, let ${\rm w}_j:=\zeta_j^*{\rm w}=-\sum_{n\in{\mathbb{Z}}}w_{jn}z^{n+1}\partial_z$, where we extend $\zeta_j$ analytically so that ${\rm w}_j$ is holomorphic on an open neighborhood of ${\mathbb{T}}$. Then the following identity holds:
\begin{align*}
0 &= \sum_{j=1}^{{\mathfrak{b}}^+}{\mathbf{H}}_{{\rm w}_j}^{(j)}{\mathcal{A}}_{\Sigma,g,{\mathbf{v}},{\boldsymbol{\alpha}},{\mathbf{m}},{\boldsymbol{\zeta}}} - \sum_{j=1}^{{\mathfrak{b}}^-}{\mathcal{A}}_{\Sigma,g,{\mathbf{v}},{\boldsymbol{\alpha}},{\mathbf{m}},{\boldsymbol{\zeta}}}{\mathbf{H}}_{{\rm w}_{{\mathfrak{b}}^++j}}^{(j)}
+ \sum_{j=1}^{{\mathfrak{s}}}\left(\Delta_{\alpha_j,m_j}(\operatorname{div}_gW)(z_j)+W_{\mathbf{v}}^{(j)}\right){\mathcal{A}}_{\Sigma,g,{\mathbf{v}},{\boldsymbol{\alpha}},{\mathbf{m}},{\boldsymbol{\zeta}}} \\
&\qquad+ c_{\mathrm{L}}\left(-\sum_{j=1}^{{\mathfrak{b}}^+}\frac{\operatorname{Re} w_{j0}}{12}+\sum_{j={\mathfrak{b}}^++1}^{{\mathfrak{b}}}\frac{\operatorname{Re} w_{j0}}{12}-\frac{1}{96\pi}\int_\Sigma 2K_g\operatorname{div}_gW\,{\mathrm{d}} v_g\right){\mathcal{A}}_{\Sigma,g,{\mathbf{v}},{\boldsymbol{\alpha}},{\mathbf{m}},{\boldsymbol{\zeta}}},
\end{align*}
where ${\mathbf{H}}_{{\rm w}}^{(j)}:={\mathrm{id}}_{\mathcal{H}} \otimes \cdots \otimes \underset{j}{\underbrace{{\mathbf{H}}_{\rm w}}} \otimes \cdots \otimes {\mathrm{id}}_{\mathcal{H}}$ acts on the $j$-th ${\mathcal{H}}$, $W={\rm w}+\bar{{\rm w}}$, and $W_{\mathbf{v}}^{(j)}$ denotes differentiation with respect to $v_j$ in the direction of $W$ at $z_j$.

\label{Q_v^+_bound}
Let $N\geq0$. For $F,G\in{\mathcal{E}}({\mathcal{D}}'({\mathbb{T}}^+,{\mathbb{T}}_R))$, we have
\begin{equation}\label{eq_V_bound_bdy}
|\langle V_{\rm v}^{\boldsymbol{\mu}}  F,G\rangle_{L^2}|\leq C\, (N+Q^2/4)^{\frac{\beta^2}{2}-1} \sup_{\theta\in[0,2\pi]}|\operatorname{Re}(e^{-{\mathrm{i}}\theta}v(e^{{\mathrm{i}}\theta}))|\,\sqrt{(N\|F\|_{L^2}^2+\widetilde{\mathcal Q}^{+,0}(F,F))(N\|G\|_{L^2}^2+\widetilde{\mathcal Q}^{+,0}(G,G))},
\end{equation}
where $C>0$ only depends on $\beta$ and ${\boldsymbol{\mu}}$. In particular, $V_{\rm v}^{\boldsymbol{\mu}}$ extends to a bounded operator ${\mathcal{D}}(\widetilde{{\mathcal{Q}}}^{+,0})\to{\mathcal{D}}'(\widetilde{{\mathcal{Q}}}^{+,0})$.

(1): The proof is the same Girsanov transform calculation as in \cref{prop_semigroup_as_amplitude}, upon applying the gluing axiom for the free field to ${\mathbb{A}}_f^+\#f({\mathbb{D}}^+)={\mathbb{D}}^+$. The only nontrivial part is the determinant term $\frac{\det'\Delta_{g|_{f({\mathbb{D}}^+)}}}{\det'\Delta_{g|_{{\mathbb{D}}^+}}}$ where $g$ is a Neumann extendible metric on ${\mathbb{D}}^+$ extending $g_f$. Now by the Polyakov formula \cite[Proposition 5.10]{Boundary_Segal} (for Neumann extendible metrics on surfaces with both Neumann and Dirichlet boundaries), we have
\[\frac{\det'\Delta_{g|_{f({\mathbb{D}}^+)}}}{\det'\Delta_{g|_{{\mathbb{D}}^+}}}=e^{-2S_{\mathrm{L}}^0({\mathbb{D}}^+,g,f^*g)}=e^{-S_{\mathrm{L}}^0({\mathbb{D}},g,f^*g)}=\left(\frac{\det'\Delta_{g|_{f({\mathbb{D}})}}}{\det'\Delta_{g|_{{\mathbb{D}}}}}\right)^{1/2},\]
where we view $g$ as an even metric on ${\mathbb{D}}$. Thus we can apply \eqref{det_formula} to get that this is precisely $e^{\frac{1}{6}W^+(f,g_f)}$, as desired.

(2): That ${\mathbf{T}}_f^+$ is bounded on $L^2({\mathcal{D}}'({\mathbb{T}}^+,{\mathbb{T}}_R))$ follows from (1) and the boundedness of the BCILT amplitude (\cite[Theorem 7.5]{BCILT}). The rest follows from \eqref{W_additivity} as in the proof of \cref{T_f_semigroup}.

(3): We emphasize that, in the proof of Proposition \ref{prop_FK_formula}, we only used the existence of the GMC exponential moment, the convergence of $\mathbb E[\exp(|\mu \int_{\mathbb A_t}|x|^{\beta Q} |x-y|^{\beta^2}M_\beta(P\widetilde{\varphi}^k+X_{{\mathbb{D}}},{\mathrm{d}} x)|)]$ to $1$ (uniformly over $y$ in a thin annulus), and the convergence of exponential moment of GMC cut-off (\cref{lemma_gmc_delta_exp_bound}). Similar to \cite[Proposition 7.6]{boundary_bootstrap}, we have
\begin{equation*}
     \int_{{\mathbb{A}}_{f_t}^+}|x|^{\beta Q} M_\beta(X^+,{\mathrm{d}} x)=-\int_{0}^t\int_0^{\pi} e^{{\mathrm{i}}\beta ((X^+\circ f_s)(e^{{\mathrm{i}}\theta})+{\mathrm{i}} Q\log\frac{|f'_s(e^{{\mathrm{i}}\theta})|}{|f_s(e^{{\mathrm{i}}\theta})|})}\operatorname{Re}\left(e^{-{\mathrm{i}}\theta}v(e^{{\mathrm{i}}\theta})\right)\, {\mathrm{d}}\theta{\mathrm{d}} s,
\end{equation*}
where $X^+:=P\widetilde{\varphi}^{\mathrm{h}}+X_{{\mathbb{D}}^+}$. Also we have
\begin{equation*}
    \begin{split}
        &\int_{[f_t(1),1]}|x|^{\frac{\beta Q}{2}}L_\beta(X^+,{\mathrm{d}} x)=-v(1)\int_0^te^{{\mathrm{i}}\frac\beta2 ((X^+\circ f_s)(1)+{\mathrm{i}} Q\log\frac{|f'_s(1)|}{|f_s(1)|})}{\mathrm{d}} s,\\
        &\int_{[-1,f_t(-1)]}|x|^{\frac{\beta Q}{2}}L_\beta(X^+,{\mathrm{d}} x)=v(-1)\int_0^te^{{\mathrm{i}}\frac\beta2 ((X^+\circ f_s)(-1)+{\mathrm{i}} Q\log\frac{|f'_s(-1)|}{|f_s(-1)|})}{\mathrm{d}} s
    \end{split}
\end{equation*}
The control of the boundary GMC exponential moment can be found in \cite[Proposition 6.2]{BCILT}. Specifically, given a general function $f(x)$, for some constant $C$ depending on $\beta$,  we have
\begin{equation*}
    \begin{split}
        &\mathbb E\left[\exp\left(\left|\int_{{\mathbb{A}}_{f_t}^+} f(x)M_\beta(X^+,{\mathrm{d}} x)\right|+\left|\int_{{\mathbb{A}}_{f_t}^+\cap\mathbb R} f(x)L_\beta(X^+,{\mathrm{d}} x)\right|\right)\right]\\
        \leq{}& e^{C V(f)}\sqrt{\left(1+C\sqrt{U_1(\Sigma,f)}e^{CU_1(\Sigma,f)}\right)\left(1+C\sqrt{U_2({\widetilde{\partial}_{\mathrm{N}}}\Sigma,f)}e^{CU_2({\widetilde{\partial}_{\mathrm{N}}}\Sigma,f)}\right)},
    \end{split}
    \end{equation*}
     where
    \begin{equation}\label{eq_BGMC_bound}
    \begin{split}
        &U_1(\Sigma,f):=\iint_{({\mathbb{A}}_{f_t}^+)^2}|f(x)f(y)|(|x-y|^{-\beta^2}+|x-\bar y|^{-\beta^2}){\mathrm{d}} x{\mathrm{d}} y,\\
        &U_2({\widetilde{\partial}_{\mathrm{N}}}\Sigma,f):=\iint_{({\mathbb{A}}_{f_t}^+\cap\mathbb R)^2}|f(x)f(y)||x-y|^{-\beta^2/2}{\mathrm{d}} x{\mathrm{d}} y,\\
        &V(f):=\int_{{\mathbb{A}}_{f_t}^+}|f(x)|\sup_{y\in\partial{\mathbb{A}}_{f_t}^+}|x-y|^{-\beta^2/2}{\mathrm{d}} x+\int_{{\mathbb{A}}_{f_t}^+\cap\mathbb R}|f(x)|\sup_{y\in\partial({\mathbb{A}}_{f_t}^+\cap\mathbb R)}|x-y|^{-\beta^2/4}\,{\mathrm{d}} x.
    \end{split}
    \end{equation}  
And we can prove the boundary version of \cref{lemma_gmc_delta_exp_bound} by using again the martingale argument.

(4): The continuity follows the discussion in \cite[Proposition 3.11]{Segal_semigroup}, \cite[Lemma 7.10]{boundary_bootstrap} and \cref{prop_Tf_continuity}. Here we point out the main difference in the proof of a BCILT version compared to those. First, there is no magnetic operator on the boundary, so the amplitude becomes simpler. Next is the estimate of GMC exponential moment when the area is small. Similar to \eqref{eq_BGMC_bound}, for some $C,\xi>0$, we bound the small area GMC exponential moment with
\begin{equation*}
\begin{split}
    &\iint_{(\mathbb A_{1,1+C\xi})^2}|x-y|^{-\beta^2}{\mathrm{d}} x{\mathrm{d}} y,\ \  \iint_{[1,1+C\xi]^2}|x-y|^{-\frac{\beta^2}{2}}{\mathrm{d}} x{\mathrm{d}} y,\\
    &\int_{\mathbb A_{1,1+C\xi}^+}(||x|-1|\wedge\operatorname{Im} x)^{-\frac{\beta^2}2}{\mathrm{d}} x,\ \ \int_1^{1+C\xi}|x-1|^{-\frac{\beta^2}{4}}{\mathrm{d}} x,
\end{split}
\end{equation*}
where $\mathbb A_{1,1+C\xi}:=\{z:1\leq|z|\leq 1+C\xi\}$ and $\mathbb A_{1,1+C\xi}^+:=\mathbb A_{1,1+C\xi}\cap \mathbb H$. The integrals above can be controlled by $\xi^{a}$ for some $a>0$.

Next let us consider a sequence of surfaces $(\Sigma_n^+,g)_{n\geq1}$ and a surface $\Sigma^{+,\xi}\subset\cap_{n\geq N}\Sigma_n^+$ for large $N$. Denote by ${\widetilde{\partial}_{\mathrm{D}}}\Sigma_n^+$ the Dirichlet boundaries of $\Sigma_n^+$ and ${\widetilde{\partial}_{\mathrm{N}}}\Sigma_n^+$ the Neumann boundaries of $\Sigma_n^+$. Then we can construct GFF $X_n^+$ on $\Sigma_n^+$ with corresponding boundary conditions. We now show how to provide a bound for $\mathbb E_{\widetilde{\boldsymbol{\varphi}}^h}[e^{-\mu\int_{\Sigma^{+,\xi}}f(x)M_\beta(X_n^{+}+Z,{\mathrm{d}} v_g(x))}]$ uniformly in $n$ and in $Z$ ($Z$ must be real and independent of $X_n^+$) or $\widetilde{\boldsymbol{\varphi}}^h$ the value on the Dirichlet boundary ${\widetilde{\partial}_{\mathrm{D}}}\Sigma_n^+$.

Denote by $\Sigma_n$ and $\Sigma^\xi$ the Neumann double of $\Sigma^+_n$ and $\Sigma^{+,\xi}$ under reflection $\tau$. We have respectively the Dirichlet Green's function $(2\pi)^{-1}G_n$ and $(2\pi)^{-1}G^\xi$ and mixed Green's function $(2\pi)^{-1}G_n^+(x,y)=(2\pi)^{-1}(G_n(x,y)+G_n(x,\tau(y)))$ and $(2\pi)^{-1}G^{+,\xi}(x,y)=(2\pi)^{-1}(G^\xi(x,y)+G^\xi(x,\tau(y)))$. Since we have $G_n\geq G^\xi$, we also have $G_n^+\geq G^{+,\xi}$. Again by Taylor's expansion we have
\begin{equation*}
    \left|\mathbb E_{\widetilde{\boldsymbol{\varphi}}^h}[e^{-\mu\int_{\Sigma^{+,\xi}}f(x)M_\beta(X_n^{+}+Z,{\mathrm{d}} v_g(x))}]\right|\leq\mathbb E[e^{|\mu|\int_{\Sigma^{+,\xi}}|f(x)|M_\beta(X^{+,\xi},{\mathrm{d}} v_g(x))}],
\end{equation*}
where $X^{+,\xi}$ is the GFF on $\Sigma^{+,\xi}$ with covariance $G^{+,\xi}$. Then we just follow the proof of \cite[Lemma 7.10]{boundary_bootstrap} and \cref{prop_Tf_continuity}.

By verifying \cref{assmp_diff}, we can get differentiability from \cref{prop_general_T_f_diff} just as the proof of  \cite[Proposition 7.9]{boundary_bootstrap} in \cite[Section 7.5.1]{boundary_bootstrap} does.

\label{ward_bcilt}
Let $\Sigma$ be an extended surface (see \cite[Definition 1.1]{BCILT} for the notations) with real-analytic boundary parametrizations ${\boldsymbol{\zeta}}=(\zeta_1^{\mathrm{D}},\ldots,\zeta_{{\mathfrak{b}}_{\mathrm{D}}}^{\mathrm{D}},\zeta_1^{{\mathrm{M_D}}},\ldots,\zeta_{{\mathfrak{b}}^{\mathrm{M_D}}}^{\mathrm{M_D}})$. Suppose ${\mathfrak{b}}^{\mathrm{D}}={\mathfrak{b}}^{{\mathrm{D}},+}+{\mathfrak{b}}^{{\mathrm{D}},-}$ where $\zeta_j^{\mathrm{D}}$ is outgoing for $j=1,\ldots,{\mathfrak{b}}^{{\mathrm{D}},+}$ and incoming for $j={\mathfrak{b}}^{{\mathrm{D}},+}+1,\ldots,{\mathfrak{b}}^{\mathrm{D}}$, and similarly for ${\mathfrak{b}}^{{\mathrm{M_D}}}={\mathfrak{b}}^{{\mathrm{M_D}},+}+{\mathfrak{b}}^{{\mathrm{M_D}},-}$. Let ${\mathbf{z}}=(z_1,\ldots,z_{\mathfrak{s}})$ be distinct marked points on $\Sigma^\circ$, ${\mathbf{v}}=(v_1,\ldots,v_{\mathfrak{s}})$ with $v_j\in T_{z_j}\Sigma\setminus\{0\}$ for each $j$, ${\boldsymbol{\alpha}}=(\alpha_1,\ldots,\alpha_{\mathfrak{s}})\in{\mathbb{R}}^{\mathfrak{s}}$ electric charges such that $\alpha_j>Q$, $\alpha_jR\in{\mathbb{Z}}$ for all $j$, and ${\mathbf{m}}=(m_1,\ldots,m_{\mathfrak{s}})\in{\mathbb{Z}}^{\mathfrak{s}}$ magnetic charges. Let ${\mathbf{x}}=(x_1,\ldots,x_{\mathfrak{t}})$ be distinct marked points on ${\widetilde{\partial}_{\mathrm{N}}}\Sigma\setminus{\widetilde{\partial}_{\mathrm{D}}}\Sigma$ and ${\boldsymbol{\eta}}=(\eta_1,\ldots,\eta_{\mathfrak{t}})\in{\mathbb{R}}^{\mathfrak{t}}$ boundary electric charges such that $\eta_j>Q$, $\frac{\eta_j}2R\in{\mathbb{Z}}$ for all $j$. Let $g$ be a Neumann extendible admissible metric on $\Sigma$. We have the amplitude operator ${\mathcal{A}}_{\Sigma,g,{\mathbf{v}},{\mathbf{x}},{\boldsymbol{\alpha}},{\mathbf{m}},{\boldsymbol{\eta}},{\boldsymbol{\zeta}}}:{\mathcal{H}}^{\otimes{\mathfrak{b}}^{{\mathrm{D}},-}}\otimes({\mathcal{H}}^+)^{\otimes{\mathfrak{b}}^{{\mathrm{M_D}},-}}\to{\mathcal{H}}^{\otimes{\mathfrak{b}}^{{\mathrm{D}},+}}\otimes({\mathcal{H}}^+)^{\otimes{\mathfrak{b}}^{{\mathrm{M_D}},+}}$ with ${\mathcal{H}}=L^2({\mathcal{D}}'({\mathbb{T}},{\mathbb{T}}_R))$, ${\mathcal{H}}^+=L^2({\mathcal{D}}'({\mathbb{T}}^+,{\mathbb{T}}_R))$. Finally, let ${\rm w}$ be a Neumann extendible holomorphic vector field on $\Sigma$ (analytic up to the boundary). For each $j=1,\ldots,{\mathfrak{b}}^{\mathrm{D}}$, let ${\rm w}_j^{\mathrm{D}}:=(\zeta_j^{\mathrm{D}})^*{\rm w}=-\sum_{n\in{\mathbb{Z}}}w_{jn}^{\mathrm{D}} z^{n+1}\partial_z$, where we extend $\zeta_j^{\mathrm{D}}$ analytically so that ${\rm w}_j^{\mathrm{D}}$ is holomorphic on an open neighborhood of ${\mathbb{T}}$. Similarly, for each $j=1,\ldots,{\mathfrak{b}}^{\mathrm{M_D}}$, let ${\rm w}_j^{\mathrm{M_D}}:=(\zeta_j^{\mathrm{M_D}})^*{\rm w}=-\sum_{n\in{\mathbb{Z}}}w_{jn}^{\mathrm{M_D}} z^{n+1}\partial_z$, which is symmetric. Then the following identity holds:
\begin{align*}
0 &= \sum_{j=1}^{{\mathfrak{b}}^{{\mathrm{D}},+}}{\mathbf{H}}_{{\rm w}_j^{\mathrm{D}}}^{(j)}{\mathcal{A}}_\Sigma - \sum_{j=1}^{{\mathfrak{b}}^{{\mathrm{D}},-}}{\mathcal{A}}_\Sigma{\mathbf{H}}_{{\rm w}_{{\mathfrak{b}}^{{\mathrm{D}},+}+j}^{\mathrm{D}}}^{(j)} + \sum_{j=1}^{{\mathfrak{b}}^{{\mathrm{M_D}},+}}{\mathbf{H}}_{{\rm w}_j^{\mathrm{M_D}}}^{+,(j)}{\mathcal{A}}_{\Sigma} - \sum_{j=1}^{{\mathfrak{b}}^{{\mathrm{M_D}},-}}{\mathcal{A}}_{\Sigma}{\mathbf{H}}_{{\rm w}_{{\mathfrak{b}}^{{\mathrm{M_D}},+}+j}^{\mathrm{M_D}}}^{+,(j)}\\
&\phantom{={}}+ \left(\sum_{j=1}^{{\mathfrak{s}}}\left(\Delta_{\alpha_j,m_j}(\operatorname{div}_gW)(z_j)+W_{\mathbf{v}}^{(j)}\right)+\sum_{j=1}^{{\mathfrak{t}}}\left(\frac{\Delta_{\eta_j}}{2}(\operatorname{div}_gW)(x_j)+W_{\mathbf{x}}^{(j)}\right)\right){\mathcal{A}}_{\Sigma} \\
&\phantom{={}}+ c_{\mathrm{L}}\left(-\sum_{j=1}^{{\mathfrak{b}}^{{\mathrm{D}},+}}\frac{\operatorname{Re} w_{j0}^{\mathrm{D}}}{12}+\sum_{j={\mathfrak{b}}^{{\mathrm{D}},+}+1}^{{\mathfrak{b}}^{\mathrm{D}}}\frac{\operatorname{Re} w_{j0}^{\mathrm{D}}}{12}-\sum_{j=1}^{{\mathfrak{b}}^{{\mathrm{M_D}},+}}\frac{w_{j0}^{{\mathrm{M_D}}}}{24}+\sum_{j={\mathfrak{b}}^{{\mathrm{M_D}},+}+1}^{{\mathfrak{b}}^{\mathrm{M_D}}}\frac{w_{j0}^{\mathrm{M_D}}}{24}-\frac{1}{96\pi}\int_\Sigma 2K_g\operatorname{div}_gW\,{\mathrm{d}} v_g\right){\mathcal{A}}_{\Sigma},
\end{align*}
where ${\mathcal{A}}_\Sigma:={\mathcal{A}}_{\Sigma,g,{\mathbf{v}},{\mathbf{x}},{\boldsymbol{\alpha}},{\mathbf{m}},{\boldsymbol{\eta}},{\boldsymbol{\zeta}}}$ for short and ${\mathbf{H}}_{{\rm w}}^{(j)},{\mathbf{H}}_{\rm w}^{+,(j)},W,W_{\mathbf{v}}^{(j)},W_{\mathbf{x}}^{(j)}$ are defined similarly to \cref{ward_cilt}.

\label{lem_App_1}
Let $N\geq0$. For $F,G\in{\mathcal{E}}({\mathcal{D}}'({\mathbb{T}},{\mathbb{T}}_R))$, we have
           \begin{equation*}
           \begin{split}
               \sup_{0<\delta<1}|\langle V^{(\delta)}_{\rm v} F,G\rangle_{L^2}|\leq {}&C\, (N+Q^2/2)^{\frac{\beta^2}{2}-1} \\
               &\sup_{\theta\in[0,2\pi]}|\operatorname{Re}(e^{-{\mathrm{i}}\theta}v(e^{{\mathrm{i}}\theta}))|\sqrt{(N\|F\|_{L^2}^2+\widetilde{\mathcal Q}^0(F,F))(N\|G\|_{L^2}^2+\widetilde{\mathcal Q}^0(G,G))},
           \end{split}
    \end{equation*}
where $C>0$ only depends on $\beta$. In particular, $V_{\rm v}$ extends to a bounded operator ${\mathcal{D}}(\widetilde{{\mathcal{Q}}}^0)\to{\mathcal{D}}'(\widetilde{{\mathcal{Q}}}^0)$.

All we need to prove is
\begin{equation}\label{eq_estimate_PVP}
    \|e^{-s\mathbf H^0}V^{(\delta)}_{\rm v} e^{-t\mathbf H^0}\|_{L^2\to L^2}\leq e^{\frac{Q^2-R^2k^2}{2}(s+t)}\,C_\beta \sup_{\theta\in[0,2\pi]}|\operatorname{Re}(e^{-{\mathrm{i}}\theta}v(e^{{\mathrm{i}}\theta}))|(1-e^{-s})^{-\frac{\beta^2}{4}}(1-e^{-t})^{-\frac{\beta^2}{4}}.
\end{equation}
Then using identity $(\mathbf H^0+\lambda)^{-\frac12}=\frac1{\sqrt{\pi}}\int_0^\infty t^{-\frac12}e^{-\lambda t} e^{-t\mathbf H^0}\,\mathrm{d}t$ when $\lambda$ is sufficiently large and Cauchy-Schwarz inequality would finish the proof. From now on we will only focus on \eqref{eq_estimate_PVP}.
Let $\widetilde{\varphi}^{\text{arc}}_\delta(\theta):=\frac{1}{2\delta}\int_{\theta-\delta}^{\theta+\delta}\widetilde{\varphi}(\theta'){\mathrm{d}}\theta'$. Denote by
\begin{equation*}
    T_{s,t,\delta}(\theta):=-e^{-s\mathbf H^0}e^{{\mathrm{i}}\beta\widetilde{\varphi}^{\text{arc}}_\delta(\theta)+\frac{\beta^2}{2}\mathbb E[(\varphi^{\text{arc}}_\delta)^2(\theta)]} e^{-t\mathbf H^0}\operatorname{Re}(e^{-{\mathrm{i}}\theta}v(e^{{\mathrm{i}}\theta})), \,\,\,\int_0^{2\pi}T_{s,t,\delta}(\theta)\,{\mathrm{d}}\theta=e^{-s\mathbf H^0}V^{(\delta)}_{\rm v} e^{-t\mathbf H^0}.
\end{equation*}
Now let us focus on $\|(T_{s,t,\delta}(\theta'))^* T_{s,t,\delta}(\theta)\|^{\frac12}_{L^2\to L^2}$. Denote by $\widetilde{\varphi}^k_t(\theta):=(P\widetilde{\varphi}^k+X_{\mathbb D})(e^{-t+{\mathrm{i}}\theta})$ the restriction of the GFF to a circle with radius $e^{-t}$. Now we take two i.i.d. Dirichlet GFFs $X_\mathbb D^1$ and $X_\mathbb D^2$ and we have $\widetilde{\varphi}^{k,j}_t(\theta):=(P\widetilde{\varphi}^k+X^j_{\mathbb D})(e^{-t+{\mathrm{i}}\theta}),\ j=1,2$. In fact, let
\begin{equation*}
    X_{g_0}(e^{-t+{\mathrm{i}}\theta}):=\widetilde{\varphi}^{k,1}_t(\theta),X_{g_0}(e^{t+{\mathrm{i}}\theta}):=\widetilde{\varphi}^{k,2}_t(\theta),\ t>0,\theta\in[0,2\pi].
\end{equation*}
which is the GFF on the sphere with a DOZZ metric $g_0=\frac {|{\mathrm{d}} z|^2}{1\vee |z|^4}$. Also define $\widetilde{\varphi}^{k,j}_{s,\delta}(\theta):=\frac{1}{2\delta}\int_{\theta-\delta}^{\theta+\delta}\widetilde{\varphi}^{k,j}_{s}(\theta')\,{\mathrm{d}}\theta'$. Then
\begin{equation*}
\begin{split}
    &\langle  T_{s,t,\delta}(\theta) F,T_{s,t,\delta}(\theta')G\rangle_{L^2}=e^{{(Q^2-R^2k^2)}(s+t)}\\
    &\int_0^{2\pi R}\operatorname{Re}(e^{-{\mathrm{i}}\theta}v(e^{{\mathrm{i}}\theta}))\operatorname{Re}(e^{-{\mathrm{i}}\theta'}v(e^{{\mathrm{i}}\theta'}))\mathbb E[e^{{\mathrm{i}}\beta\widetilde{\varphi}^{k,1}_{s,\delta}(\theta)+\frac{\beta^2}{2}\mathbb E[(\varphi^{\text{arc}}_\delta)^2(\theta)]}F(\widetilde{\varphi}^{k,1}_{s+t})e^{-{\mathrm{i}}\beta\widetilde{\varphi}^{k,2}_{s,\delta}(\theta')+\frac{\beta^2}{2}\mathbb E[(\varphi^{\text{arc}}_\delta)^2(\theta)]}\overline{G(\widetilde{\varphi}^{k,2}_{s+t})}]\,{\mathrm{d}} c.
\end{split}
\end{equation*}
Denote by $P(\widetilde{\varphi}^{k,1}_{s+t},\widetilde{\varphi}^{k,2}_{s+t})(z)$ the harmonic extension from $\widetilde{\varphi}^{k,1}_{s+t}(\theta)$ on $|z|=e^{-s-t}$ and $\widetilde{\varphi}^{k,2}_{s+t}(\theta)$ on $|z|=e^{s+t}$, to the annulus $e^{-s-t}\leq |z|\leq e^{s+t}$. By the domain Markov property, we can write $X_{g_0}(z)$ as $X_{g_0}=P(\widetilde{\varphi}^{k,1}_{s+t},\widetilde{\varphi}^{k,2}_{s+t})+X_{D,s+t}$ when $e^{-s-t}\leq |z|\leq e^{s+t}$, where $X_{D,s+t}$ is a Dirichlet GFF on $e^{-s-t}\leq |z|\leq e^{s+t}$ that is independent of $\widetilde{\varphi}^{k,1}_{s+t},\widetilde{\varphi}^{k,2}_{s+t}$.

Conditioning on $\widetilde{\varphi}^{k,1}_{s+t},\widetilde{\varphi}^{k,2}_{s+t}$, we have
\begin{equation}\label{eq_condi_robin}
    \begin{split}
        &\left|\mathbb E[e^{{\mathrm{i}}\beta\widetilde{\varphi}^{k,1}_{s,\delta}(\theta)+\frac{\beta^2}{2}\mathbb E[(\varphi^{\text{arc}}_\delta)^2(\theta)]}F(\widetilde{\varphi}^{k,1}_{s+t})e^{-{\mathrm{i}}\beta\widetilde{\varphi}^{k,2}_{s,\delta}(\theta')+\frac{\beta^2}{2}\mathbb E[(\varphi^{\text{arc}}_\delta)^2(\theta)]}\overline{G(\widetilde{\varphi}^{k,2}_{s+t})}|\widetilde{\varphi}^{k,1}_{s+t},\widetilde{\varphi}^{k,2}_{s+t}]\right|\\
        \leq{}&\left|F(\widetilde{\varphi}^{k,1}_{s+t})\overline{G(\widetilde{\varphi}^{k,2}_{s+t})}\right|e^{\beta^2\mathbb E[(\varphi^{\text{arc}}_\delta)^2(\theta)]-\frac{\beta^2}{2}\mathbb E[(\frac{1}{2\delta}\int_{\theta-\delta}^{\theta+\delta}X_{D,s+t}(e^{-s+{\mathrm{i}}\theta''})\,{\mathrm{d}}\theta''-\frac{1}{2\delta}\int_{\theta'-\delta}^{\theta'+\delta}X_{D,s+t}(e^{s+{\mathrm{i}}\theta''})\,{\mathrm{d}}\theta'')^2]}.
    \end{split}
\end{equation}
Denote by $G_{D,s+t}(\cdot,\cdot)$ the covariance kernel of $X_{D,s+t}$. To give a bound for \eqref{eq_condi_robin}, we check that
\begin{equation*}
\begin{split}
    &-\frac{\beta^2}{2}\mathbb E\left[\left(\frac{1}{2\delta}\int_{\theta-\delta}^{\theta+\delta}X_{D,s+t}(e^{-s+{\mathrm{i}}\theta''})\,{\mathrm{d}}\theta''-\frac{1}{2\delta}\int_{\theta'-\delta}^{\theta'+\delta}X_{D,s+t}(e^{s+{\mathrm{i}}\theta''})\,{\mathrm{d}}\theta''\right)^2\right]\\
    ={}&-\frac{\beta^2}{8\delta^2}\Bigg(\int_{\theta-\delta}^{\theta+\delta}\int_{\theta-\delta}^{\theta+\delta}G_{D,s+t}(e^{-s+{\mathrm{i}}\theta_1},e^{-s+{\mathrm{i}}\theta_2})\,{\mathrm{d}}\theta_1{\mathrm{d}}\theta_2+\int_{\theta'-\delta}^{\theta'+\delta}\int_{\theta'-\delta}^{\theta'+\delta}G_{D,s+t}(e^{s+{\mathrm{i}}\theta_1},e^{s+{\mathrm{i}}\theta_2})\,{\mathrm{d}}\theta_1{\mathrm{d}}\theta_2\\
    &\ \ \ \ \ \ \ \ \ \ \ \ \ -2\int_{\theta'-\delta}^{\theta'+\delta}\int_{\theta-\delta}^{\theta+\delta}G_{D,s+t}(e^{-s+{\mathrm{i}}\theta_1},e^{s+{\mathrm{i}}\theta_2})\,{\mathrm{d}}\theta_1{\mathrm{d}}\theta_2\Bigg),
\end{split}
\end{equation*}
\begin{lemma}\label{lemma_lowerB_DGreen}
    For $(2\pi)^{-1}G_{D,s+t}(\cdot,\cdot)$ the Dirichlet Green's function on $e^{-s-t}\leq |z|\leq e^{s+t}$, uniformly in $s,t\geq0,\delta<1,\theta\in[0,2\pi]$,
    \begin{equation*}
        \frac{1}{4\delta^2}\int_{\theta-\delta}^{\theta+\delta}\int_{\theta-\delta}^{\theta+\delta}G_{D,s+t}(e^{-s+{\mathrm{i}}\theta_1},e^{-s+{\mathrm{i}}\theta_2})\,{\mathrm{d}}\theta_1{\mathrm{d}}\theta_2\geq\mathbb E[(\varphi^{\text{arc}}_\delta)^2(\theta)]+\log|1-e^{-t}|+C,
    \end{equation*}
    where $C$ is independent of $s,t>0,\theta\in[0,2\pi],0<\delta<1$.
\end{lemma}
\begin{proof}
    Consider the Dirichlet Green's function $(2\pi)^{-1}G_{\theta,s,t}$ of a disk centered at $a=e^{-s+{\mathrm{i}}\theta}$ with radius $r=e^{-s}-e^{-s-t}$
\begin{equation*}
    G_{\theta,s,t}(x,y)=\log\left|\frac{r^2-(x-a)\overline{(y-a)}}{r(x-y)}\right|.
\end{equation*}
To study the integral, we need
\begin{equation*}
     G_{\theta,s,t}(e^{-s+{\mathrm{i}}\theta_1},e^{-s+{\mathrm{i}}\theta_2})=\log\left|\frac{(e^{-{\mathrm{i}}\theta_2}-e^{-{\mathrm{i}}\theta})(e^{{\mathrm{i}}\theta_1}-e^{{\mathrm{i}}\theta})-|1-e^{-t}|^2}{(1-e^{-t})(e^{{\mathrm{i}}\theta_1}-e^{{\mathrm{i}}\theta_2})}\right|.
\end{equation*}
Denote by $\delta_t:=\delta\wedge2\arcsin(\frac{1-e^{-t}}{2})$. Then
\begin{equation}\label{eq_bound_DGreen}
\begin{split}
     \frac{1}{4\delta^2}\int_{\theta-\delta}^{\theta+\delta}\int_{\theta-\delta}^{\theta+\delta}G_{D,s+t}(e^{-s+{\mathrm{i}}\theta_1},e^{-s+{\mathrm{i}}\theta_2})\,{\mathrm{d}}\theta_1{\mathrm{d}}\theta_2\geq{}&\frac{1}{4\delta^2}\int_{\theta-\delta_t}^{\theta+\delta_t}\int_{\theta-\delta_t}^{\theta+\delta_t}\log\left|\frac{(e^{-{\mathrm{i}}\theta_2}-e^{-{\mathrm{i}}\theta})(e^{{\mathrm{i}}\theta_1}-e^{{\mathrm{i}}\theta})}{|1-e^{-t}|^2}-1\right|\,{\mathrm{d}}\theta_1{\mathrm{d}}\theta_2\\
     +&\frac{\delta^2_t}{\delta^2}\log|1-e^{-t}|-\frac{1}{4\delta^2}\int_{\theta-\delta_t}^{\theta+\delta_t}\int_{\theta-\delta_t}^{\theta+\delta_t}\log|e^{{\mathrm{i}}\theta_1}-e^{{\mathrm{i}}\theta_2}|\,{\mathrm{d}}\theta_1{\mathrm{d}}\theta_2\\
     =:&I_1+\frac{\delta^2_t}{\delta^2}\log|1-e^{-t}|+I_2.
\end{split}
\end{equation}
We first compare the singular part $I_2$. That is
\begin{equation}\label{eq_bound_DGI2}
    I_2+\frac{1}{4\delta^2}\int_{\theta-\delta}^{\theta+\delta}\int_{\theta-\delta}^{\theta+\delta}\log|e^{{\mathrm{i}}\theta_1}-e^{{\mathrm{i}}\theta_2}|\,{\mathrm{d}}\theta_1{\mathrm{d}}\theta_2
    \geq\frac{\delta_t^2}{\delta^2}(-\log\delta_t-C)+\log\delta-C\geq-\frac{\delta_t^2}{\delta^2}\log\frac{\delta_t}\delta+(1-\frac{\delta_t^2}{\delta^2})\log\delta+C,
\end{equation}
where $C$ is independent of $\delta$ since $|\mathbb E[(\varphi^{\text{arc}}_\delta)^2(\theta)]+\log\delta|$ is bounded uniformly in $\delta$ small. 

Next, since $e^{{\mathrm{i}}\theta_1}-1=2{\mathrm{i}} e^{{\mathrm{i}}\frac{\theta_1}2}\sin(\frac{\theta_1}2)$, we have
\begin{equation*}
    \left|\frac{(e^{-{\mathrm{i}}\theta_2}-1)(e^{{\mathrm{i}}\theta_1}-1)}{|1-e^{-t}|^2}-1\right|\geq\left|\cos\left(\frac{\theta_1-\theta_2}{2}\right)\frac{4\sin\left(\frac{\theta_1}2\right)\sin\left(\frac{\theta_2}2\right)}{|1-e^{-t}|^2}-1\right|.
\end{equation*}
Therefore
\begin{equation*}
\begin{split}
     I_1={}&\frac{1}{4\delta^2}\int_{-\delta_t}^{\delta_t}\int_{-\delta_t}^{\delta_t}\log\left|\frac{(e^{-{\mathrm{i}}\theta_2}-1)(e^{{\mathrm{i}}\theta_1}-1)}{|1-e^{-t}|^2}-1\right|\,{\mathrm{d}}\theta_1{\mathrm{d}}\theta_2\\
     \geq{}&\frac{1}{2\delta^2}\int_{0}^{\delta_t}\int_{0}^{\delta_t}\log\left|\cos\left(\frac{\theta_1-\theta_2}{2}\right)\frac{4\sin\left(\frac{\theta_1}2\right)\sin\left(\frac{\theta_2}2\right)}{|1-e^{-t}|^2}-1\right|\,{\mathrm{d}}\theta_1{\mathrm{d}}\theta_2+C\frac{\delta_t^2}{2\delta^2},
\end{split}
\end{equation*}
where we can replace $\int_{0}^{\delta_t}\int_{-\delta_t}^{0}\cdots{\mathrm{d}}\theta_1{\mathrm{d}}\theta_2$ with $C\delta_t^2$ because $\cos\left(\frac{\theta_1-\theta_2}{2}\right)\geq-\frac12$ (since $\delta_t\leq2\arcsin(\frac{1-e^{-t}}{2})\leq\frac{2\pi}{3}$). Now $I_1$ is further bounded by
\begin{equation*}
    I_1\geq\frac{1}{2\delta^2}\int_{0}^{\delta_t}\int_{0}^{\delta_t}\log\left|\frac{4\sin\left(\frac{\theta_1}2\right)\sin\left(\frac{\theta_2}2\right)}{|1-e^{-t}|^2}-1\right|\,{\mathrm{d}}\theta_1{\mathrm{d}}\theta_2.
\end{equation*}
Let $u=2\frac{\sin\left(\frac{\theta_1}2\right)}{1-e^{-t}},v=2\frac{\sin\left(\frac{\theta_2}2\right)}{1-e^{-t}}$, and
\begin{equation}\label{eq_DGI1}
\begin{split}
     I_1\geq{}&\frac{(1-e^{-t})^2}{2\delta^2}\int_0^{2\frac{\sin\left(\frac{\delta_t}2\right)}{1-e^{-t}}\wedge1}\int_0^{2\frac{\sin\left(\frac{\delta_t}2\right)}{1-e^{-t}}\wedge1}\log|1-uv|\,\frac{{\mathrm{d}} u{\mathrm{d}} v}{\sqrt{1-\left(\frac{1-e^{-t}}{2}u\right)^2}\sqrt{1-\left(\frac{1-e^{-t}}{2}v\right)^2}}\\
     \geq{}&\frac23\int_0^{1}\int_0^{1}\log|1-uv|\,{{\mathrm{d}} u{\mathrm{d}} v}\geq C.
\end{split}
\end{equation}
Finally with \eqref{eq_bound_DGI2} and \eqref{eq_DGI1} we get back to \eqref{eq_bound_DGreen}, which is greater than
\begin{equation*}
    I_1+\frac{\delta^2_t}{\delta^2}\log|1-e^{-t}|+I_2\geq \mathbb E[(\varphi^{\text{arc}}_\delta)^2(\theta)]+\log|1-e^{-t}|+(1-\frac{\delta_t^2}{\delta^2})\log\frac{\delta}{|1-e^{-t}|}-\frac{\delta_t^2}{\delta^2}\log\frac{\delta_t}{\delta}+C,
\end{equation*}
where $(1-\frac{\delta_t^2}{\delta^2})\log\frac{\delta}{|1-e^{-t}|}$ is positive (when $\delta>\delta_t$, use $\arcsin x\geq x$).
\end{proof}
\begin{lemma}\label{lemma_upper_Green_DOZZ}
    \begin{equation*}
        -\frac{1}{4\delta^2}\int_{-\delta}^{\delta}\int_{-\delta}^{\delta}\log|e^{-2s+{\mathrm{i}}(\theta-\theta'+\theta_1-\theta_2)}-1|\,{\mathrm{d}}\theta_1{\mathrm{d}}\theta_2\leq-\log|e^{{\mathrm{i}}\theta}-e^{{\mathrm{i}}\theta'}|+C,
    \end{equation*}
    with $C$ independent of $\theta,\theta'\in[0,2\pi],s>0,0<\delta<1$.
\end{lemma}
\begin{proof}
Since for $t\in\mathbb R$, $|e^{{\mathrm{i}} t}-1|\leq 2|e^{-2s+{\mathrm{i}} t}-1|$, we get
    \begin{equation*}
         -\frac{1}{4\delta^2}\int_{-\delta}^{\delta}\int_{-\delta}^{\delta}\log{|e^{-2s+{\mathrm{i}}(\theta-\theta'+\theta_1-\theta_2)}-1|}\,{\mathrm{d}}\theta_1{\mathrm{d}}\theta_2\leq  -\frac{1}{4\delta^2}\int_{-\delta}^{\delta}\int_{-\delta}^{\delta}\log{|e^{{\mathrm{i}}(\theta-\theta'+\theta_1-\theta_2)}-1|}\,{\mathrm{d}}\theta_1{\mathrm{d}}\theta_2+C.
    \end{equation*}
    Let $u=\theta_1-\theta_2,v=\theta_1+\theta_2$. Then
    \begin{equation*}
         -\frac{1}{4\delta^2}\int_{-\delta}^{\delta}\int_{-\delta}^{\delta}\log{|e^{{\mathrm{i}}(\theta-\theta'+\theta_1-\theta_2)}-1|}\,{\mathrm{d}}\theta_1{\mathrm{d}}\theta_2= -\frac{1}{4\delta^2}\int_{-2\delta}^{2\delta}(2\delta-|u|)\log{|e^{{\mathrm{i}}(\theta-\theta'+u)}-1|}\,{\mathrm{d}} u.
    \end{equation*}
We only need to deal with $\delta$ sufficiently small. Note that $|e^{{\mathrm{i}}(\theta-\theta'+u)}-1|^2=4\sin^2(\frac{\theta-\theta'+u}{2})$. Define $|t|_{2\pi}:=\operatorname{dist}(t,2\pi\mathbb Z)\in[0,\pi]$, then by $\frac{2t}{\pi}\leq\sin t\leq t$ on $[0,\frac\pi2]$, we have
\begin{equation*}
   \log\frac{1}{|\theta-\theta'+u|_{2\pi}} \leq -\log{|e^{{\mathrm{i}}(\theta-\theta'+u)}-1|}\leq \log\frac{\pi}{2|\theta-\theta'+u|_{2\pi}}.
\end{equation*}
Therefore, from now on we only need to compare $|\theta-\theta'+u|_{2\pi}$ with $|\theta-\theta'|_{2\pi}$. When $|\theta-\theta'|_{2\pi}\geq4\delta$, $|\theta-\theta'+u|_{2\pi}\geq|\theta-\theta'|_{2\pi}/2$ provides an upper bound. And when $|\theta-\theta'|_{2\pi}\leq4\delta$, we claim that
\begin{equation*}
     -\frac{1}{4\delta^2}\int_{-2\delta}^{2\delta}(2\delta-|u|)\log{\left|\sin\left(\frac{\theta-\theta'+u}{2}\right)\right|}\,{\mathrm{d}} u\leq-\log\delta+C\leq-\log|\theta-\theta'|_{2\pi}+C.
\end{equation*}
We only prove the first inequality as the second one is straightforward. First, by Fubini's theorem,
\begin{equation*}
   - \int_{-2\delta}^{2\delta}\frac{2\delta-|u|}{4\delta^2}\log{\left|\sin\left(\frac{\theta-\theta'+u}{2}\right)\right|}\,{\mathrm{d}} u=\int_0^{\infty}\int_{-2\delta}^{2\delta}\textbf{1}_{\{-\log{\left|\sin\left(\frac{\theta-\theta'+u}{2}\right)\right|}>\tau\}}\frac{2\delta-|u|}{4\delta^2}\,{\mathrm{d}} u\,{\mathrm{d}}\tau.
\end{equation*}
Assume $|\theta-\theta'|=|\theta-\theta'|_{2\pi}$ (or choose a representative modulo $2\pi$). Denote by $A(\tau):=\{u:-\log{\left|\sin\left(\frac{\theta-\theta'+u}{2}\right)\right|}>\tau,|\theta-\theta'+u|
\leq\pi\}$, then (since $\delta<\frac\pi6$)
\begin{equation*}    \int_{-2\delta}^{2\delta}\textbf{1}_{A(\tau)}\frac{2\delta-|u|}{4\delta^2}\,{\mathrm{d}} u\leq\frac1{2\delta}\min(\int_{|\theta-\theta'+u|\leq\delta}\,{\mathrm{d}} u,\int_{A(\tau)}\,{\mathrm{d}} u)=\frac{1}{2\delta}\int_{A(\tau)\cap\{|\theta-\theta'+u|\leq\delta\}}\,{\mathrm{d}} u.
\end{equation*}
Hence we conclude that
\begin{equation*}
\begin{split}
    -\int_{-2\delta}^{2\delta}\frac{2\delta-|u|}{4\delta^2}\log{\left|\sin\left(\frac{\theta-\theta'+u}{2}\right)\right|}\,{\mathrm{d}} u\leq{}&-\frac{1}{2\delta}\int_{\{|\theta-\theta'+u|\leq\delta\}}\log{\left|\sin\left(\frac{\theta-\theta'+u}{2}\right)\right|}\,{\mathrm{d}} u\\
    \leq{}&\frac{1}{\delta}\int_0^{\delta}\log\frac{\pi}{u}\,{\mathrm{d}} u\leq-\log\delta+C.\qedhere
\end{split}
\end{equation*}
\end{proof}
Using \cref{lemma_lowerB_DGreen}, \cref{lemma_upper_Green_DOZZ}, the invariance of $G_{D,s+t}$ under $z\to1/z$, and that $G_{D,s+t}$ is bounded by the covariance of $X_{g_0}$ $G_{g_0}(x,y)+\log2=\log\frac{(|x|\vee1)(|y|\vee1)}{|x-y|} +\log2$, we find \eqref{eq_condi_robin} is bounded by

\begin{equation*}
C\left|F(\widetilde{\varphi}^{k,1}_{s+t})\overline{G(\widetilde{\varphi}^{k,2}_{s+t})}\right|(1-e^{-t})^{-\beta^2}|e^{{\mathrm{i}}\theta}-e^{{\mathrm{i}}\theta'}|^{-\beta^2}.
\end{equation*}
This implies the operator norm of $(T_{s,t,\delta}(\theta'))^* T_{s,t,\delta}(\theta)$ is controlled by $Ce^{(Q^2-R^2k^2)(s+t)}\sup_{\theta\in[0,2\pi]}|\operatorname{Re}(e^{-{\mathrm{i}}\theta}v(e^{{\mathrm{i}}\theta}))|^2(1-e^{-t})^{-\beta^2}|e^{{\mathrm{i}}\theta}-e^{{\mathrm{i}}\theta'}|^{-\beta^2}$ by using Cauchy--Schwarz inequality and that $\widetilde{\varphi}^{k,1}_{s+t}$ has the same distribution as $\widetilde{\varphi}^{k}$. Therefore,
\begin{equation*}
\begin{split}
    M_1:={}&\sup_{\theta'\in[0,2\pi]}\int_{0}^{2\pi}\|(T_{s,t,\delta}(\theta'))^* T_{s,t,\delta}(\theta)\|^{\frac12}_{L^2\to L^2}\,{\mathrm{d}}\theta\\
    \leq{}& Ce^{\frac{Q^2-R^2k^2}{2}(s+t)}\sup_{\theta\in[0,2\pi]}|\operatorname{Re}(e^{-{\mathrm{i}}\theta}v(e^{{\mathrm{i}}\theta}))|(1-e^{-t})^{-\frac{\beta^2}2}\int_{0}^{2\pi}|e^{{\mathrm{i}}\theta}-1|^{-\frac{\beta^2}{2}}{\mathrm{d}}\theta<\infty.
\end{split}
\end{equation*}
Similarly, we have
\begin{equation*}
\begin{split}
    M_2:={}&\sup_{\theta'\in[0,2\pi]}\int_{0}^{2\pi}\|T_{s,t,\delta}(\theta') (T_{s,t,\delta}(\theta))^*\|^{\frac12}_{L^2\to L^2}\,{\mathrm{d}}\theta\\
    \leq {}&Ce^{\frac{Q^2-R^2k^2}{2}(s+t)}\sup_{\theta\in[0,2\pi]}|\operatorname{Re}(e^{-{\mathrm{i}}\theta}v(e^{{\mathrm{i}}\theta}))|(1-e^{-s})^{-\frac{\beta^2}2}\int_{0}^{2\pi}|e^{{\mathrm{i}}\theta}-1|^{-\frac{\beta^2}{2}}{\mathrm{d}}\theta<\infty
\end{split}
\end{equation*}
By using the continuous Cotlar-Stein lemma (see \cite{CALDERON1971}), we have
\begin{equation*}
\begin{split}
    &\left\| \int_0^{2\pi}T_{s,t,\delta}(\theta')\,{\mathrm{d}}\theta'\,\right\|_{L^2\to L^2}\leq\sqrt{M_1M_2}\\
    \leq{}&Ce^{\frac{Q^2-R^2k^2}{2}(s+t)}\sup_{\theta\in[0,2\pi]}|\operatorname{Re}(e^{-{\mathrm{i}}\theta}v(e^{{\mathrm{i}}\theta}))|(1-e^{-t})^{-\frac{\beta^2}4}(1-e^{-s})^{-\frac{\beta^2}4}\int_{0}^{2\pi}|e^{{\mathrm{i}}\theta}-1|^{-\frac{\beta^2}{2}}{\mathrm{d}}\theta.
\end{split}
\end{equation*}
This brings us back to \eqref{eq_estimate_PVP} and thus we have finished the proof.

\label{lemma_lowerB_DGreen}
    For $(2\pi)^{-1}G_{D,s+t}(\cdot,\cdot)$ the Dirichlet Green's function on $e^{-s-t}\leq |z|\leq e^{s+t}$, uniformly in $s,t\geq0,\delta<1,\theta\in[0,2\pi]$,
    \begin{equation*}
        \frac{1}{4\delta^2}\int_{\theta-\delta}^{\theta+\delta}\int_{\theta-\delta}^{\theta+\delta}G_{D,s+t}(e^{-s+{\mathrm{i}}\theta_1},e^{-s+{\mathrm{i}}\theta_2})\,{\mathrm{d}}\theta_1{\mathrm{d}}\theta_2\geq\mathbb E[(\varphi^{\text{arc}}_\delta)^2(\theta)]+\log|1-e^{-t}|+C,
    \end{equation*}
    where $C$ is independent of $s,t>0,\theta\in[0,2\pi],0<\delta<1$.

Consider the Dirichlet Green's function $(2\pi)^{-1}G_{\theta,s,t}$ of a disk centered at $a=e^{-s+{\mathrm{i}}\theta}$ with radius $r=e^{-s}-e^{-s-t}$
\begin{equation*}
    G_{\theta,s,t}(x,y)=\log\left|\frac{r^2-(x-a)\overline{(y-a)}}{r(x-y)}\right|.
\end{equation*}
To study the integral, we need
\begin{equation*}
     G_{\theta,s,t}(e^{-s+{\mathrm{i}}\theta_1},e^{-s+{\mathrm{i}}\theta_2})=\log\left|\frac{(e^{-{\mathrm{i}}\theta_2}-e^{-{\mathrm{i}}\theta})(e^{{\mathrm{i}}\theta_1}-e^{{\mathrm{i}}\theta})-|1-e^{-t}|^2}{(1-e^{-t})(e^{{\mathrm{i}}\theta_1}-e^{{\mathrm{i}}\theta_2})}\right|.
\end{equation*}
Denote by $\delta_t:=\delta\wedge2\arcsin(\frac{1-e^{-t}}{2})$. Then
\begin{equation}\label{eq_bound_DGreen}
\begin{split}
     \frac{1}{4\delta^2}\int_{\theta-\delta}^{\theta+\delta}\int_{\theta-\delta}^{\theta+\delta}G_{D,s+t}(e^{-s+{\mathrm{i}}\theta_1},e^{-s+{\mathrm{i}}\theta_2})\,{\mathrm{d}}\theta_1{\mathrm{d}}\theta_2\geq{}&\frac{1}{4\delta^2}\int_{\theta-\delta_t}^{\theta+\delta_t}\int_{\theta-\delta_t}^{\theta+\delta_t}\log\left|\frac{(e^{-{\mathrm{i}}\theta_2}-e^{-{\mathrm{i}}\theta})(e^{{\mathrm{i}}\theta_1}-e^{{\mathrm{i}}\theta})}{|1-e^{-t}|^2}-1\right|\,{\mathrm{d}}\theta_1{\mathrm{d}}\theta_2\\
     +&\frac{\delta^2_t}{\delta^2}\log|1-e^{-t}|-\frac{1}{4\delta^2}\int_{\theta-\delta_t}^{\theta+\delta_t}\int_{\theta-\delta_t}^{\theta+\delta_t}\log|e^{{\mathrm{i}}\theta_1}-e^{{\mathrm{i}}\theta_2}|\,{\mathrm{d}}\theta_1{\mathrm{d}}\theta_2\\
     =:&I_1+\frac{\delta^2_t}{\delta^2}\log|1-e^{-t}|+I_2.
\end{split}
\end{equation}
We first compare the singular part $I_2$. That is
\begin{equation}\label{eq_bound_DGI2}
    I_2+\frac{1}{4\delta^2}\int_{\theta-\delta}^{\theta+\delta}\int_{\theta-\delta}^{\theta+\delta}\log|e^{{\mathrm{i}}\theta_1}-e^{{\mathrm{i}}\theta_2}|\,{\mathrm{d}}\theta_1{\mathrm{d}}\theta_2
    \geq\frac{\delta_t^2}{\delta^2}(-\log\delta_t-C)+\log\delta-C\geq-\frac{\delta_t^2}{\delta^2}\log\frac{\delta_t}\delta+(1-\frac{\delta_t^2}{\delta^2})\log\delta+C,
\end{equation}
where $C$ is independent of $\delta$ since $|\mathbb E[(\varphi^{\text{arc}}_\delta)^2(\theta)]+\log\delta|$ is bounded uniformly in $\delta$ small. 

Next, since $e^{{\mathrm{i}}\theta_1}-1=2{\mathrm{i}} e^{{\mathrm{i}}\frac{\theta_1}2}\sin(\frac{\theta_1}2)$, we have
\begin{equation*}
    \left|\frac{(e^{-{\mathrm{i}}\theta_2}-1)(e^{{\mathrm{i}}\theta_1}-1)}{|1-e^{-t}|^2}-1\right|\geq\left|\cos\left(\frac{\theta_1-\theta_2}{2}\right)\frac{4\sin\left(\frac{\theta_1}2\right)\sin\left(\frac{\theta_2}2\right)}{|1-e^{-t}|^2}-1\right|.
\end{equation*}
Therefore
\begin{equation*}
\begin{split}
     I_1={}&\frac{1}{4\delta^2}\int_{-\delta_t}^{\delta_t}\int_{-\delta_t}^{\delta_t}\log\left|\frac{(e^{-{\mathrm{i}}\theta_2}-1)(e^{{\mathrm{i}}\theta_1}-1)}{|1-e^{-t}|^2}-1\right|\,{\mathrm{d}}\theta_1{\mathrm{d}}\theta_2\\
     \geq{}&\frac{1}{2\delta^2}\int_{0}^{\delta_t}\int_{0}^{\delta_t}\log\left|\cos\left(\frac{\theta_1-\theta_2}{2}\right)\frac{4\sin\left(\frac{\theta_1}2\right)\sin\left(\frac{\theta_2}2\right)}{|1-e^{-t}|^2}-1\right|\,{\mathrm{d}}\theta_1{\mathrm{d}}\theta_2+C\frac{\delta_t^2}{2\delta^2},
\end{split}
\end{equation*}
where we can replace $\int_{0}^{\delta_t}\int_{-\delta_t}^{0}\cdots{\mathrm{d}}\theta_1{\mathrm{d}}\theta_2$ with $C\delta_t^2$ because $\cos\left(\frac{\theta_1-\theta_2}{2}\right)\geq-\frac12$ (since $\delta_t\leq2\arcsin(\frac{1-e^{-t}}{2})\leq\frac{2\pi}{3}$). Now $I_1$ is further bounded by
\begin{equation*}
    I_1\geq\frac{1}{2\delta^2}\int_{0}^{\delta_t}\int_{0}^{\delta_t}\log\left|\frac{4\sin\left(\frac{\theta_1}2\right)\sin\left(\frac{\theta_2}2\right)}{|1-e^{-t}|^2}-1\right|\,{\mathrm{d}}\theta_1{\mathrm{d}}\theta_2.
\end{equation*}
Let $u=2\frac{\sin\left(\frac{\theta_1}2\right)}{1-e^{-t}},v=2\frac{\sin\left(\frac{\theta_2}2\right)}{1-e^{-t}}$, and
\begin{equation}\label{eq_DGI1}
\begin{split}
     I_1\geq{}&\frac{(1-e^{-t})^2}{2\delta^2}\int_0^{2\frac{\sin\left(\frac{\delta_t}2\right)}{1-e^{-t}}\wedge1}\int_0^{2\frac{\sin\left(\frac{\delta_t}2\right)}{1-e^{-t}}\wedge1}\log|1-uv|\,\frac{{\mathrm{d}} u{\mathrm{d}} v}{\sqrt{1-\left(\frac{1-e^{-t}}{2}u\right)^2}\sqrt{1-\left(\frac{1-e^{-t}}{2}v\right)^2}}\\
     \geq{}&\frac23\int_0^{1}\int_0^{1}\log|1-uv|\,{{\mathrm{d}} u{\mathrm{d}} v}\geq C.
\end{split}
\end{equation}
Finally with \eqref{eq_bound_DGI2} and \eqref{eq_DGI1} we get back to \eqref{eq_bound_DGreen}, which is greater than
\begin{equation*}
    I_1+\frac{\delta^2_t}{\delta^2}\log|1-e^{-t}|+I_2\geq \mathbb E[(\varphi^{\text{arc}}_\delta)^2(\theta)]+\log|1-e^{-t}|+(1-\frac{\delta_t^2}{\delta^2})\log\frac{\delta}{|1-e^{-t}|}-\frac{\delta_t^2}{\delta^2}\log\frac{\delta_t}{\delta}+C,
\end{equation*}
where $(1-\frac{\delta_t^2}{\delta^2})\log\frac{\delta}{|1-e^{-t}|}$ is positive (when $\delta>\delta_t$, use $\arcsin x\geq x$).

