    \|e^{-s\mathbf H^{+,0}}V_{\rm v}^{\cap,(\delta)} e^{-t\mathbf H^{+,0}}\|_{L^2\to L^2}\leq e^{\frac{Q^2}{4}(s+t)}\,C_\beta \sup_{\theta\in[0,2\pi]}|\operatorname{Re}(e^{-{\mathrm{i}}\theta}v(e^{{\mathrm{i}}\theta}))|(1-e^{-s})^{-\frac{\beta^2}{4}}(1-e^{-t})^{-\frac{\beta^2}{4}}.
