\begin{lemma}\label{lem_AI3}
    Suppose $(2\pi)^{-1}G$ is the Dirichlet Green's function on the annulus $\mathbb A_{q}:=q<|z|<1$. Then when $z_1,\cdots,z_N\in\mathbb A_q\cap\mathbb H$, for $c_1,\cdots,c_N\in\mathbb R$
    \begin{equation*}
       \sum_{j,l}c_jc_lG(z_j,\bar z_l)\geq 0,
    \end{equation*}
    i.e. $G(z,\bar w)$ is positive definite.
\end{lemma}
\begin{proof}
For $z,w\in\mathbb A_q\cap\mathbb H$, define
\begin{equation*}
    H:=\sum_jc_jG(\cdot,\bar z_j),\ \ \ \check H:=\sum_jc_jG(\cdot,  z_j).
\end{equation*}
Using Green's first identity on $\mathbb A_q\cap\mathbb H$, we have
\begin{equation*}
    \int_{\mathbb A_q\cap\mathbb H}|\nabla H|^2\,{\mathrm{d}} x=\int_{\mathbb A_q\cap\mathbb R}H\partial_n H\,{\mathrm{d}} x,
\end{equation*}
with $\partial_n H$ the normal derivative.

Now let $B(z_j,\varepsilon)$ be the closed ball centered at $z_j$ with radius $\varepsilon$. Set $A_\varepsilon^+:=(\mathbb A_q\cap\mathbb H)\backslash (\cup_j B(z_j,\varepsilon))$, where $\varepsilon$ is small enough so that $B(z_j,\varepsilon)\cap B(z_l,\varepsilon)=\varnothing$ whenever $j\not=l$. By Green's second identity on $A_\varepsilon^+$, we get
\begin{equation*}
    0=\int_{A_\varepsilon^+}H\Delta \check H-\check H\Delta  H\,{\mathrm{d}} x=\int_{\partial A_\varepsilon^+}H\partial_n \check H-\check H\partial_n  H\,{\mathrm{d}} x.
\end{equation*}
Since $H,\check H$ vanish on $\partial \mathbb A_q$, we study the integration on $\mathbb A_q\cap\mathbb R$ and $\partial B(z_j,\varepsilon)$.

On $\mathbb A_q\cap\mathbb R$, $H=\check H$ and $\partial_n H=-\partial_n \check H$. On $\partial B(z_j,\varepsilon)$, by the properties of Green's function, we have
\begin{equation*}
    \partial_n \check H=\frac{c_j}{\varepsilon}+O(1),\ \ \ \check H=c_j\log\frac{1}{\varepsilon}+O(1).
\end{equation*}
Hence
\begin{equation*}
   0= \int_{\partial A_\varepsilon^+}H\partial_n \check H-\check H\partial_n  H\,{\mathrm{d}} x=-2\int_{\mathbb A_q\cap\mathbb R}H\partial_n H\,{\mathrm{d}} x+2\pi \sum_j c_j H(z_j)+O(\varepsilon\log\frac{1}{\varepsilon}).
\end{equation*}
Let $\varepsilon\to0$, and we conclude that
\begin{equation*}
    \frac{1}{\pi}\int_{\mathbb A_q\cap\mathbb H}|\nabla H|^2\,{\mathrm{d}} x=\sum_j c_j H(z_j)=\sum_{j,l}c_jc_lG(z_j,\bar z_l)\geq0.\qedhere
\end{equation*}
\end{proof}
